				return e;
			if (this.ContentOffset + 1 >= this.ContentLength)
				return -1;
			switch (this.Content[this.ContentOffset++]) {
			case 189:
				e = this.Content[this.ContentOffset++];
				if (e >= 160 && e <= 191)
					return e;
				break;
			case 190:
				e = this.Content[this.ContentOffset++];
				if (e >= 128 && e <= 159)
					return e + 64;
				break;
			default:
				break;
			}
			return -1;
		}
	}

	class X68KPicStream : BitStream
