	class Mx1Stream : X68KPicStream
	{
		internal Mx1Stream()
		{
			int d = 0;
			for (int e = 0; e < 256; e++) {
				if ((e >= '!' && e <= '~' && e != '"' && e != '\'' && e != ',' && e != '@' && e != '\\' && e != '`') || (e >= 161 && e <= 200))
					this.DecodeTable[e] = (byte) d++;
				else
					this.DecodeTable[e] = 128;
			}
		}

		readonly byte[] DecodeTable = new byte[256];

		internal bool FindImage()
		{
			for (;;) {
				int lineOffset = this.ContentOffset;
				for (;;) {
					int c = ReadByte();
					if (c < 0)
						return false;
					if (c == '\r' || c == '\n')
						break;
				}
				if (this.ContentOffset - lineOffset >= 17 && RECOIL.IsStringAt(this.Content, lineOffset, "@@@ ") && RECOIL.IsStringAt(this.Content, this.ContentOffset - 11, "lines) @@@")) {
					this.Bits = 0;
					return true;
				}
			}
		}

		internal override int ReadBit()
		{
			if ((this.Bits & 63) == 0) {
				int e = ReadNl3Char(true);
				if (e < 0)
					return -1;
				int d = this.DecodeTable[e];
				if (d >= 128)
					return -1;
				this.Bits = d << 1 | 1;
			}
			else
				this.Bits <<= 1;
			return this.Bits >> 7 & 1;
		}
	}

