				return rgb << 5 | rgb << 2 | (rgb >> 1 & 197379);
			case 1:
				rgb = ReadBits(12);
				rgb = (rgb & 1792) << 9 | (rgb & 2160) << 5 | (rgb & 135) << 1 | (rgb & 8) >> 3;
				return rgb << 4 | rgb;
			case 3:
				return RECOIL.GetSteInterlacedColor(ReadBits(15));
			default:
				return 0;
			}
		}
