	class RastPalette : MultiPalette
	{

		internal int Colors;

		internal override void SetLinePalette(RECOIL recoil, int y)
		{
			int paletteLength = (1 + this.Colors) << 1;
			for (int offset = this.ContentOffset; offset <= this.ContentLength - paletteLength; offset += paletteLength) {
				if (y == (this.Content[offset] << 8 | this.Content[offset + 1])) {
					recoil.SetStPalette(this.Content, offset + 2, this.Colors);
					break;
				}
			}
		}
	}

	class HblPalette : MultiPalette
