		bool HasPalette(int row) { return this.Content[row << 1] != 255 || this.Content[row << 1 | 1] != 255; }

		internal bool Init()
		{
			if (!HasPalette(0))
				return false;
			this.ContentOffset = 896;
			for (int row = 1; row < 50; row++) {
				if (HasPalette(row))
					this.ContentOffset += 48;
			}
			return this.ContentOffset <= this.ContentLength;
		}

		internal override void SetLinePalette(RECOIL recoil, int y)
		{
			if ((y & 3) == 0 && HasPalette(y >> 2)) {
				this.ContentOffset -= 48;
				int bitplanes = recoil.GetWidth() == 320 || y == 0 ? 4 : 2;
				for (int c = 0; c < 1 << bitplanes; c++) {
					int offset = this.ContentOffset + c * 3;
					int rgb = (this.Content[offset] << 16 | this.Content[offset + 1] << 8 | this.Content[offset + 2]) & 460551;
					recoil.SetStVdiColor(c, rgb << 5 | rgb << 2 | (rgb >> 1 & 197379), bitplanes);
				}
			}
		}
	}

