			if ((this.HavePaletteChange[y >> 3] >> (~y & 7) & 1) == 0)
				return;
			int count = UnpackByte();
			if (count < 0)
				return;
			int count2 = UnpackByte();
			if (count2 < 0)
				return;
			if (this.Ocs) {
				SetOcsColors(recoil, 0, count);
				SetOcsColors(recoil, 16, count2);
			}
			else {
				count = count << 8 | count2;
				while (--count >= 0) {
					if (UnpackByte() != 0)
						return;
					int c = UnpackByte();
					if (c < 0 || UnpackByte() < 0)
						return;
					int r = UnpackByte();
					if (r < 0)
						return;
					int b = UnpackByte();
					if (b < 0)
						return;
					int g = UnpackByte();
					if (g < 0)
						return;
					recoil.ContentPalette[c] = r << 16 | g << 8 | b;
				}
			}
		}
	}

	/// <summary>Readable in-memory Run-Length-Encoded stream.</summary>
	/// <remarks>This class contains the compression logic.
	/// Subclasses must implement <c>ReadCommand()</c>
	/// and are allowed to override <c>ReadValue()</c>.</remarks>
	abstract class RleStream : BitStream
	{

		/// <summary>Block length.</summary>
		internal int RepeatCount = 0;

		/// <summary>Value for an RLE block, -1 for a block of literals.</summary>
		protected int RepeatValue;

		/// <summary>Decodes a block from the stream.</summary>
		/// <remarks>Fills <c>RepeatCount</c> with the length of the block.
		/// Sets <c>RepeatValue</c> to the RLE value
		/// or -1 if the block consists of <c>RepeatCount</c> literals.
		/// Returns <see langword="false" /> on end of stream.</remarks>
		protected abstract bool ReadCommand();

		internal virtual int ReadValue() { return ReadByte(); }

		/// <summary>Returns the next uncompressed byte or -1 on error.</summary>
		internal int ReadRle()
		{
			while (this.RepeatCount == 0) {
				if (!ReadCommand())
					return -1;
			}
			this.RepeatCount--;
			if (this.RepeatValue >= 0)
				return this.RepeatValue;
			return ReadValue();
		}

		/// <summary>Uncompresses bytes to <c>unpacked[unpackedOffset]</c>,
		/// <c>unpacked[unpackedOffset + unpackedStride]</c>,
		/// <c>unpacked[unpackedOffset + 2 * unpackedStride]</c>,
		/// ... as long as indexes are smaller than <c>unpackedEnd</c>.</summary>
		/// <remarks>Returns <see langword="true" /> on success, <see langword="false" /> on error.</remarks>
		internal bool Unpack(byte[] unpacked, int unpackedOffset, int unpackedStride, int unpackedEnd)
		{
			for (; unpackedOffset < unpackedEnd; unpackedOffset += unpackedStride) {
				int b = ReadRle();
				if (b < 0)
					return false;
				unpacked[unpackedOffset] = (byte) b;
			}
			return true;
		}

		/// <summary>Uncompresses laiding out bytes vertically column by column,
		/// <c>unpackedStride</c> being line width.</summary>
		/// <remarks>Returns <see langword="true" /> on success, <see langword="false" /> on error.</remarks>
		internal bool UnpackColumns(byte[] unpacked, int unpackedOffset, int unpackedStride, int unpackedEnd)
		{
			for (int x = 0; x < unpackedStride; x++) {
				if (!Unpack(unpacked, unpackedOffset + x, unpackedStride, unpackedEnd))
					return false;
			}
			return true;
		}

		/// <summary>Uncompresses bytes to <c>unpacked[unpackedOffset]</c>, <c>unpacked[unpackedOffset + 1]</c>,
		/// <c>unpacked[unpackedOffset + unpackedStride]</c>, <c>unpacked[unpackedOffset + unpackedStride + 1]</c>,
		/// <c>unpacked[unpackedOffset + 2 * unpackedStride]</c>, <c>unpacked[unpackedOffset + 2 * unpackedStride + 1]</c>,
		/// ... as long as indexes are smaller than <c>unpackedEnd</c>.</summary>
		/// <remarks>Returns <see langword="true" /> on success, <see langword="false" /> on error.</remarks>
		internal bool UnpackWords(byte[] unpacked, int unpackedOffset, int unpackedStride, int unpackedEnd)
		{
			for (; unpackedOffset < unpackedEnd; unpackedOffset += unpackedStride) {
				int b = ReadRle();
				if (b < 0)
					return false;
				unpacked[unpackedOffset] = (byte) b;
				b = ReadRle();
				if (b < 0)
					return false;
				unpacked[unpackedOffset + 1] = (byte) b;
			}
			return true;
		}

		/// <summary>Uncompresses writing first byte to <c>unpacked[unpackedEnd]</c>, <c>unpacked[unpackedEnd - 1]</c>, ...</summary>
		/// <remarks>until <c>unpacked[unpackedOffset]</c>.
		/// Returns <see langword="true" /> on success, <see langword="false" /> on error.</remarks>
		internal bool UnpackBackwards(byte[] unpacked, int unpackedOffset, int unpackedEnd)
		{
			while (unpackedEnd >= unpackedOffset) {
				int b = ReadRle();
				if (b < 0)
					return false;
				unpacked[unpackedEnd--] = (byte) b;
			}
			return true;
		}
	}

	class BldStream : RleStream
	{

		protected override bool ReadCommand()
		{
			int b = ReadByte();
			if (b < 0)
				return false;
			this.RepeatValue = b;
			if (b == 0 || b == 255) {
				b = ReadByte();
				if (b < 0)
					return false;
				this.RepeatCount = b + 1;
			}
			else
				this.RepeatCount = 1;
			return true;
		}
	}

	class BbgStream : RleStream
	{

		internal int ValueBits;

		internal int CountBits;

		/// <summary>Reads the requested number of bits and returns them
		/// as an unsigned integer with the first bit read as the least significant.</summary>
		/// <remarks>Returns -1 on end of stream.</remarks>
		internal int ReadBitsReverse(int count)
		{
			int result = 0;
			for (int i = 0; i < count; i++) {
				switch (ReadBit()) {
				case 0:
					break;
				case 1:
					result |= 1 << i;
					break;
				default:
					return -1;
				}
			}
			return result;
		}

		protected override bool ReadCommand()
		{
			switch (ReadBit()) {
			case 0:
				this.RepeatCount = 1;
				break;
			case 1:
				this.RepeatCount = ReadBitsReverse(this.CountBits);
				if (this.RepeatCount <= 0)
					return false;
				break;
			default:
				return false;
			}
			this.RepeatValue = ReadBitsReverse(this.ValueBits);
			return true;
		}
	}

	class MspStream : RleStream
	{

		protected override bool ReadCommand()
		{
			int b = ReadByte();
			if (b < 0)
				return false;
			if (b == 0) {
				this.RepeatCount = ReadByte();
				this.RepeatValue = ReadByte();
				return this.RepeatValue >= 0;
			}
			this.RepeatCount = b;
			this.RepeatValue = -1;
			return true;
		}
	}

	class C64KoalaStream : RleStream
	{

		protected override bool ReadCommand()
		{
			int b = ReadByte();
			if (b < 0)
				return false;
			if (b == 254) {
				this.RepeatValue = ReadByte();
				this.RepeatCount = ReadByte();
				return this.RepeatCount >= 0;
			}
			this.RepeatValue = b;
			this.RepeatCount = 1;
			return true;
		}
