			else
				this.RepeatCount = 1;
			this.RepeatValue = b;
			return b >= 0;
		}
	}

	class DrpStream : RleStream
	{

		internal int Escape;

		protected override bool ReadCommand()
		{
			int b = ReadByte();
			if (b == this.Escape) {
				this.RepeatCount = ReadByte();
				b = ReadByte();
			}
			else
				this.RepeatCount = 1;
			this.RepeatValue = b;
			return b >= 0;
		}

		internal static byte[] UnpackFile(byte[] content, int contentLength, string signature, byte[] unpacked, int unpackedLength)
		{
			if (contentLength > 16 && RECOIL.IsStringAt(content, 2, signature)) {
				DrpStream rle = new DrpStream { Content = content, ContentOffset = 16, ContentLength = contentLength, Escape = content[15] };
				return rle.Unpack(unpacked, 2, 1, unpackedLength) ? unpacked : null;
			}
			if (contentLength != unpackedLength)
				return null;
			return content;
		}
	}

	class HpmStream : RleStream
