		internal int Escape;

		protected override bool ReadCommand()
		{
			int b = ReadValue();
			if (b == this.Escape) {
				this.RepeatCount = ReadValue();
				if (this.RepeatCount == 0)
					this.RepeatCount = 256;
				b = ReadValue();
			}
			else
				this.RepeatCount = 1;
			this.RepeatValue = b;
			return b >= 0;
		}
	}

	class UifStream : UflStream
	{

		internal override int ReadValue()
		{
			if (this.ContentOffset <= 2)
				return -1;
			return this.Content[--this.ContentOffset];
		}

		internal bool StartSifFrame(int contentOffset)
		{
			if (contentOffset + 5 >= this.ContentLength)
				return false;
			int packedLength = this.Content[contentOffset] + (this.Content[contentOffset + 1] << 8) - 37890;
			if (packedLength <= 0 || contentOffset + 2 + packedLength > this.ContentLength)
				return false;
			this.ContentOffset = contentOffset + 2 + packedLength;
			this.Escape = this.Content[contentOffset + 2];
			return true;
		}
	}

	class PgcStream : RleStream
