			if (b < 0)
				return false;
			if (b < 128) {
				this.RepeatCount = b;
				this.RepeatValue = -1;
			}
			else {
				this.RepeatCount = b - 128;
				this.RepeatValue = ReadValue();
			}
			return true;
		}
	}

	class DaVinciStream : PgcStream
