	class VhiStream : RleStream
	{

		protected override bool ReadCommand()
		{
			int c;
			switch (ReadByte()) {
			case 0:
				c = ReadByte();
				this.RepeatValue = -1;
				break;
			case 1:
				c = ReadByte();
				this.RepeatValue = ReadByte();
				break;
			default:
				return false;
			}
			this.RepeatCount = c == 0 ? 256 : c;
			return true;
		}
	}

	class PrintfoxStream : RleStream
