		protected override bool ReadCommand()
		{
			int b = ReadByte();
			if (b == 155) {
				this.RepeatCount = ReadByte();
				if (this.Content[0] != 'P')
					this.RepeatCount += ReadByte() << 8;
				else if (this.RepeatCount == 0)
					this.RepeatCount = 256;
				b = ReadByte();
			}
			else
				this.RepeatCount = 1;
			this.RepeatValue = b;
			return b >= 0;
		}
	}

	class ArtMaster88Stream : RleStream
	{

		int Escape = -1;

		protected override bool ReadCommand()
		{
			int b = ReadByte();
			if (b < 0)
				return false;
			if (b == this.Escape) {
				b = ReadByte();
				if (b < 0)
					return false;
				this.RepeatCount = (b - 1) & 255;
				this.Escape = -1;
			}
			else {
				this.RepeatCount = 1;
				this.Escape = this.RepeatValue = b;
			}
			return true;
		}

		internal bool SkipChunk()
		{
			if (this.ContentOffset + 1 >= this.ContentLength)
				return false;
			int length = this.Content[this.ContentOffset] | this.Content[this.ContentOffset + 1] << 8;
			if (length < 2)
				return false;
			this.ContentOffset += length;
			return true;
		}

		internal readonly byte[][] Planes = Fu.NewArray(4, () => new byte[32000]);

		internal bool ReadPlanes(int planes, int planeLength)
		{
			for (int plane = 0; plane < planes; plane++) {
				if (!Unpack(this.Planes[plane], 0, 1, planeLength))
					return false;
			}
			return true;
		}
	}

	class SrStream : RleStream
	{

		protected override bool ReadCommand()
		{
			int b = ReadByte();
			switch (b) {
			case -1:
				return false;
			case 0:
				this.RepeatCount = ReadByte();
				if (this.RepeatCount == 0)
					this.RepeatCount = 256;
				this.RepeatValue = ReadByte();
				return true;
			case 1:
			case 2:
			case 3:
			case 4:
			case 5:
			case 6:
			case 7:
			case 8:
			case 9:
			case 10:
			case 11:
			case 12:
			case 13:
			case 14:
			case 15:
				this.RepeatCount = b;
				this.RepeatValue = ReadByte();
				return true;
			default:
				this.RepeatCount = 1;
				this.RepeatValue = b;
				return true;
			}
		}
	}

	class PacStream : RleStream
	{

		protected override bool ReadCommand()
		{
			int b = ReadByte();
			if (b < 0)
				return false;
			if (b == this.Content[4]) {
				b = ReadByte();
				if (b < 0)
					return false;
				this.RepeatCount = b + 1;
				this.RepeatValue = this.Content[5];
			}
			else if (b == this.Content[6]) {
				this.RepeatValue = ReadByte();
				if (this.RepeatValue < 0)
					return false;
				b = ReadByte();
				if (b < 0)
					return false;
				this.RepeatCount = b + 1;
			}
			else {
				this.RepeatCount = 1;
				this.RepeatValue = b;
			}
			return true;
		}
	}

	class Bdp4Stream : RleStream
	{

		protected override bool ReadCommand()
		{
			switch (ReadByte()) {
			case 255:
				this.RepeatCount = ReadByte();
				if (this.RepeatCount == 0)
					this.RepeatCount = 256;
				this.RepeatValue = ReadByte();
				return this.RepeatValue >= 0;
			case 254:
				int lo = ReadByte();
				int hi = ReadByte();
				if (hi < 0)
					return false;
				this.RepeatCount = lo | hi << 8;
				this.RepeatValue = -1;
				return true;
			default:
				return false;
			}
		}
	}

	class Bdp5Stream : RleStream
	{

		protected override bool ReadCommand()
		{
			int b = ReadByte();
			if (b == this.Content[10] || b == this.Content[11]) {
				this.RepeatCount = ReadByte();
				if (b == this.Content[11])
					this.RepeatCount |= ReadByte() << 8;
				else if (this.RepeatCount == 0)
					this.RepeatCount = 256;
				b = ReadByte();
			}
			else
				this.RepeatCount = 1;
			this.RepeatValue = b;
			return b >= 0;
		}
	}

	class XlpStream : RleStream
	{

		protected override bool ReadCommand()
		{
			int b = ReadByte();
			if (b < 0)
				return false;
			bool rle;
			if (b < 128)
				rle = false;
			else {
				b -= 128;
				rle = true;
			}
			this.RepeatCount = b;
			if (b >= 64) {
				b = ReadByte();
				if (b < 0)
					return false;
				this.RepeatCount = (this.RepeatCount - 64) << 8 | b;
			}
			this.RepeatValue = rle ? ReadByte() : -1;
			return true;
		}
	}

	class AmstradStream : RleStream
	{

		int BlockLength = 0;

		protected override bool ReadCommand()
		{
			while (this.BlockLength <= 0) {
				if (ReadByte() != 'M' || ReadByte() != 'J' || ReadByte() != 'H')
					return false;
				int lo = ReadByte();
				if (lo < 0)
					return false;
				int hi = ReadByte();
				if (hi < 0)
					return false;
				this.BlockLength = hi << 8 | lo;
			}
			int b = ReadByte();
			if (b < 0)
				return false;
			if (b == 1) {
				this.RepeatCount = ReadByte();
				if (this.RepeatCount == 0)
					this.RepeatCount = 256;
				this.RepeatValue = ReadByte();
			}
			else {
				this.RepeatCount = 1;
				this.RepeatValue = b;
			}
			this.BlockLength -= this.RepeatCount;
			return true;
		}

		internal static bool UnpackFile(byte[] content, int contentOffset, int contentLength, byte[] unpacked, int unpackedLength)
		{
			AmstradStream rle = new AmstradStream { Content = content, ContentOffset = contentOffset, ContentLength = contentLength };
			return rle.Unpack(unpacked, 0, 1, unpackedLength);
		}
	}

	class CpiStream : RleStream
	{

		protected override bool ReadCommand()
		{
			int b = ReadByte();
			if (b < 0)
				return false;
			if (this.ContentOffset + 1 < this.ContentLength && this.Content[this.ContentOffset] == b) {
				this.ContentOffset++;
				this.RepeatCount = 1 + this.Content[this.ContentOffset++];
			}
			else
				this.RepeatCount = 1;
			this.RepeatValue = b;
			return true;
		}
	}

	class VbmStream : RleStream
	{

		protected override bool ReadCommand()
		{
			int b = ReadByte();
			if (b == this.Content[9]) {
				this.RepeatValue = ReadByte();
				this.RepeatCount = ReadByte();
				return this.RepeatCount > 0;
			}
			if (b == this.Content[10]) {
				this.RepeatValue = 0;
				this.RepeatCount = ReadByte();
				return this.RepeatCount > 0;
			}
			if (b == this.Content[11]) {
				this.RepeatValue = 255;
				this.RepeatCount = ReadByte();
				return this.RepeatCount > 0;
			}
			if (b == this.Content[12]) {
				this.RepeatValue = 0;
				this.RepeatCount = 2;
				return true;
			}
			if (b == this.Content[13]) {
				this.RepeatValue = 255;
				this.RepeatCount = 2;
				return true;
			}
			this.RepeatValue = b;
			this.RepeatCount = 1;
			return true;
		}
	}

	class XeKoalaStream : RleStream
	{

		protected override bool ReadCommand()
		{
			int b = ReadByte();
			if (b < 0)
				return false;
			bool rle;
			if (b < 128)
				rle = true;
			else {
				b -= 128;
				rle = false;
			}
			if (b == 0) {
				int hi = ReadByte();
				if (hi < 0)
					return false;
				b = ReadByte();
				if (b < 0)
					return false;
				b |= hi << 8;
			}
			this.RepeatCount = b;
			this.RepeatValue = rle ? ReadByte() : -1;
			return true;
		}

		internal readonly byte[] Unpacked = new byte[7680];

		internal bool UnpackRaw(int type, int unpackedLength)
		{
			switch (type) {
			case 0:
				if (this.ContentLength - this.ContentOffset != unpackedLength)
					return false;
				Array.Copy(this.Content, this.ContentOffset, this.Unpacked, 0, unpackedLength);
				return true;
			case 1:
				for (int x = 0; x < 40; x++) {
					for (int unpackedOffset = x; unpackedOffset < 80; unpackedOffset += 40) {
						if (!Unpack(this.Unpacked, unpackedOffset, 80, unpackedLength))
							return false;
					}
				}
				return true;
			case 2:
				return Unpack(this.Unpacked, 0, 1, unpackedLength);
			default:
				return false;
			}
		}

		internal bool UnpackWrapped(int unpackedLength)
		{
			if (ReadByte() != 255 || ReadByte() != 128 || ReadByte() != 201 || ReadByte() != 199)
				return false;
			int offset = ReadByte();
			offset |= ReadByte() << 8;
			if (offset < 26 || ReadByte() != 1)
				return false;
			int type = ReadByte();
			this.ContentOffset++;
			if (ReadByte() != 0 || ReadByte() != 40 || ReadByte() != 0)
				return false;
			this.ContentOffset += 9;
			if (ReadByte() != 0)
				return false;
			this.ContentOffset += offset - 21;
			return UnpackRaw(type, unpackedLength);
		}
	}

	class ImgStream : RleStream
	{

		int PatternRepeatCount = 0;

		const int Keep = 256;

		internal int GetLineRepeatCount()
		{
			if (this.RepeatCount == 0 && this.ContentOffset < this.ContentLength - 4 && this.Content[this.ContentOffset] == 0 && this.Content[this.ContentOffset + 1] == 0 && this.Content[this.ContentOffset + 2] == 255) {
				this.ContentOffset += 4;
				return this.Content[this.ContentOffset - 1];
			}
			return 1;
		}

		protected override bool ReadCommand()
		{
			if (this.PatternRepeatCount > 1) {
				this.PatternRepeatCount--;
				this.RepeatCount = this.Content[6] << 8 | this.Content[7];
				this.ContentOffset -= this.RepeatCount;
				return true;
			}
			int b = ReadByte();
			switch (b) {
			case -1:
				return false;
			case 0:
				b = ReadByte();
				if (b < 0)
					return false;
				if (b == 0) {
					b = ReadByte();
					if (b < 0)
						return false;
					this.RepeatCount = b + 1;
					this.RepeatValue = 256;
					return true;
				}
				this.PatternRepeatCount = b;
				this.RepeatCount = this.Content[6] << 8 | this.Content[7];
				this.RepeatValue = -1;
				return true;
			case 128:
				this.RepeatCount = ReadByte();
				if (this.RepeatCount < 0)
					return false;
				if (this.RepeatCount == 0)
					this.RepeatCount = 256;
				this.RepeatValue = -1;
				return true;
			default:
				this.RepeatCount = b & 127;
				this.RepeatValue = b >= 128 ? 255 : 0;
				return true;
			}
		}

		internal bool UnpackLine(byte[] unpacked, int unpackedLength, int y)
		{
			for (int x = 0; x < unpackedLength; x++) {
				int b = ReadRle();
				if (b < 0)
					return false;
				if (b != 256)
					unpacked[x] = (byte) b;
				else if (y == 0)
					unpacked[x] = 0;
			}
			return true;
		}
	}

	class CaStream : RleStream
	{

		int Escape;

		int DefaultValue;

		protected override bool ReadCommand()
		{
			int b = ReadByte();
			if (b < 0)
				return false;
			if (b != this.Escape) {
				this.RepeatCount = 1;
				this.RepeatValue = b;
				return true;
			}
			int c = ReadByte();
			if (c < 0)
				return false;
			if (c == this.Escape) {
				this.RepeatCount = 1;
				this.RepeatValue = c;
				return true;
			}
			b = ReadByte();
			if (b < 0)
				return false;
			switch (c) {
			case 0:
				this.RepeatCount = b + 1;
				this.RepeatValue = ReadByte();
				break;
			case 1:
				c = ReadByte();
				if (c < 0)
					return false;
				this.RepeatCount = (b << 8) + c + 1;
				this.RepeatValue = ReadByte();
				break;
			case 2:
				if (b == 0)
					this.RepeatCount = 32000;
				else {
					c = ReadByte();
					if (c < 0)
						return false;
					this.RepeatCount = (b << 8) + c + 1;
				}
				this.RepeatValue = this.DefaultValue;
				break;
			default:
				this.RepeatCount = c + 1;
				this.RepeatValue = b;
				break;
			}
			return true;
		}

		internal bool UnpackCa(byte[] unpacked, int unpackedOffset)
		{
			if (this.ContentOffset > this.ContentLength - 4)
				return false;
			this.Escape = this.Content[this.ContentOffset];
			this.DefaultValue = this.Content[this.ContentOffset + 1];
			int unpackedStep = this.Content[this.ContentOffset + 2] << 8 | this.Content[this.ContentOffset + 3];
			if (unpackedStep >= 32000)
				return false;
			this.RepeatCount = 0;
			if (unpackedStep == 0) {
				this.RepeatCount = 32000;
				this.RepeatValue = this.DefaultValue;
				unpackedStep = 1;
			}
			this.ContentOffset += 4;
			return UnpackColumns(unpacked, unpackedOffset, unpackedStep, unpackedOffset + 32000);
		}

		internal static bool UnpackDel(byte[] content, int contentLength, byte[] unpacked, int blocks)
		{
			CaStream rle = new CaStream { Content = content, ContentOffset = blocks << 2 };
			if (rle.ContentOffset >= contentLength)
				return false;
			for (int block = 0; block < blocks; block++) {
				rle.ContentLength = rle.ContentOffset + RECOIL.Get32BigEndian(content, block << 2);
				if (rle.ContentLength > contentLength || rle.ContentLength < rle.ContentOffset || !rle.UnpackCa(unpacked, block * 32000))
					return false;
				rle.ContentOffset = rle.ContentLength;
			}
			if (blocks == 2) {
				rle.ContentLength = contentLength;
				return rle.UnpackCa(unpacked, 64000);
			}
			return true;
		}
	}

	class RgbStream : RleStream
	{

		internal override int ReadValue() { return ReadBits(12); }

		protected override bool ReadCommand()
		{
			int b = ReadBits(4);
			if (b < 0)
				return false;
			bool rle;
			if (b < 8)
				rle = true;
			else {
				b -= 8;
				rle = false;
			}
			if (b == 0) {
				b = ReadBits(4);
				if (b < 0)
					return false;
				b += 7;
			}
			if (rle) {
				this.RepeatValue = ReadValue();
				b++;
			}
			else
				this.RepeatValue = -1;
			this.RepeatCount = b;
			return true;
		}
	}

	abstract class TnyPcsStream : RleStream
	{

		protected bool ReadTnyCommand()
		{
			int b = ReadByte();
			if (b < 0)
				return false;
			if (b < 128) {
				if (b == 0 || b == 1) {
					if (this.ContentOffset >= this.ContentLength - 1)
						return false;
					this.RepeatCount = this.Content[this.ContentOffset] << 8 | this.Content[this.ContentOffset + 1];
					this.ContentOffset += 2;
				}
				else
					this.RepeatCount = b;
				this.RepeatValue = b == 1 ? -1 : ReadValue();
			}
			else {
				this.RepeatCount = 256 - b;
				this.RepeatValue = -1;
			}
			return true;
		}
	}

	class TnyStream : TnyPcsStream
	{

		internal int ValueOffset;

		internal int ValueLength;

		protected override bool ReadCommand() { return ReadTnyCommand(); }

		internal override int ReadValue()
		{
			if (this.ValueOffset + 1 >= this.ValueLength)
				return -1;
			int value = this.Content[this.ValueOffset] << 8 | this.Content[this.ValueOffset + 1];
			this.ValueOffset += 2;
			return value;
		}
	}

	class PcsStream : TnyPcsStream
	{

		int CommandCount;

		bool Palette;

		protected override bool ReadCommand()
		{
			if (this.CommandCount <= 0)
				return false;
			this.CommandCount--;
			return ReadTnyCommand();
		}

		internal override int ReadValue()
		{
			if (!this.Palette)
				return ReadByte();
			if (this.ContentOffset >= this.ContentLength - 1)
				return -1;
			int value = this.Content[this.ContentOffset] << 8 | this.Content[this.ContentOffset + 1];
			this.ContentOffset += 2;
			return value;
		}

		bool StartBlock()
		{
			if (this.ContentOffset >= this.ContentLength - 1)
				return false;
			this.CommandCount = this.Content[this.ContentOffset] << 8 | this.Content[this.ContentOffset + 1];
			this.ContentOffset += 2;
			return true;
		}

		bool EndBlock()
		{
			while (this.RepeatCount > 0 || this.CommandCount > 0) {
				if (ReadRle() < 0)
					return false;
			}
			return true;
		}

		internal const int UnpackedLength = 51136;

		internal bool UnpackPcs(byte[] unpacked)
		{
			this.Palette = false;
			if (!StartBlock() || !Unpack(unpacked, 0, 1, 32000) || !EndBlock())
				return false;
			this.Palette = true;
			if (!StartBlock())
				return false;
			for (int unpackedOffset = 32000; unpackedOffset < 51136; unpackedOffset += 2) {
				int b = ReadRle();
				if (b < 0)
					return false;
				unpacked[unpackedOffset] = (byte) (b >> 8);
				unpacked[unpackedOffset + 1] = (byte) b;
			}
			return EndBlock();
		}
	}

	class VdatStream : TnyStream
	{

		protected override bool ReadCommand()
		{
			int b = ReadByte();
			if (b < 0)
				return false;
			if (b < 128) {
				if (b == 0 || b == 1) {
					this.RepeatCount = ReadValue();
					if (this.RepeatCount < 0)
						return false;
				}
				else
					this.RepeatCount = b;
				this.RepeatValue = b == 0 ? -1 : ReadValue();
			}
			else {
				this.RepeatCount = 256 - b;
				this.RepeatValue = -1;
			}
			return true;
		}
	}

	class HimStream : RleStream
	{

		internal override int ReadValue()
		{
			if (this.ContentOffset < 18)
				return -1;
			return this.Content[this.ContentOffset--];
		}

		protected override bool ReadCommand()
		{
			int b = ReadValue();
			switch (b) {
			case -1:
				return false;
			case 0:
				this.RepeatCount = ReadValue();
				if (this.RepeatCount <= 0)
					return false;
				this.RepeatValue = ReadValue();
				return true;
			default:
				this.RepeatCount = b - 1;
				this.RepeatValue = -1;
				return true;
			}
		}
	}

	class IcStream : RleStream
	{

		bool ReadCount()
		{
			this.RepeatCount = 257;
			while (ReadByte() == 1)
				this.RepeatCount += 256;
			int b = ReadByte();
			if (b < 0)
				return false;
			this.RepeatCount += b;
			return true;
		}

		protected override bool ReadCommand()
		{
			int b = ReadByte();
			int escape = this.Content[66];
			if (b != escape) {
				this.RepeatCount = 1;
				this.RepeatValue = b;
				return true;
			}
			b = ReadByte();
			if (b == escape) {
				this.RepeatCount = 1;
				this.RepeatValue = b;
				return true;
			}
			switch (b) {
			case -1:
				return false;
			case 0:
				b = ReadByte();
				if (b < 0)
					return false;
				this.RepeatCount = b + 1;
				break;
			case 1:
				if (!ReadCount())
					return false;
				break;
			case 2:
				b = ReadByte();
				switch (b) {
				case -1:
					return false;
				case 0:
					this.RepeatCount = 32000;
					break;
				case 1:
					if (!ReadCount())
						return false;
					break;
				case 2:
					while (ReadByte() > 0) {
					}
					this.RepeatCount = 0;
					break;
				default:
					this.RepeatCount = b + 1;
					break;
				}
				this.RepeatValue = 0;
				return true;
			default:
				this.RepeatCount = b + 1;
				break;
			}
			this.RepeatValue = ReadByte();
			return true;
		}
	}

	class DeepStream : PackBitsStream
	{

		internal int Components = 0;

		readonly int[] ComponentShift = new int[6];

		int CurrentByte;

		internal int[] Line = null;

		internal bool SetDpel(int chunkOffset, int chunkLength)
		{
			if (chunkLength < 8 || this.Content[chunkOffset + 8] != 0 || this.Content[chunkOffset + 9] != 0 || this.Content[chunkOffset + 10] != 0)
				return false;
			this.Components = this.Content[chunkOffset + 11];
			if (this.Components > 6 || chunkLength != (this.Components + 1) << 2)
				return false;
			for (int c = 0; c < this.Components; c++) {
				int offset = chunkOffset + 12 + c * 4;
				if (this.Content[offset] != 0 || this.Content[offset + 2] != 0 || this.Content[offset + 3] != 8)
					return false;
				int shift;
				switch (this.Content[offset + 1]) {
				case 1:
					shift = 16;
					break;
				case 2:
					shift = 8;
					break;
				case 3:
					shift = 0;
					break;
				case 4:
				case 9:
				case 10:
				case 11:
				case 17:
					shift = -1;
					break;
				default:
					return false;
				}
				this.ComponentShift[c] = shift;
			}
			return true;
		}

		internal override int ReadValue()
		{
			int rgb = 0;
			for (int c = 0; c < this.Components; c++) {
				int b = ReadByte();
				if (b < 0)
					return -1;
				int shift = this.ComponentShift[c];
				if (shift >= 0)
					rgb |= b << shift;
			}
			return rgb;
		}

		int ReadNibble()
		{
			if (this.CurrentByte < 0) {
				this.CurrentByte = ReadByte();
				if (this.CurrentByte < 0)
					return -1;
				return this.CurrentByte >> 4;
			}
			int result = this.CurrentByte & 15;
			this.CurrentByte = -1;
			return result;
		}

		internal bool ReadDeltaLine(int width, int tvdcOffset)
		{
			if (this.Line == null)
				this.Line = new int[width];
			for (int c = 0; c < this.Components; c++) {
				int count = 0;
				int value = 0;
				this.CurrentByte = -1;
				for (int x = 0; x < width; x++) {
					if (count == 0) {
						int i = ReadNibble();
						if (i < 0)
							return false;
						int delta = this.Content[tvdcOffset + i * 2 + 1];
						if (delta == 0) {
							if (this.Content[tvdcOffset + i * 2] == 0) {
								count = ReadNibble();
								if (count < 0)
									return false;
							}
						}
						else
							value = (value + delta) & 255;
					}
					else
						count--;
					int rgb = c == 0 ? 0 : this.Line[x];
					int shift = this.ComponentShift[c];
					if (shift >= 0)
						rgb |= value << shift;
					this.Line[x] = rgb;
				}
			}
			return true;
		}
	}

	class PackBytesStream : Stream
	{

		int Count = 1;

		int Pattern = 0;

		internal int ReadUnpacked()
		{
			if (--this.Count == 0) {
				if (this.ContentOffset >= this.ContentLength)
					return -1;
				int b = this.Content[this.ContentOffset++];
				this.Count = (b & 63) + 1;
				if (b >= 128)
					this.Count <<= 2;
				this.Pattern = ReadUnpacked_patterns[b >> 6];
			}
			else if ((this.Count & (this.Pattern - 1)) == 0)
				this.ContentOffset -= this.Pattern;
			return ReadByte();
		}

		static readonly byte[] ReadUnpacked_patterns = { 0, 1, 4, 1 };
	}

	class Lz4Stream : Stream
	{

		internal byte[] Unpacked = null;

		internal int UnpackedOffset;

		internal int UnpackedLength;

		internal bool Copy(int count)
		{
			if (this.UnpackedOffset + count > this.UnpackedLength || !ReadBytes(this.Unpacked, this.UnpackedOffset, count))
				return false;
			this.UnpackedOffset += count;
			return true;
		}

		internal int ReadCount(int count)
		{
			if (count == 15) {
				int b;
				do {
					b = ReadByte();
					if (b < 0)
						return -1;
					count += b;
				}
				while (b == 255);
			}
			return count;
		}
	}

	class Tre1Stream : RleStream
	{

		int LastRgb = -1;

		protected override bool ReadCommand()
		{
			this.RepeatCount = ReadByte();
			if (this.RepeatCount <= 0)
				return false;
			if (this.RepeatCount == 255) {
				if (this.ContentOffset + 1 >= this.ContentLength)
					return false;
				this.RepeatCount = 255 + (this.Content[this.ContentOffset] << 8) + this.Content[this.ContentOffset + 1];
				this.ContentOffset += 2;
			}
			this.RepeatValue = this.LastRgb;
			this.LastRgb = -1;
			return true;
		}

		internal override int ReadValue()
		{
			if (this.ContentOffset + 1 >= this.ContentLength)
				return -1;
			this.LastRgb = RECOIL.GetFalconTrueColor(this.Content, this.ContentOffset);
			this.ContentOffset += 2;
			return this.LastRgb;
		}
	}

	class MciStream : RleStream
	{

		protected override bool ReadCommand()
		{
			if (this.ContentOffset < 2)
				return false;
			int b = this.Content[this.ContentOffset--];
			for (int e = 8; e >= 0; e--) {
				if (b == this.Content[129 + e]) {
					switch (this.Content[120 + e]) {
					case 0:
						this.RepeatCount = 2;
						this.RepeatValue = this.Content[133 + e];
						return true;
					case 7:
						if (this.ContentOffset < 2)
							return false;
						this.RepeatCount = 2 + this.Content[this.ContentOffset--];
						this.RepeatValue = this.Content[79];
						return true;
					case 11:
						this.RepeatCount = 3;
						this.RepeatValue = this.Content[79];
						return true;
					case 17:
						if (this.ContentOffset < 3)
							return false;
						this.RepeatCount = 2 + this.Content[this.ContentOffset--];
						this.RepeatValue = this.Content[this.ContentOffset--];
						return true;
					case 23:
						if (this.ContentOffset < 2)
							return false;
						this.RepeatCount = 3;
						this.RepeatValue = this.Content[this.ContentOffset--];
						return true;
					case 25:
						if (this.ContentOffset < 2)
							return false;
						b = this.Content[this.ContentOffset--];
						break;
					default:
						break;
					}
					break;
				}
			}
			this.RepeatCount = 1;
			this.RepeatValue = b;
			return true;
		}
	}

	class Nl3Stream : RleStream
	{

		internal override int ReadValue()
		{
			int e = ReadNl3Char(false);
			if (e < 32)
				return -1;
			if (e < 127)
				return e - 32;
			if (e < 160)
				return -1;
			if (e < 224)
				return e - 65;
			if (e == 253)
				return 159;
			if (e == 254)
				return 160;
			return -1;
		}

		protected override bool ReadCommand()
		{
			int b = ReadValue();
			if (b < 0 || b > 127)
				return false;
			this.RepeatValue = b & 63;
			if (b < 64)
				this.RepeatCount = 1;
			else {
				b = ReadValue();
				if (b < 0)
					return false;
				this.RepeatCount = b + 2;
			}
			return true;
		}
	}

	class SfdnStream : BitStream
	{

		internal bool Unpack(byte[] unpacked, int unpackedLength)
		{
			if (this.ContentLength < 22 + (unpackedLength >> 1) || !RECOIL.IsStringAt(this.Content, 0, "S101") || (this.Content[4] | this.Content[5] << 8) != unpackedLength)
				return false;
			this.ContentOffset = 22;
			int current = ReadBits(4);
			int hi = -1;
			for (int unpackedOffset = 0;;) {
				if (hi < 0)
					hi = current;
				else {
					unpacked[unpackedOffset++] = (byte) (hi << 4 | current);
					if (unpackedOffset >= unpackedLength)
						return true;
					hi = -1;
				}
				int code;
				int bit;
				for (code = 0;; code += 2) {
					bit = ReadBit();
					if (bit == 0)
						break;
					if (bit < 0 || code >= 14)
						return false;
				}
				bit = ReadBit();
				if (bit < 0)
					return false;
				code += bit;
				current = (current - this.Content[6 + code]) & 15;
			}
		}
	}

	class G9bStream : BitStream
	{

		const int BlockEnd = -2;

		int ReadLength()
		{
			for (int length = 1; length < 65536;) {
				switch (ReadBit()) {
				case 0:
					return length + 1;
				case 1:
					break;
				default:
					return -1;
				}
				length <<= 1;
				switch (ReadBit()) {
				case 0:
					break;
				case 1:
					length++;
					break;
				default:
					return -1;
				}
			}
			return -2;
		}

		internal bool Unpack(byte[] unpacked, int headerLength, int unpackedLength)
		{
			this.ContentOffset = headerLength + 3;
			for (int unpackedOffset = headerLength; unpackedOffset < unpackedLength;) {
				int b;
				switch (ReadBit()) {
				case 0:
					b = ReadByte();
					if (b < 0)
						return false;
					unpacked[unpackedOffset++] = (byte) b;
					break;
				case 1:
					int length = ReadLength();
					if (length == -2) {
						this.ContentOffset += 2;
						this.Bits = 0;
						break;
					}
					if (length < 0 || unpackedOffset + length > unpackedLength)
						return false;
					int distance = ReadByte();
					if (distance < 0)
						return false;
					if (distance >= 128) {
						b = ReadBits(4);
						if (b < 0)
							return false;
						distance += (b - 1) << 7;
					}
					distance++;
					if (unpackedOffset - distance < headerLength)
						return false;
					do {
						unpacked[unpackedOffset] = unpacked[unpackedOffset - distance];
						unpackedOffset++;
					}
					while (--length > 0);
					break;
				default:
					return false;
				}
			}
			return true;
		}
	}

	class MigStream : BitStream
	{

		internal const int MaxUnpackedLength = 108800;

		internal int Unpack(byte[] unpacked)
		{
			this.ContentOffset = 15;
			for (int unpackedOffset = 0; unpackedOffset < 108800;) {
				int c = ReadBit();
				if (c < 0)
					return -1;
				int b = ReadByte();
				if (b < 0)
					return -1;
				if (c == 0)
					unpacked[unpackedOffset++] = (byte) b;
				else {
					if (b >= 128) {
						c = ReadBits(4);
						if (c < 0)
							return -1;
						b += (c - 1) << 7;
					}
					int distance = b + 1;
					if (unpackedOffset - distance < 0)
						return -1;
					c = -1;
					do {
						b = ReadBit();
						if (b < 0)
							return -1;
						c++;
					}
					while (b != 0);
					int length = ReadBits(c);
					if (length < 0)
						return -1;
					if (c >= 16) {
						this.ContentOffset += 4;
						if (this.ContentOffset >= this.ContentLength)
							return unpackedOffset;
						this.Bits = 0;
					}
					else {
						length += (1 << c) + 1;
						if (unpackedOffset + length > 108800)
							return -1;
						do {
							unpacked[unpackedOffset] = unpacked[unpackedOffset - distance];
							unpackedOffset++;
						}
						while (--length > 0);
					}
				}
			}
			return -1;
		}
	}

	class Ice21Stream
	{

		internal byte[] Content = null;

		internal int ContentOffset;

		internal int ContentStart;

		protected int Bits;

		internal int GetUnpackedLength()
		{
			if (this.ContentStart + 16 > this.ContentOffset || !RECOIL.IsStringAt(this.Content, this.ContentStart, "Ice!") || RECOIL.Get32BigEndian(this.Content, this.ContentStart + 4) != this.ContentOffset - this.ContentStart)
				return -1;
			return RECOIL.Get32BigEndian(this.Content, this.ContentStart + 8);
		}

		protected int ReadBit()
		{
			int b = this.Bits;
			int next = b & 2147483647;
			if (next == 0) {
				this.ContentOffset -= 4;
				if (this.ContentOffset < this.ContentStart)
					return -1;
				b = RECOIL.Get32BigEndian(this.Content, this.ContentOffset);
				this.Bits = (b & 2147483647) << 1 | 1;
			}
			else
				this.Bits = next << 1;
			return b >> 31 & 1;
		}

		protected int ReadBits(int count)
		{
			int result = 0;
			while (--count >= 0) {
				int bit = ReadBit();
				if (bit < 0)
					return -1;
				result = result << 1 | bit;
			}
			return result;
		}

		int CountOnes(int max)
		{
			for (int result = 0; result < max; result++) {
				switch (ReadBit()) {
				case -1:
					return -1;
				case 0:
					return result;
				default:
					break;
				}
			}
			return max;
		}

		int ReadLiteralLength()
		{
			int o = 1;
			for (int n = 0;; n++) {
				int c = ReadLiteralLength_bits[n];
				int b = ReadBits(c);
				if (b < 0)
					return -1;
				c = (1 << c) - 1;
				if (b < c || n == 5)
					return o + b;
				o += c;
			}
		}

		int ReadEncoded(int maxCount, byte[] extraBits, int[] offsets)
		{
			int n = CountOnes(maxCount);
			if (n < 0)
				return -1;
			int b = ReadBits(extraBits[n]);
			if (b < 0)
				return -1;
			return offsets[n] + b;
		}

		internal bool Unpack(byte[] unpacked, int unpackedStart, int unpackedEnd)
		{
			this.ContentStart += 12;
			this.ContentOffset -= 4;
			this.Bits = RECOIL.Get32BigEndian(this.Content, this.ContentOffset);
			for (int unpackedOffset = unpackedEnd; unpackedOffset > unpackedStart;) {
				int length;
				switch (ReadBit()) {
				case -1:
					return false;
				case 1:
					length = ReadLiteralLength();
					if (length < 0)
						return false;
					if (length > unpackedOffset - unpackedStart)
						length = unpackedOffset - unpackedStart;
					this.ContentOffset -= length;
					if (this.ContentOffset < this.ContentStart)
						return false;
					unpackedOffset -= length;
					Array.Copy(this.Content, this.ContentOffset, unpacked, unpackedOffset, length);
					if (unpackedOffset == unpackedStart)
						return true;
					break;
				default:
					break;
				}
				length = ReadEncoded(4, Unpack_lengthExtraBits, Unpack_lengthOffsets);
				int offset;
				switch (length) {
				case -1:
					return false;
				case 0:
					switch (ReadBit()) {
					case -1:
						return false;
					case 0:
						offset = ReadBits(6);
						if (offset < 0)
							return false;
						break;
					default:
						offset = ReadBits(9);
						if (offset < 0)
							return false;
						offset += 64;
						break;
					}
					break;
				default:
					offset = ReadEncoded(2, Unpack_offsetExtraBits, Unpack_offsetOffsets);
					if (offset < 0)
						return false;
					break;
				}
				length += 2;
				offset += length;
				if (unpackedOffset + offset > unpackedEnd)
					return false;
				if (length > unpackedOffset - unpackedStart)
					length = unpackedOffset - unpackedStart;
				unpackedOffset -= length;
				Array.Copy(unpacked, unpackedOffset + offset, unpacked, unpackedOffset, length);
			}
			return true;
		}

		static readonly byte[] ReadLiteralLength_bits = { 1, 2, 2, 3, 8, 15 };

		static readonly byte[] Unpack_lengthExtraBits = { 0, 0, 1, 2, 10 };

		static readonly int[] Unpack_lengthOffsets = { 0, 1, 2, 4, 8 };

		static readonly byte[] Unpack_offsetExtraBits = { 8, 5, 12 };

		static readonly int[] Unpack_offsetOffsets = { 32, 0, 288 };
	}

	class SpxStream : Ice21Stream
	{

		int ReadCount()
		{
			int b = ReadBits(2);
			if (b < 0)
				return -1;
			return ReadBits((b + 1) << 2);
		}

		internal bool UnpackV2(byte[] unpacked, int unpackedLength)
		{
			this.Bits = 0;
			for (int unpackedOffset = unpackedLength; unpackedOffset > 0;) {
				int count;
				switch (ReadBit()) {
				case -1:
					return false;
				case 0:
					count = ReadCount();
					if (count <= 0)
						return false;
					if (count > unpackedOffset)
						count = unpackedOffset;
					for (int i = 0; i < count; i++) {
						int b = ReadBits(8);
						if (b < 0)
							return false;
						unpacked[--unpackedOffset] = (byte) b;
					}
					if (unpackedOffset == 0)
						return true;
					if (count == 65535)
						continue;
					break;
				default:
					break;
				}
				int distance = ReadCount();
				if (distance <= 0 || unpackedOffset + distance > unpackedLength)
					return false;
				count = ReadCount();
				if (count < 0)
					return false;
				count = Math.Min(count + 3, unpackedOffset);
				do {
					unpackedOffset--;
					unpacked[unpackedOffset] = unpacked[unpackedOffset + distance];
				}
				while (--count > 0);
			}
			return true;
		}
	}

	class Q4Stream : RleStream
	{

		internal int StartChunk()
		{
			if (this.ContentOffset + 6 > this.ContentLength)
				return -1;
			int chunkLength = this.Content[this.ContentOffset] | this.Content[this.ContentOffset + 1] << 8;
			this.ContentOffset += 6;
			this.ContentLength = this.ContentOffset + chunkLength;
			return this.ContentLength;
		}

		int CodeBits;

		int ReadCode()
		{
			do {
				int value = ReadBits(this.CodeBits);
				switch (value) {
				case -1:
				case 0:
					return -1;
				case 1:
					break;
				default:
					return value - 2;
				}
			}
			while (++this.CodeBits <= 15);
			return -1;
		}

		readonly byte[] Unpacked = new byte[65536];

		internal bool UnpackQ4()
		{
			this.Bits = 0;
			this.CodeBits = 3;
			int unpackedLength = 0;
			ushort[] offsets = new ushort[16384];
			for (int codes = 17; codes < 16384; codes++) {
				int code = ReadCode();
				if (code < 0 || code >= codes) {
					this.Content = this.Unpacked;
					this.ContentOffset = 0;
					this.ContentLength = unpackedLength;
					this.LastRepeatValue = 0;
					return true;
				}
				if (unpackedLength >= 65536)
					return false;
				offsets[codes] = (ushort) unpackedLength;
				if (code <= 16) {
					this.Unpacked[unpackedLength++] = (byte) code;
				}
				else {
					int sourceOffset = offsets[code];
					int endOffset = offsets[code + 1];
					if (unpackedLength + endOffset - sourceOffset >= 65536)
						return false;
					do
						this.Unpacked[unpackedLength++] = this.Unpacked[sourceOffset++];
					while (sourceOffset <= endOffset);
				}
			}
			return false;
		}

		int LastRepeatValue;

		protected override bool ReadCommand()
		{
			int b = ReadByte();
			if (b < 0)
				return false;
			if (b < 16) {
				this.RepeatCount = 1;
				this.RepeatValue = b;
				return true;
			}
			b = ReadByte();
			if (b == 0) {
				this.LastRepeatValue = ReadByte();
				if (this.LastRepeatValue < 0 || this.LastRepeatValue >= 16)
					return false;
				b = ReadByte();
			}
			if (b < 0)
				return false;
			this.RepeatCount = b * 17;
			b = ReadByte();
			if (b < 0)
				return false;
			this.RepeatCount += b;
			this.RepeatValue = this.LastRepeatValue;
			return true;
		}
	}

	class PiStream : BitStream
	{

		internal byte[] Indexes = null;

		readonly byte[] RecentColors = new byte[65536];

		int ReadInt(int bits, int maxBits)
		{
			for (; bits < maxBits; bits++) {
				int b = ReadBit();
				if (b == 0)
					break;
				if (b < 0)
					return -1;
			}
			return 1 << bits | ReadBits(bits);
		}

		bool UnpackLiteral(int indexesOffset, int depth)
		{
			int offset;
			switch (ReadBit()) {
			case 1:
				offset = ReadBit();
				break;
			case 0:
				offset = ReadInt(1, depth - 1);
				break;
			default:
				return false;
			}
			if (offset < 0)
				return false;
			int recentOffset = indexesOffset == 0 ? 0 : this.Indexes[indexesOffset - 1] << 8;
			offset += recentOffset;
			int c = this.RecentColors[offset];
			for (; offset > recentOffset; offset--)
				this.RecentColors[offset] = this.RecentColors[offset - 1];
			this.RecentColors[offset] = (byte) c;
			this.Indexes[indexesOffset] = (byte) c;
			return true;
		}

		bool UnpackTwoLiterals(int indexesOffset, int indexesLength, int depth)
		{
			if (!UnpackLiteral(indexesOffset, depth))
				return false;
			return indexesOffset + 1 >= indexesLength || UnpackLiteral(indexesOffset + 1, depth);
		}

		int ReadPosition()
		{
			int position = ReadBits(2);
			if (position != 3)
				return position;
			position = ReadBit();
			if (position < 0)
				return -1;
			return 3 + position;
		}

		internal bool Unpack(int width, int height, int depth)
		{
			int colors = 1 << depth;
			for (int i = 0; i < colors; i++)
				for (int j = 0; j < colors; j++)
					this.RecentColors[i << 8 | j] = (byte) ((i - j) & (colors - 1));
			int indexesLength = width * height;
			this.Indexes = new byte[indexesLength];
			if (!UnpackTwoLiterals(0, indexesLength, depth))
				return false;
			int lastPosition = -1;
			for (int indexesOffset = 0; indexesOffset < indexesLength;) {
				int position = ReadPosition();
				if (position < 0)
					return false;
				if (position == lastPosition) {
					do {
						if (!UnpackTwoLiterals(indexesOffset, indexesLength, depth))
							return false;
						indexesOffset += 2;
					}
					while (indexesOffset < indexesLength && ReadBit() == 1);
					lastPosition = -1;
				}
				else {
					int length = ReadInt(0, 23);
					if (length < 0)
						return false;
					lastPosition = position;
					switch (position) {
					case 0:
						position = indexesOffset == 0 ? 0 : indexesOffset - 2;
						position = this.Indexes[position] == this.Indexes[position + 1] ? 2 : 4;
						break;
					case 1:
						position = width;
						break;
					case 2:
						position = width << 1;
						break;
					case 3:
						position = width - 1;
						break;
					case 4:
						position = width + 1;
						break;
					default:
						throw new NotImplementedException();
					}
					int copyEnd = Math.Min(indexesOffset + (length << 1), indexesLength);
					for (; indexesOffset < copyEnd; indexesOffset++) {
						int sourceOffset = indexesOffset - position;
						if (sourceOffset < 0)
							sourceOffset &= 1;
						this.Indexes[indexesOffset] = this.Indexes[sourceOffset];
					}
				}
			}
			return true;
		}
	}

	class A4rStream : Stream
	{

		int OuterFlags = 0;

		int InnerFlags = 0;

		int ReadFlag()
		{
			if ((this.InnerFlags & 127) == 0) {
				if ((this.OuterFlags & 127) == 0) {
					if (this.ContentOffset >= this.ContentLength)
						return -1;
					this.OuterFlags = this.Content[this.ContentOffset++] << 1 | 1;
				}
				else
					this.OuterFlags <<= 1;
				if ((this.OuterFlags & 256) == 0)
					this.InnerFlags = 1;
				else {
					if (this.ContentOffset >= this.ContentLength)
						return -1;
					this.InnerFlags = this.Content[this.ContentOffset++] << 1 | 1;
				}
			}
			else
				this.InnerFlags <<= 1;
			return this.InnerFlags >> 8 & 1;
		}

		internal const int MinAddress = 19984;

		const int MaxAddress = 31231;

		const int UnpackedLength = 11248;

		internal readonly byte[] Unpacked = new byte[11248];

		int UnpackedOffset;

		bool CopyByte()
		{
			int b = ReadByte();
			if (b < 0 || this.UnpackedOffset < 0 || this.UnpackedOffset >= 11248)
				return false;
			this.Unpacked[this.UnpackedOffset++] = (byte) b;
			return true;
		}

		bool CopyBlock(int distance, int count)
		{
			if (this.UnpackedOffset < 0)
				return false;
			int nextOffset = this.UnpackedOffset + count;
			if (nextOffset > 11248 || !RECOIL.CopyPrevious(this.Unpacked, this.UnpackedOffset, distance, count))
				return false;
			this.UnpackedOffset = nextOffset;
			return true;
		}

		internal bool UnpackA4r()
		{
			Array.Clear(this.Unpacked, 0, 11248);
			this.UnpackedOffset = -1;
			for (;;) {
				switch (ReadFlag()) {
				case 0:
					if (!CopyByte())
						return false;
					break;
				case 1:
					int b = ReadByte();
					switch (b) {
					case -1:
						return false;
					case 0:
						if (this.ContentOffset >= this.ContentLength - 2)
							return false;
						b = ReadByte();
						this.UnpackedOffset = b + (ReadByte() << 8) + 128 - 19984;
						if (!CopyByte())
							return false;
						break;
					case 1:
						b = ReadByte();
						switch (b) {
						case -1:
							return false;
						case 0:
							return true;
						default:
							if (!CopyBlock(1, b + 2))
								return false;
							break;
						}
						break;
					default:
						if (!CopyBlock(128 - (b >> 1), 2 + (b & 1)))
							return false;
						break;
					}
					break;
				default:
					return false;
				}
			}
		}
	}

	class ZimStream : Stream
	{

		readonly byte[] Flags1 = new byte[1];

		internal readonly byte[] Flags2 = new byte[8];

		internal int ReadWord()
		{
			if (this.ContentOffset + 1 >= this.ContentLength)
				return -1;
			int result = this.Content[this.ContentOffset] | this.Content[this.ContentOffset + 1] << 8;
			this.ContentOffset += 2;
			return result;
		}

		internal int ReadUnpacked(byte[] flags, int unpackedOffset) { return (flags[unpackedOffset >> 3] >> (~unpackedOffset & 7) & 1) != 0 ? ReadByte() : 0; }

		internal bool Unpack(byte[] flags, byte[] unpacked, int unpackedLength)
		{
			bool enough = true;
			for (int unpackedOffset = 0; unpackedOffset < unpackedLength; unpackedOffset++) {
				int b = ReadUnpacked(flags, unpackedOffset);
				if (b < 0) {
					enough = false;
					b = 0;
				}
				unpacked[unpackedOffset] = (byte) b;
			}
			return enough;
		}

		internal bool UnpackFlags2()
		{
			int b = ReadByte();
			if (b < 0)
				return false;
			this.Flags1[0] = (byte) b;
			return Unpack(this.Flags1, this.Flags2, 8);
		}
	}

	class FanoTree
	{

		/// <summary>Count[n] == number of codes of bit length n.</summary>
		readonly int[] Count = new int[16];

		/// <summary>Values sorted by code length.</summary>
		readonly byte[] Values = new byte[256];

		internal void Create(byte[] content, int contentOffset, int codeCount)
		{
			Array.Clear(this.Count, 0, 16);
			for (int code = 0; code < codeCount; code++)
				this.Count[RECOIL.GetNibble(content, contentOffset, code)]++;
			int[] positions = new int[16];
			int position = 0;
			for (int bits = 0; bits < 16; bits++) {
				positions[bits] = position;
				position += this.Count[bits];
			}
			for (int code = 0; code < codeCount; code++)
				this.Values[positions[RECOIL.GetNibble(content, contentOffset, code)]++] = (byte) code;
		}

		internal int ReadCode(BitStream bitStream)
		{
			int code = 0;
			int valuesOffset = this.Count[0];
			for (int bits = 1; bits < 16; bits++) {
				int bit = bitStream.ReadBit();
				if (bit < 0)
					return -1;
				code = code << 1 | bit;
				int count = this.Count[bits];
				if (code < count)
					return this.Values[valuesOffset + code];
				code -= count;
				valuesOffset += count;
			}
			return -1;
		}
	}

	/// <summary>Dictionary of <c>Count</c> key-value pairs.</summary>
	/// <remarks>A key is an integer between zero and <c>Count-1</c>. A value is an int.
	/// The dictionary always contains exactly <c>Count</c> mappings. The values are initially all zeros.
	/// The pairs are ordered by their last usage, from Most Recently Used (MRU) to Least Recently Used (LRU).
	/// When you add or retrieve a value, it becomes the Most Recently Used.
	/// When you add a value, the Least Recently Used is discarded.</remarks>
	class RecentInts
	{
		internal RecentInts()
		{
			for (int i = 0; i < 128; i++) {
				this.Prev[i] = (byte) ((i + 1) & 127);
				this.Next[i] = (byte) ((i - 1) & 127);
			}
		}

		const int Count = 128;

		readonly int[] Value = new int[128];

		readonly byte[] Prev = new byte[128];

		readonly byte[] Next = new byte[128];

		int Head = 0;

		/// <summary>Store the value.</summary>
		/// <remarks>Will use the Least Recently Used key.
		/// Its previous value is discarded and now it maps to <c>value</c>
		/// and becomes the Most Recently Used.</remarks>
		internal void Add(int value)
		{
			this.Head = this.Prev[this.Head];
			this.Value[this.Head] = value;
		}

		/// <summary>Retrieve a value by key.</summary>
		internal int Get(int key)
		{
			if (key != this.Head) {
				int prev = this.Prev[key];
				int next = this.Next[key];
				this.Next[prev] = (byte) next;
				this.Prev[next] = (byte) prev;
				int tail = this.Prev[this.Head];
				this.Next[tail] = (byte) key;
				this.Prev[key] = (byte) tail;
				this.Prev[this.Head] = (byte) key;
				this.Next[key] = (byte) this.Head;
				this.Head = key;
			}
			return this.Value[key];
		}
	}

	class BlazingPaddlesBoundingBox
	{

		internal int Left;

		internal int Top;

		internal int Right;

		internal int Bottom;

		internal bool Calculate(byte[] content, int contentLength, int index, int startAddress)
		{
			index <<= 1;
			if (index + 1 >= contentLength)
				return false;
			int contentOffset = content[index] + (content[index + 1] << 8) - startAddress;
			if (contentOffset < 0)
				return false;
			this.Left = this.Top = this.Right = this.Bottom = 0;
			int x = 0;
			int y = 0;
			while (contentOffset < contentLength) {
				int control = content[contentOffset++];
				if (control == 8)
					return true;
				int len = (control >> 4) + 1;
				switch (control & 3) {
				case 0:
					x += len;
					if (this.Right < x)
						this.Right = x;
					break;
				case 1:
					x -= len;
					if (this.Left > x)
						this.Left = x;
					break;
				case 2:
					y -= len;
					if (this.Top > y)
						this.Top = y;
					break;
				case 3:
					y += len;
					if (this.Bottom < y)
						this.Bottom = y;
					break;
				default:
					throw new NotImplementedException();
				}
			}
			return false;
		}
	}

	class IcnParser : Stream
	{

		bool SkipWhitespaceAndComments()
		{
			bool got = false;
			while (this.ContentOffset < this.ContentLength) {
				switch (this.Content[this.ContentOffset]) {
				case (byte) ' ':
				case (byte) '\t':
				case (byte) '\r':
				case (byte) '\n':
					this.ContentOffset++;
					got = true;
					break;
				case (byte) '/':
					if (this.ContentOffset >= this.ContentLength - 3 || this.Content[this.ContentOffset + 1] != '*')
						return false;
					this.ContentOffset += 3;
					do {
						if (++this.ContentOffset > this.ContentLength)
							return false;
					}
					while (this.Content[this.ContentOffset - 2] != '*' || this.Content[this.ContentOffset - 1] != '/');
					got = true;
					break;
				default:
					return got;
				}
			}
			return true;
		}

		internal bool ExpectAfterWhitespace(string s) { return SkipWhitespaceAndComments() && Expect(s); }

		internal int ParseHex()
		{
			if (!ExpectAfterWhitespace("0x"))
				return -1;
			return ParseInt(16, 65535);
		}

		internal int ParseDefine(string s)
		{
			if (!ExpectAfterWhitespace("#define") || !ExpectAfterWhitespace(s))
				return -1;
			return ParseHex();
		}
	}

