		void Poke()
		{
			this.Gtia.Poke(this.GtiaRegisterIndex, this.CpuRegisters[this.CpuRegisterIndex]);
		}

		internal bool ReadIni()
		{
			Array.Clear(this.Gtia.PlayerHpos, 0, 4);
			Array.Clear(this.Gtia.Colors, 0, 9);
			this.ContentOffset = 0;
			for (;;) {
				switch (ExecuteUntilPoke()) {
				case -1:
					return false;
				case 0:
					return Expect(":2 sta wsync") && EndLine();
				default:
					Poke();
					break;
				}
			}
		}

		readonly byte[] Players = new byte[1024];

		internal bool ReadPmg()
		{
			this.ContentOffset = 0;
			if (!SkipUntilMnemonic() || !Expect(".ds $100") || !EndLine())
				return false;
			bool beginLine = true;
			for (int i = 0; i < 1024; i++) {
				if (beginLine) {
					if (!SkipUntilMnemonic() || !Expect(".he "))
						return false;
					beginLine = false;
				}
				int b = ParseHexByte();
				if (b < 0)
					return false;
				this.Players[i] = (byte) b;
				if (ReadByte() != ' ') {
					this.ContentOffset--;
					if (!EndLine())
						return false;
					beginLine = true;
				}
			}
			return true;
		}

		bool ExpectCmpZp() { return Expect("cmp byt2") && EndLine(); }

		internal bool ReadRp(byte[] bitmap, int height, byte[] frame)
		{
			this.ContentOffset = 0;
			for (int i = 0; i < 4; i++) {
				if (!SkipUntilMnemonic() || !Expect("nop") || !EndLine())
					return false;
			}
			if (!SkipUntilMnemonic() || !ExpectCmpZp())
				return false;
			Array.Clear(this.Gtia.MissileHpos, 0, 4);
			GtiaRenderer.SetSpriteSizes(this.Gtia.PlayerSize, 255);
			GtiaRenderer.SetSpriteSizes(this.Gtia.MissileSize, 0);
			this.Gtia.MissileGraphics = 0;
			this.Gtia.Prior = 20;
			this.Gtia.Content = bitmap;
			this.Gtia.PlayfieldColumns = 40;
			for (int y = 0; y < height; y++) {
				this.Gtia.ProcessPlayerDma(this.Players, 8 + y);
				this.Gtia.StartLine(48);
				for (int hpos = 7;;) {
					int cpuCycles = ExecuteUntilPoke();
					if (cpuCycles > 0) {
						int untilHpos = this.Gtia.AdvanceCpuCycles(hpos, cpuCycles, true);
						this.Gtia.DrawSpan(y, hpos >= 48 ? hpos : 48, untilHpos < 208 ? untilHpos : 208, AnticMode.FourColor, frame, 320);
						hpos = untilHpos;
						Poke();
						continue;
					}
					if (cpuCycles == 0 && ExpectCmpZp()) {
						this.Gtia.DrawSpan(y, hpos >= 48 ? hpos : 48, 208, AnticMode.FourColor, frame, 320);
						break;
					}
					return false;
				}
			}
			return true;
		}
	}

	class InflateStream : Stream
	{

		int Bits;

		int ReadBit()
		{
			if (this.Bits <= 1) {
				if (this.ContentOffset >= this.ContentLength)
					return -1;
				this.Bits = this.Content[this.ContentOffset++] | 256;
			}
			int result = this.Bits & 1;
			this.Bits >>= 1;
			return result;
		}

		int ReadBits(int count)
		{
			int result = 0;
			for (int rank = 0; rank < count; rank++) {
				switch (ReadBit()) {
				case -1:
					return -1;
				case 1:
					result |= 1 << rank;
					break;
				default:
					break;
				}
			}
			return result;
		}

		const int PrimarySymbols = 288;

		const int DistanceSymbols = 30;

		const int AllSymbols = 318;

		readonly byte[] SymbolCodeLength = new byte[318];

		const int TreeSize = 16;

		const int PrimaryTree = 0;

		const int DistanceTree = 16;

		readonly int[] NBitCodeCount = new int[32];

		readonly int[] NBitCodeOffset = new int[32];

		readonly short[] CodeToSymbol = new short[318];

		void BuildHuffmanTrees()
		{
			Array.Clear(this.NBitCodeCount, 0, 32);
			for (int i = 0; i < 318; i++)
				this.NBitCodeCount[this.SymbolCodeLength[i]]++;
			int offset = 0;
			for (int i = 0; i < 32; i++) {
				this.NBitCodeOffset[i] = offset;
				offset += this.NBitCodeCount[i];
			}
			for (int i = 0; i < 318; i++)
				this.CodeToSymbol[this.NBitCodeOffset[this.SymbolCodeLength[i]]++] = (short) i;
		}

		int FetchCode(int tree)
		{
			int code = 0;
			do {
				int bit = ReadBit();
				if (bit < 0)
					return -1;
				code = (code << 1) + bit - this.NBitCodeCount[++tree];
				if (code < 0)
					return this.CodeToSymbol[this.NBitCodeOffset[tree] + code];
			}
			while ((tree & 15) != 15);
			return -1;
		}

		int Inflate(byte[] unpacked, int unpackedLength)
		{
			int unpackedOffset = 0;
			this.Bits = 0;
			int lastBlock;
			do {
				lastBlock = ReadBit();
				int count;
				switch (ReadBits(2)) {
				case 0:
					this.Bits = 0;
					count = ReadBits(16);
					if (ReadBits(16) != (count ^ 65535))
						return -1;
					if (count > unpackedLength - unpackedOffset)
						count = unpackedLength - unpackedOffset;
					if (!ReadBytes(unpacked, unpackedOffset, count))
						return -1;
					unpackedOffset += count;
					if (unpackedOffset == unpackedLength)
						return unpackedOffset;
					continue;
				case 1:
					for (int i = 0; i < 144; i++)
						this.SymbolCodeLength[i] = 8;
					for (int i = 144; i < 256; i++)
						this.SymbolCodeLength[i] = 9;
					for (int i = 256; i < 280; i++)
						this.SymbolCodeLength[i] = 7;
					for (int i = 280; i < 288; i++)
						this.SymbolCodeLength[i] = 8;
					for (int i = 288; i < 318; i++)
						this.SymbolCodeLength[i] = 21;
					break;
				case 2:
					int primaryCodes = 257 + ReadBits(5);
					int codes = 289 + ReadBits(5);
					if (codes > 318)
						return -1;
					int temporaryCodes = ReadBits(4);
					if (temporaryCodes < 0)
						return -1;
					temporaryCodes += 4;
					Array.Clear(this.SymbolCodeLength, 0, 318);
					for (int i = 0; i < temporaryCodes; i++) {
						int bits = ReadBits(3);
						if (bits < 0)
							return -1;
						this.SymbolCodeLength[Inflate_tempSymbols[i]] = (byte) bits;
					}
					BuildHuffmanTrees();
					int length = 0;
					count = 1;
					for (int i = 0; i < codes; i++) {
						if (--count == 0) {
							int symbol = FetchCode(0);
							switch (symbol) {
							case -1:
								return -1;
							case 16:
								count = ReadBits(2);
								if (count < 0)
									return -1;
								count += 3;
								break;
							case 17:
								length = 0;
								count = ReadBits(3);
								if (count < 0)
									return -1;
								count += 3;
								break;
							case 18:
								length = 0;
								count = ReadBits(7);
								if (count < 0)
									return -1;
								count += 11;
								break;
							default:
								length = symbol;
								count = 1;
								break;
							}
						}
						if (i == primaryCodes)
							i = 288;
						this.SymbolCodeLength[i] = (byte) (i < 288 ? length : 16 + length);
					}
					break;
				default:
					return -1;
				}
				BuildHuffmanTrees();
				for (;;) {
					int symbol = FetchCode(0);
					if (symbol < 0)
						return -1;
					else if (symbol < 256)
						unpacked[unpackedOffset++] = (byte) symbol;
					else if (symbol == 256)
						break;
					else {
						switch (symbol) {
						case 257:
						case 258:
						case 259:
						case 260:
						case 261:
						case 262:
						case 263:
						case 264:
							count = symbol - 254;
							break;
						case 285:
							count = 258;
							break;
						case 286:
						case 287:
							return -1;
						default:
							symbol -= 261;
							count = ReadBits(symbol >> 2);
							if (count < 0)
								return -1;
							count += ((4 + (symbol & 3)) << (symbol >> 2)) + 3;
							break;
						}
						symbol = FetchCode(16);
						int distance;
						switch (symbol) {
						case -1:
							return -1;
						case 288:
						case 289:
						case 290:
						case 291:
							distance = symbol - 287;
							break;
						default:
							symbol -= 290;
							distance = ReadBits(symbol >> 1);
							if (distance < 0)
								return -1;
							distance += ((2 + (symbol & 1)) << (symbol >> 1)) + 1;
							break;
						}
						if (count > unpackedLength - unpackedOffset)
							count = unpackedLength - unpackedOffset;
						if (!RECOIL.CopyPrevious(unpacked, unpackedOffset, distance, count))
							return -1;
						unpackedOffset += count;
					}
					if (unpackedOffset == unpackedLength)
						return unpackedOffset;
				}
			}
			while (lastBlock == 0);
			return unpackedOffset;
		}

		internal int Uncompress(byte[] unpacked, int unpackedLength)
		{
			int b0 = ReadByte();
			if ((b0 & 143) != 8)
				return -1;
			int b1 = ReadByte();
			if ((b1 & 32) != 0 || (b0 << 8 | b1) % 31 != 0)
				return -1;
			return Inflate(unpacked, unpackedLength);
		}

		static readonly byte[] Inflate_tempSymbols = { 16, 17, 18, 0, 8, 7, 9, 6, 10, 5, 11, 4, 12, 3, 13, 2,
			14, 1, 15 };
	}

	/// <summary>Decoder of images in formats native to vintage computers.</summary>
	/// <remarks>Decodes file contents passed as a byte array
	/// into a 24-bit RGB bitmap.</remarks>
	public class RECOIL
	{
		/// <summary>Constructs a decoder of images.</summary>
		/// <remarks>The decoder can be used for several images, one after another.</remarks>
		public RECOIL()
		{
			SetNtsc(false);
		}

		/// <summary>RECOIL version - major part.</summary>
		public const int VersionMajor = 7;

		/// <summary>RECOIL version - minor part.</summary>
		public const int VersionMinor = 0;

		/// <summary>RECOIL version - micro part.</summary>
		public const int VersionMicro = 0;

		/// <summary>RECOIL version as a string.</summary>
		public const string Version = "7.0.0";

		/// <summary>Years RECOIL was created in.</summary>
		public const string Years = "2009-2026";

		/// <summary>Short credits for RECOIL.</summary>
		public const string Credits = "Retro Computer Image Library (C) 2009-2026 Piotr Fusik\n";

		/// <summary>Short license notice.</summary>
		/// <remarks>Display after the credits.</remarks>
		public const string License = "This program is licensed under the MIT License.";

		/// <summary>Maximum length of a supported platform palette file.</summary>
		public const int MaxPlatformPaletteContentLength = 32768;

		/// <summary>Maximum number of pixels in a decoded image.</summary>
		const int MaxPixelsLength = 16777216;

		/// <summary>Decoded image width.</summary>
		int Width;

		/// <summary>Decoded image height.</summary>
		int Height;

		/// <summary>Decoded image pixels as 0xRRGGBB.</summary>
		int[] Pixels;

		/// <summary>Length of the currently allocated <c>Pixels</c>.</summary>
		int PixelsLength = 0;

		/// <summary>Platform and pixel ratio.</summary>
		RECOILResolution Resolution;

		/// <summary>Number of frames (normally 1; 2 or 3 for flickering pictures).</summary>
		int Frames;

		/// <summary><see langword="true" /> if NTSC is preferred over PAL.</summary>
		bool Ntsc;

		readonly int[] C64Palette = new int[16];

		readonly int[] C16Palette = new int[128];

		readonly int[] Atari8Palette = new int[256];

		int LeftSkip;

		/// <summary>Maximum length of a string returned by <c>GetPlatform()</c>.</summary>
		public const int MaxPlatformLength = 22;

		/// <summary>Selects the PAL/NTSC video standard for applicable platforms.</summary>
		/// <remarks>Resets all platform palettes loaded with <c>SetPlatformPalette</c> to default.</remarks>
		/// <param name="ntsc"><see langword="true" /> for NTSC, <see langword="false" /> for PAL</param>
		public void SetNtsc(bool ntsc)
		{
			this.Ntsc = ntsc;
			this.C64Palette[0] = 0;
			this.C64Palette[1] = 16777215;
			this.C64Palette[2] = 6829867;
			this.C64Palette[3] = 7382194;
			this.C64Palette[4] = 7290246;
			this.C64Palette[5] = 5803331;
			this.C64Palette[6] = 3483769;
			this.C64Palette[7] = 12109679;
			this.C64Palette[8] = 7294757;
			this.C64Palette[9] = 4405504;
			this.C64Palette[10] = 10119001;
			this.C64Palette[11] = 4473924;
			this.C64Palette[12] = 7105644;
			this.C64Palette[13] = 10146436;
			this.C64Palette[14] = 7102133;
			this.C64Palette[15] = 9803157;
			DecodeR8G8B8Colors(FuResource.c16_pal, 0, 128, this.C16Palette, 0);
			DecodeR8G8B8Colors(this.Ntsc ? FuResource.altirrantsc_pal : FuResource.altirrapal_pal, 0, 256, this.Atari8Palette, 0);
		}

		/// <summary>Returns <see langword="true" /> if NTSC video standard is selected.</summary>
		public bool IsNtsc() { return this.Ntsc; }

		static int PackExt(string ext) { return ext.Length == 0 || ext.Length > 4 ? 0 : (ext[0] + (ext.Length >= 2 ? ext[1] << 8 : 0) + (ext.Length >= 3 ? ext[2] << 16 : 0) + (ext.Length >= 4 ? ext[3] << 24 : 0)) | 538976288; }

		static int GetPackedExt(string filename)
		{
			int ext = 0;
			for (int i = filename.Length; --i >= 0;) {
				int c = filename[i];
				if (c == '.')
					return ext | 538976288;
				if (c <= ' ' || c > 'z' || ext >= 16777216)
					return 0;
				ext = (ext << 8) + c;
			}
			return 0;
		}

		/// <summary>Sets a custom platform palette.</summary>
		/// <remarks>
		/// <list type="bullet">
		/// <item>768-byte <c>ACT</c>/<c>PAL</c> file with an Atari 8-bit palette</item>
		/// <item><c>VPL</c> VICE Palette file with a C64 or C16 palette</item>
		/// </list>
		/// <para>Returns <see langword="true" /> on success.</para></remarks>
		/// <param name="filename">Name of the file to decode. Only the extension is processed, for format recognition.</param>
		/// <param name="content">File contents.</param>
		/// <param name="contentLength">File length.</param>
		public bool SetPlatformPalette(string filename, byte[] content, int contentLength)
		{
			switch (GetPackedExt(filename)) {
			case 544498529:
			case 543973744:
				if (contentLength != 768)
					return false;
				DecodeR8G8B8Colors(content, 0, 256, this.Atari8Palette, 0);
				return true;
			case 543977590:
				VplStream vpl = new VplStream { Content = content, ContentOffset = 0, ContentLength = contentLength };
				switch (vpl.Decode()) {
				case 16:
					vpl.CopyTo(this.C64Palette, 16);
					return true;
				case 128:
					vpl.CopyTo(this.C16Palette, 128);
					return true;
				default:
					return false;
				}
			default:
				return false;
			}
		}

		/// <summary>Initializes decoded image size and resolution.</summary>
		bool SetSize(int width, int height, RECOILResolution resolution, int frames = 1)
		{
			if (width <= 0 || height <= 0 || height > 16777216 / width / frames)
				return false;
			this.Width = width;
			this.Height = height;
			this.Resolution = resolution;
			this.Frames = frames;
			this.Colors = -1;
			this.LeftSkip = 0;
			int pixelsLength = width * height * frames;
			if (this.PixelsLength < pixelsLength) {
				this.Pixels = new int[pixelsLength];
				this.PixelsLength = pixelsLength;
			}
			return true;
		}

		bool SetSizeStOrFalcon(int width, int height, int bitplanes, bool squarePixels)
		{
			RECOILResolution resolution = RECOILResolution.Falcon1x1;
			switch (bitplanes) {
			case 1:
				if (width <= 640 && height <= 400)
					resolution = RECOILResolution.St1x1;
				break;
			case 2:
				if (!squarePixels && width == 640 && height == 200) {
					height <<= 1;
					resolution = RECOILResolution.Ste1x2;
				}
				break;
			case 4:
				if (width <= 320 && height <= 200)
					resolution = RECOILResolution.Ste1x1;
				break;
			case 8:
				if (!squarePixels && width == 320 && height == 480) {
					width <<= 1;
					resolution = RECOILResolution.Tt2x1;
				}
				break;
			default:
				break;
			}
			return SetSize(width, height, resolution);
		}

		bool SetScaledSize(int width, int height, RECOILResolution resolution)
		{
			switch (resolution) {
			case RECOILResolution.Amiga2x1:
			case RECOILResolution.Falcon2x1:
			case RECOILResolution.Msx22x1i:
			case RECOILResolution.Msx2Plus2x1i:
				width <<= 1;
				break;
			case RECOILResolution.Amiga4x1:
				width <<= 2;
				break;
			case RECOILResolution.Amiga8x1:
				width <<= 3;
				break;
			case RECOILResolution.Amiga1x2:
			case RECOILResolution.AmigaDctv1x2:
			case RECOILResolution.St1x2:
			case RECOILResolution.Ste1x2:
			case RECOILResolution.Msx21x2:
			case RECOILResolution.Pc801x2:
			case RECOILResolution.Pc881x2:
			case RECOILResolution.ElementZx1x2:
				height <<= 1;
				break;
			case RECOILResolution.Amiga1x4:
				height <<= 2;
				break;
			default:
				break;
			}
			return SetSize(width, height, resolution);
		}

		void SetScaledPixel(int x, int y, int rgb)
		{
			int offset = y * this.Width;
			switch (this.Resolution) {
			case RECOILResolution.Amiga2x1:
			case RECOILResolution.AmigaHame2x1:
			case RECOILResolution.Amstrad2x1:
			case RECOILResolution.Tt2x1:
			case RECOILResolution.Falcon2x1:
			case RECOILResolution.Bbc2x1:
			case RECOILResolution.Msx22x1i:
			case RECOILResolution.Msx2Plus2x1i:
			case RECOILResolution.SamCoupe2x1i:
				offset += x << 1;
				this.Pixels[offset + 1] = this.Pixels[offset] = rgb;
				break;
			case RECOILResolution.Amiga4x1:
				offset += x << 2;
				this.Pixels[offset + 3] = this.Pixels[offset + 2] = this.Pixels[offset + 1] = this.Pixels[offset] = rgb;
				break;
			case RECOILResolution.Amiga8x1:
				offset += x << 3;
				for (x = 0; x < 8; x++)
					this.Pixels[offset + x] = rgb;
				break;
			case RECOILResolution.Amiga1x2:
			case RECOILResolution.AmigaDctv1x2:
			case RECOILResolution.AppleIIGS1x2:
			case RECOILResolution.St1x2:
			case RECOILResolution.Ste1x2:
			case RECOILResolution.Mc05151x2:
			case RECOILResolution.Pc801x2:
			case RECOILResolution.Pc881x2:
			case RECOILResolution.Msx21x2:
			case RECOILResolution.SamCoupe1x2:
			case RECOILResolution.ElementZx1x2:
			case RECOILResolution.Trs1x2:
				offset = (offset << 1) + x;
				this.Pixels[offset + this.Width] = this.Pixels[offset] = rgb;
				break;
			case RECOILResolution.Amiga1x4:
				offset = (offset << 2) + x;
				this.Pixels[offset + this.Width * 3] = this.Pixels[offset + this.Width * 2] = this.Pixels[offset + this.Width] = this.Pixels[offset] = rgb;
				break;
			default:
				this.Pixels[offset + x] = rgb;
				break;
			}
		}

		/// <summary>Reads a 32-bit big endian integer from a byte array.</summary>
		internal static int Get32BigEndian(byte[] content, int contentOffset)
		{
			return content[contentOffset] << 24 | content[contentOffset + 1] << 16 | content[contentOffset + 2] << 8 | content[contentOffset + 3];
		}

		/// <summary>Reads a 32-bit little endian integer from a byte array.</summary>
		internal static int Get32LittleEndian(byte[] content, int contentOffset)
		{
			return content[contentOffset] | content[contentOffset + 1] << 8 | content[contentOffset + 2] << 16 | content[contentOffset + 3] << 24;
		}

		internal static int GetNibble(byte[] content, int contentOffset, int index)
		{
			int b = content[contentOffset + (index >> 1)];
			return (index & 1) == 0 ? b >> 4 : b & 15;
		}

		internal static bool IsStringAt(byte[] content, int contentOffset, string s)
		{
			foreach (int c in s)
				if (content[contentOffset++] != c)
					return false;
			return true;
		}

		internal static bool CopyPrevious(byte[] unpacked, int unpackedOffset, int distance, int count)
		{
			if (distance > unpackedOffset)
				return false;
			do {
				unpacked[unpackedOffset] = unpacked[unpackedOffset - distance];
				unpackedOffset++;
			}
			while (--count > 0);
			return true;
		}

		bool ApplyBlend()
		{
			int pixelsLength = this.Width * this.Height;
			for (int i = 0; i < pixelsLength; i++) {
				int rgb1 = this.Pixels[i];
				int rgb2 = this.Pixels[pixelsLength + i];
				this.Pixels[i] = (rgb1 & rgb2) + ((rgb1 ^ rgb2) >> 1 & 8355711);
			}
			return true;
		}

		/// <summary>Reads a companion file to the specified byte array.</summary>
		/// <remarks>Implement this method in a subclass to enable support for multi-file images.
		/// Returns the number of bytes read (up to <c>contentLength</c>) or -1 on error.</remarks>
		/// <param name="filename">Name of the file to read.</param>
		/// <param name="content">Out: target for the file contents.</param>
		/// <param name="contentLength">Maximum number of bytes to read.</param>
		protected virtual int ReadFile(string filename, byte[] content, int contentLength) { return -1; }

		int ReadCompanionFile(string baseFilename, string upperExt, string lowerExt, byte[] content, int contentLength)
		{
			int i = baseFilename.Length;
			bool lower = false;
			for (;;) {
				int c = baseFilename[--i];
				if (c >= 'a')
					lower = true;
				else if (c == '.')
					break;
			}
			string filename = baseFilename.Substring(0, i + 1);
			filename += lower ? lowerExt : upperExt;
			return ReadFile(filename, content, contentLength);
		}

		int ReadSiblingFile(string baseFilename, string newFilename, byte[] content, int contentLength)
		{
			int i = baseFilename.Length;
			while (i > 0 && baseFilename[i - 1] != '/' && baseFilename[i - 1] != '\\')
				i--;
			string filename = baseFilename.Substring(0, i);
			filename += newFilename;
			return ReadFile(filename, content, contentLength);
		}

		bool DecodeBru(byte[] content, int contentLength)
		{
			if (contentLength != 64)
				return false;
			SetSize(8, 8, RECOILResolution.St1x1);
			for (int i = 0; i < 64; i++) {
				switch (content[i]) {
				case 0:
					this.Pixels[i] = 0;
					break;
				case 1:
					this.Pixels[i] = 16777215;
					break;
				default:
					return false;
				}
			}
			return true;
		}

		/// <summary>RGB palette decoded from the image file.</summary>
		internal readonly int[] ContentPalette = new int[256];

		void SetGrayscalePalette(int inverse)
		{
			for (int c = 0; c < 256; c++)
				this.ContentPalette[c] = (c ^ inverse) * 65793;
		}

		void DecodeBytes(byte[] content, int contentOffset)
		{
			int width = GetOriginalWidth();
			int height = GetOriginalHeight();
			for (int y = 0; y < height; y++)
				for (int x = 0; x < width; x++)
					SetScaledPixel(x, y, this.ContentPalette[content[contentOffset + y * width + x]]);
		}

		void DecodeNibbles(byte[] content, int contentOffset, int contentStride)
		{
			int width = GetOriginalWidth();
			int height = GetOriginalHeight();
			for (int y = 0; y < height; y++)
				for (int x = 0; x < width; x++)
					SetScaledPixel(x, y, this.ContentPalette[GetNibble(content, contentOffset + y * contentStride, x)]);
		}

		static int GetR8G8B8Color(byte[] content, int contentOffset) { return content[contentOffset] << 16 | content[contentOffset + 1] << 8 | content[contentOffset + 2]; }

		static int GetB8G8R8Color(byte[] content, int contentOffset) { return content[contentOffset + 2] << 16 | content[contentOffset + 1] << 8 | content[contentOffset]; }

		static void DecodeR8G8B8Colors(byte[] content, int contentOffset, int count, int[] destination, int destinationOffset)
		{
			for (int i = 0; i < count; i++)
				destination[destinationOffset + i] = GetR8G8B8Color(content, contentOffset + i * 3);
		}

		static int GetB5G5R5Color(int c)
		{
			c = (c & 31) << 19 | (c & 992) << 6 | (c >> 7 & 248);
			return c | (c >> 5 & 460551);
		}

		static int GetR5G5B5Color(int c)
		{
			c = (c & 31744) << 9 | (c & 992) << 6 | (c & 31) << 3;
			return c | (c >> 5 & 460551);
		}

		static int GetG6R5B5Color(int c)
		{
			c = (c & 992) << 14 | (c & 64512) | (c & 31) << 3;
			return c | (c >> 5 & 458759) | (c >> 6 & 768);
		}

		static int Get729Color(int c)
		{
			int r = c / 81;
			int g = c / 9 % 9;
			int b = c % 9;
			return r * 255 >> 3 << 16 | g * 255 >> 3 << 8 | b * 255 >> 3;
		}

		internal static int GetFalconTrueColor(byte[] content, int contentOffset)
		{
			int rg = content[contentOffset];
			int gb = content[contentOffset + 1];
			int rgb = (rg & 248) << 16 | (rg & 7) << 13 | (gb & 224) << 5 | (gb & 31) << 3;
			rgb |= (rgb >> 5 & 458759) | (rgb >> 6 & 768);
			return rgb;
		}

		static int GetBitplanePixel(byte[] content, int contentOffset, int x, int bitplanes, int bytesPerBitplane)
		{
			int bit = ~x & 7;
			int c = 0;
			for (int bitplane = bitplanes; --bitplane >= 0;)
				c = c << 1 | (content[contentOffset + bitplane * bytesPerBitplane] >> bit & 1);
			return c;
		}

		bool DecodeAmigaPlanar(byte[] content, int contentOffset, int width, int height, RECOILResolution resolution, int bitplanes, int[] palette)
		{
			if (!SetScaledSize(width, height, resolution))
				return false;
			int bytesPerLine = (width + 15) >> 4 << 1;
			int bitplaneLength = height * bytesPerLine;
			for (int y = 0; y < height; y++) {
				for (int x = 0; x < width; x++) {
					int c = GetBitplanePixel(content, contentOffset + y * bytesPerLine + (x >> 3), x, bitplanes, bitplaneLength);
					SetScaledPixel(x, y, palette[c]);
				}
			}
			return true;
		}

		static int GetBitplaneWordsPixel(byte[] content, int contentOffset, int x, int bitplanes) { return GetBitplanePixel(content, contentOffset + (x >> 3 & ~1) * bitplanes + (x >> 3 & 1), x, bitplanes, 2); }

		/// <summary>Decodes Atari ST/Falcon interleaved bitplanes.</summary>
		/// <remarks>Each 16 pixels are encoded in N consecutive 16-bit words.</remarks>
		void DecodeBitplanes(byte[] content, int contentOffset, int contentStride, int bitplanes, int pixelsOffset, int width, int height)
		{
			while (--height >= 0) {
				for (int x = 0; x < width; x++) {
					int c = GetBitplaneWordsPixel(content, contentOffset, x, bitplanes);
					this.Pixels[pixelsOffset + x] = this.ContentPalette[c];
				}
				contentOffset += contentStride;
				pixelsOffset += this.Width;
			}
		}

		void DecodeScaledBitplanes(byte[] content, int contentOffset, int width, int height, int bitplanes, bool ehb, MultiPalette multiPalette)
		{
			int contentStride = ((width + 15) >> 4 << 1) * bitplanes;
			for (int y = 0; y < height; y++) {
				if (multiPalette != null)
					multiPalette.SetLinePalette(this, y);
				if (ehb) {
					for (int c = 0; c < 32; c++)
						this.ContentPalette[32 + c] = this.ContentPalette[c] >> 1 & 8355711;
				}
				for (int x = 0; x < width; x++) {
					int c = GetBitplaneWordsPixel(content, contentOffset, x, bitplanes);
					SetScaledPixel(x, y, this.ContentPalette[c]);
				}
				contentOffset += contentStride;
			}
		}

		bool DecodeMono(byte[] content, int contentOffset, int contentLength, bool wordAlign)
		{
			int contentStride = (this.Width + 7) >> 3;
			if (wordAlign)
				contentStride += contentStride & 1;
			if (contentLength != contentOffset + contentStride * this.Height)
				return false;
			DecodeBitplanes(content, contentOffset, contentStride, 1, 0, this.Width, this.Height);
			return true;
		}

		bool DecodeBlackAndWhite(byte[] content, int contentOffset, int contentLength, bool wordAlign, int backgroundColor)
		{
			this.ContentPalette[0] = backgroundColor;
			this.ContentPalette[1] = backgroundColor ^ 16777215;
			return DecodeMono(content, contentOffset, contentLength, wordAlign);
		}

		bool DecodeRleMono(RleStream rle, int color0, int color1)
		{
			int width = GetOriginalWidth();
			int height = GetOriginalHeight();
			for (int y = 0; y < height; y++) {
				int b = 0;
				for (int x = 0; x < width; x++) {
					if ((x & 7) == 0) {
						b = rle.ReadRle();
						if (b < 0)
							return false;
					}
					SetScaledPixel(x, y, (b >> (~x & 7) & 1) == 0 ? color0 : color1);
				}
			}
			return true;
		}

		bool DecodeRleBlackAndWhite(RleStream rle, int backgroundColor) { return DecodeRleMono(rle, backgroundColor, backgroundColor ^ 16777215); }

		void DecodeBlackAndWhiteFont(byte[] content, int contentOffset, int contentLength, int fontHeight)
		{
			for (int y = 0; y < this.Height; y++) {
				for (int x = 0; x < 256; x++) {
					int row = y % fontHeight;
					int offset = contentOffset + ((y - row) << 5) + (x >> 3) * fontHeight + row;
					int c;
					if (offset < contentLength) {
						c = content[offset] >> (~x & 7) & 1;
						if (c != 0)
							c = 16777215;
					}
					else
						c = 0;
					this.Pixels[(y << 8) + x] = c;
				}
			}
		}

		bool DecodePgf(byte[] content, int contentLength)
		{
			SetSize(240, 64, RECOILResolution.Portfolio1x1);
			this.ContentPalette[0] = 9355692;
			this.ContentPalette[1] = 4409239;
			return DecodeMono(content, 0, contentLength, false);
		}

		bool DecodePgc(byte[] content, int contentLength)
		{
			if (contentLength < 33 || content[0] != 'P' || content[1] != 'G' || content[2] != 1)
				return false;
			SetSize(240, 64, RECOILResolution.Portfolio1x1);
			PgcStream rle = new PgcStream { Content = content, ContentOffset = 3, ContentLength = contentLength };
			return DecodeRleMono(rle, 9355692, 4409239);
		}

		bool DecodePsion3Pic(byte[] content, int contentLength)
		{
			if (contentLength < 22 || content[0] != 'P' || content[1] != 'I' || content[2] != 'C' || content[3] != 220 || content[4] != '0' || content[5] != '0' || (content[6] == 0 && content[7] == 0))
				return false;
			int width = content[10] | content[11] << 8;
			int height = content[12] | content[13] << 8;
			int bitmapLength = content[14] | content[15] << 8;
			int stride = (width + 15) >> 4 << 1;
			if (bitmapLength != height * stride)
				return false;
			int bitmapOffset = 20 + RECOIL.Get32LittleEndian(content, 16);
			if (bitmapOffset < 20 || contentLength < bitmapOffset + bitmapLength)
				return false;
			if (!SetSize(width, height, RECOILResolution.Psion31x1))
				return false;
			for (int y = 0; y < height; y++) {
				for (int x = 0; x < width; x++) {
					this.Pixels[y * width + x] = (content[bitmapOffset + (x >> 3)] >> (x & 7) & 1) == 0 ? 16777215 : 0;
				}
				bitmapOffset += stride;
			}
			return true;
		}

		bool DecodeGrb(byte[] content, int contentLength)
		{
			if (contentLength < 19)
				return false;
			if (IsStringAt(content, 0, "HPHP48-") && content[8] == 30 && content[9] == 43 && (content[10] & 15) == 0) {
				int nibbles = content[10] >> 4 | content[11] << 4 | content[12] << 12;
				int height = content[13] | content[14] << 8 | (content[15] & 15) << 16;
				int width = content[15] >> 4 | content[16] << 4 | content[17] << 12;
				int bytesPerLine = (width + 7) >> 3;
				if (nibbles != (contentLength << 1) - 21 || contentLength != 18 + height * bytesPerLine || !SetSize(width, height, RECOILResolution.Hp481x1))
					return false;
				for (int y = 0; y < height; y++) {
					for (int x = 0; x < width; x++)
						this.Pixels[y * width + x] = (content[18 + y * bytesPerLine + (x >> 3)] >> (x & 7) & 1) == 0 ? 16777215 : 0;
				}
				return true;
			}
			if (contentLength >= 31 && IsStringAt(content, 0, "%%HP: T(0)A(D)F(.);\rGROB ")) {
				Stream s = new Stream { Content = content, ContentOffset = 25, ContentLength = contentLength };
				int width = s.ParseInt(10, 65535);
				if (width <= 0 || s.ReadByte() != ' ')
					return false;
				int height = s.ParseInt(10, 65535);
				if (height <= 0 || s.ReadByte() != '\r' || !SetSize(width, height, RECOILResolution.Hp481x1))
					return false;
				int b = 0;
				for (int y = 0; y < height; y++) {
					for (int x = 0; x < width; x++) {
						int bit = x & 7;
						if (bit == 0) {
							b = s.ReadHexByte();
							if (b < 0)
								return false;
						}
						this.Pixels[y * width + x] = (b >> (bit ^ 4) & 1) == 0 ? 16777215 : 0;
					}
				}
				return true;
			}
			return false;
		}

		bool DecodeTrsHr(byte[] content, int contentLength)
		{
			switch (contentLength) {
			case 19200:
			case 19328:
			case 19456:
				break;
			default:
				return false;
			}
			SetSize(640, 480, RECOILResolution.Trs1x2);
			for (int y = 0; y < 240; y++) {
				for (int x = 0; x < 640; x++) {
					int c = content[y * 80 + (x >> 3)] >> (~x & 7) & 1;
					if (c != 0)
						c = 16777215;
					int pixelsOffset = y * 1280 + x;
					this.Pixels[pixelsOffset + 640] = this.Pixels[pixelsOffset] = c;
				}
			}
			return true;
		}

		bool DecodeTrsShr(byte[] content, int contentLength)
		{
			SetSize(640, 480, RECOILResolution.Trs1x2);
			PgcStream rle = new PgcStream { Content = content, ContentOffset = 0, ContentLength = contentLength };
			return DecodeRleBlackAndWhite(rle, 0);
		}

		bool DecodeRle(byte[] content, int contentLength)
		{
			if (contentLength < 520 || content[0] != 27 || content[1] != 71 || content[2] != 72)
				return false;
			SetSize(256, 192, RECOILResolution.Trs1x1);
			int count = 0;
			int contentOffset = 3;
			int c = 16777215;
			for (int pixelsOffset = 0; pixelsOffset < 49152; pixelsOffset++) {
				while (count == 0) {
					if (contentOffset >= contentLength)
						return false;
					count = content[contentOffset++];
					if (count < 32 || count > 127) {
						if (pixelsOffset == 49151) {
							this.Pixels[pixelsOffset] = c;
							return true;
						}
						return false;
					}
					c ^= 16777215;
					count -= 32;
				}
				this.Pixels[pixelsOffset] = c;
				count--;
			}
			return true;
		}

		bool DecodeCocoClp(byte[] content, int contentLength)
		{
			if (contentLength != 306 || content[305] != 100)
				return false;
			for (int i = 0; i < 25; i++) {
				if (content[i] != DecodeCocoClp_header[i])
					return false;
			}
			SetSize(40, 56, RECOILResolution.Coco1x1);
			return DecodeBlackAndWhite(content, 25, 305, false, 16777215);
		}

		bool DecodeCocoMax(byte[] content, int contentLength)
		{
			switch (contentLength) {
			case 6154:
			case 6155:
			case 6272:
			case 7168:
				break;
			default:
				return false;
			}
			if (content[0] != 0 || content[1] != 24 || content[2] > 1 || content[3] != 14 || content[4] != 0)
				return false;
			SetSize(256, 192, RECOILResolution.Coco1x1);
			return DecodeBlackAndWhite(content, 5, 6149, false, 0);
		}

		bool DecodeP11(byte[] content, int contentLength)
		{
			if ((contentLength != 3083 && contentLength != 3243) || content[0] != 0 || content[1] != 12 || content[3] != 14 || content[4] != 0)
				return false;
			SetSize(256, 192, RECOILResolution.Coco2x2);
			for (int y = 0; y < 192; y++) {
				for (int x = 0; x < 256; x++) {
					int c = content[5 + ((y & ~1) << 4) + (x >> 3)] >> (~x & 6) & 3;
					this.Pixels[(y << 8) + x] = DecodeP11_palette[c];
				}
			}
			return true;
		}

		bool DecodeMac(byte[] content, int contentLength)
		{
			if (contentLength < 512)
				return false;
			int contentOffset = IsStringAt(content, 65, "PNTG") ? 128 : 0;
			if (content[contentOffset] != 0 || content[contentOffset + 1] != 0 || content[contentOffset + 2] != 0 || content[contentOffset + 3] > 3)
				return false;
			SetSize(576, 720, RECOILResolution.Macintosh1x1);
			PackBitsStream rle = new PackBitsStream { Content = content, ContentOffset = contentOffset + 512, ContentLength = contentLength };
			return DecodeRleBlackAndWhite(rle, 16777215);
		}

		static void DecodePlayStation(byte[] content, int contentOffset, int[] pixels, int pixelsLength)
		{
			for (int i = 0; i < pixelsLength; i++)
				pixels[i] = GetB5G5R5Color(content[contentOffset + (i << 1)] | content[contentOffset + (i << 1) + 1] << 8);
		}

		int DecodeTimPalette(byte[] content, int contentLength, int colors)
		{
			if ((content[16] | content[17] << 8) != colors)
				return -1;
			int paletteCount = content[18] | content[19] << 8;
			if (paletteCount == 0)
				return -1;
			int bitmapOffset = 20 + (paletteCount * colors << 1);
			if (Get32LittleEndian(content, 8) != bitmapOffset - 8 || contentLength < bitmapOffset + 12)
				return -1;
			int width = (content[bitmapOffset + 8] | content[bitmapOffset + 9] << 8) << 1;
			int height = content[bitmapOffset + 10] | content[bitmapOffset + 11] << 8;
			if (contentLength < bitmapOffset + 12 + width * height)
				return -1;
			if (colors == 16)
				width <<= 1;
			if (!SetSize(width, height, RECOILResolution.PlayStation1x1))
				return -1;
			DecodePlayStation(content, 20, this.ContentPalette, colors);
			return bitmapOffset + 12;
		}

		bool DecodeTim(byte[] content, int contentLength)
		{
			if (contentLength < 20 || Get32LittleEndian(content, 0) != 16)
				return false;
			int width;
			int height;
			int pixelsLength;
			int bitmapOffset;
			switch (content[4] & 15) {
			case 2:
				width = content[16] | content[17] << 8;
				height = content[18] | content[19] << 8;
				pixelsLength = width * height;
				if (contentLength < 20 + (pixelsLength << 1) || !SetSize(width, height, RECOILResolution.PlayStation1x1))
					return false;
				DecodePlayStation(content, 20, this.Pixels, pixelsLength);
				return true;
			case 3:
				width = (content[16] | content[17] << 8) * 2 / 3;
				height = content[18] | content[19] << 8;
				pixelsLength = width * height;
				if (contentLength != 20 + pixelsLength * 3 || !SetSize(width, height, RECOILResolution.PlayStation1x1))
					return false;
				DecodeR8G8B8Colors(content, 20, pixelsLength, this.Pixels, 0);
				return true;
			case 8:
				bitmapOffset = DecodeTimPalette(content, contentLength, 16);
				if (bitmapOffset < 0)
					return false;
				pixelsLength = this.Width * this.Height;
				for (int i = 0; i < pixelsLength; i++) {
					int b = content[bitmapOffset + (i >> 1)];
					this.Pixels[i] = this.ContentPalette[(i & 1) == 0 ? b & 15 : b >> 4];
				}
				return true;
			case 9:
				bitmapOffset = DecodeTimPalette(content, contentLength, 256);
				if (bitmapOffset < 0)
					return false;
				DecodeBytes(content, bitmapOffset);
				return true;
			default:
				return false;
			}
		}

		static readonly int[] BbcPalette = { 0, 16711680, 65280, 16776960, 255, 16711935, 65535, 16777215, 0, 16711680, 65280, 16776960, 255, 16711935, 65535, 16777215 };

		static readonly int[] BbcPalette2Bit = { 0, 16711680, 16776960, 16777215 };

		static readonly int[] BbcPalette1Bit = { 0, 16777215 };

		bool DecodeBb0(byte[] content, int contentLength, int[] palette)
		{
			if (contentLength != 20480)
				return false;
			SetSize(640, 512, RECOILResolution.Bbc1x2);
			for (int y = 0; y < 256; y++) {
				for (int x = 0; x < 640; x++) {
					int c = content[(y & ~7) * 80 + (x & ~7) + (y & 7)] >> (~x & 7) & 1;
					int pixelsOffset = y * 1280 + x;
					this.Pixels[pixelsOffset + 640] = this.Pixels[pixelsOffset] = palette[c];
				}
			}
			return true;
		}

		bool DecodeBb1(byte[] content, int contentLength, int[] palette)
		{
			if (contentLength != 20480)
				return false;
			SetSize(320, 256, RECOILResolution.Bbc1x1);
			for (int y = 0; y < 256; y++) {
				for (int x = 0; x < 320; x++) {
					int c = content[(y & ~7) * 80 + ((x & ~3) << 1) + (y & 7)] >> (~x & 3);
					this.Pixels[y * 320 + x] = palette[(c >> 3 & 2) + (c & 1)];
				}
			}
			return true;
		}

		bool DecodeBb2(byte[] content, int contentLength, int[] palette)
		{
			if (contentLength != 20480)
				return false;
			SetSize(320, 256, RECOILResolution.Bbc2x1);
			for (int y = 0; y < 256; y++) {
				for (int x = 0; x < 160; x++) {
					int c = content[(y & ~7) * 80 + ((x & ~1) << 2) + (y & 7)] >> (~x & 1);
					int pixelsOffset = (y * 160 + x) << 1;
					this.Pixels[pixelsOffset + 1] = this.Pixels[pixelsOffset] = palette[(c >> 3 & 8) + (c >> 2 & 4) + (c >> 1 & 2) + (c & 1)];
				}
			}
			return true;
		}

		bool DecodeBb4(byte[] content, int contentLength, int[] palette)
		{
			if (contentLength != 10240)
				return false;
			SetSize(320, 256, RECOILResolution.Bbc1x1);
			for (int y = 0; y < 256; y++) {
				for (int x = 0; x < 320; x++) {
					int c = content[(y & ~7) * 40 + (x & ~7) + (y & 7)] >> (~x & 7) & 1;
					this.Pixels[y * 320 + x] = palette[c];
				}
			}
			return true;
		}

		bool DecodeBb5(byte[] content, int contentLength, int[] palette)
		{
			if (contentLength != 10240)
				return false;
			SetSize(320, 256, RECOILResolution.Bbc2x1);
			for (int y = 0; y < 256; y++) {
				for (int x = 0; x < 160; x++) {
					int c = content[(y & ~7) * 40 + ((x & ~3) << 1) + (y & 7)] >> (~x & 3);
					int pixelsOffset = (y * 160 + x) << 1;
					this.Pixels[pixelsOffset + 1] = this.Pixels[pixelsOffset] = palette[(c >> 3 & 2) + (c & 1)];
				}
			}
			return true;
		}

		bool DecodeBbg(byte[] content, int contentLength)
		{
			BbgStream rle = new BbgStream { Content = content, ContentOffset = 0, ContentLength = contentLength };
			rle.ValueBits = rle.ReadBitsReverse(8);
			if (rle.ValueBits < 1 || rle.ValueBits > 8)
				return false;
			int mode = rle.ReadBitsReverse(8);
			int unpackedLength;
			switch (mode) {
			case 0:
			case 1:
			case 2:
				unpackedLength = 20480;
				break;
			case 4:
			case 5:
				unpackedLength = 10240;
				break;
			default:
				return false;
			}
			for (int i = 15; i >= 0; i--) {
				int c = rle.ReadBitsReverse(4);
				if (c < 0)
					return false;
				this.ContentPalette[i] = BbcPalette[c];
			}
			int unpackedStep = rle.ReadBitsReverse(8);
			if (unpackedStep <= 0)
				return false;
			rle.CountBits = rle.ReadBitsReverse(8);
			if (rle.CountBits < 1 || rle.CountBits > 8)
				return false;
			byte[] unpacked = new byte[20480];
			for (int x = unpackedStep - 1; x >= 0; x--) {
				if (!rle.Unpack(unpacked, x, unpackedStep, unpackedLength))
					return false;
			}
			switch (mode) {
			case 0:
				return DecodeBb0(unpacked, unpackedLength, this.ContentPalette);
			case 1:
				return DecodeBb1(unpacked, unpackedLength, this.ContentPalette);
			case 2:
				return DecodeBb2(unpacked, unpackedLength, this.ContentPalette);
			case 4:
				return DecodeBb4(unpacked, unpackedLength, this.ContentPalette);
			case 5:
				return DecodeBb5(unpacked, unpackedLength, this.ContentPalette);
			default:
				return false;
			}
		}

		static int GetOricHeader(byte[] content, int contentLength)
		{
			if (contentLength < 26 || content[0] != 22 || content[1] != 22 || content[2] != 22 || content[3] != 36 || content[4] != 0 || content[5] != 0 || content[6] != 128 || content[7] != 0 || content[12] != 0)
				return 0;
			int contentOffset = 13;
			while (content[contentOffset++] != 0) {
				if (contentOffset >= 26)
					return 0;
			}
			return contentOffset;
		}

		bool DecodeChs(byte[] content, int contentLength)
		{
