			for (int y = 0; y < 200; y++) {
				int paper = 0;
				int ink = 7;
				for (int col = 0; col < 40; col++) {
					int offset = y * 40 + col;
					int b = content[contentOffset + offset];
					int inverse = b >= 128 ? 7 : 0;
					switch (b & 120) {
					case 0:
						ink = b & 7;
						b = 0;
						break;
					case 8:
					case 24:
						b = 0;
						break;
					case 16:
						paper = b & 7;
						b = 0;
						break;
					default:
						break;
					}
					for (int x = 0; x < 6; x++)
						this.Pixels[offset * 6 + x] = BbcPalette[((b >> (5 - x) & 1) == 0 ? paper : ink) ^ inverse];
				}
			}
			return true;
		}

		static int GetAmstradHeader(byte[] content, int contentLength)
		{
			if (contentLength < 128 || (content[24] | content[25] << 8) != contentLength - 128 || content[64] != content[24] || content[65] != content[25] || content[66] != 0)
				return 0;
			int sum = 0;
			for (int i = 0; i < 67; i++)
				sum += content[i];
			if ((content[67] | content[68] << 8) != sum)
				return 0;
			return 128;
		}

		bool DecodeAmstradFnt(byte[] content, int contentLength)
		{
