			SetSize(256, 24, RECOILResolution.Amstrad1x1);
			DecodeBlackAndWhiteFont(content, contentOffset, contentLength, 8);
			return true;
		}

		static int GetAmstradLineOffset(int y, int bytesPerLine, bool overscan) { return ((y & 7) << 11) + (y >> 3) * bytesPerLine + (overscan && y >= 128 ? 14336 : 0); }

		void DecodeAmstradMode2Line(byte[] content, int lineOffset, int y)
