				int c = content[lineOffset + (x >> 3)] >> (~x & 7) & 1;
				this.Pixels[offset + this.Width] = this.Pixels[offset] = this.ContentPalette[c];
			}
		}

		bool DecodeAmstradMode2(byte[] content, int contentOffset, int width, int height, bool overscan)
		{
			SetSize(width, height << 1, RECOILResolution.Amstrad1x2);
			for (int y = 0; y < height; y++)
				DecodeAmstradMode2Line(content, contentOffset + GetAmstradLineOffset(y, width >> 3, overscan), y);
