		static readonly int[] AmstradPalette = { 8421504, 8421504, 65408, 16777088, 128, 16711808, 32896, 16744576, 16711808, 16777088, 16776960, 16777215, 16711680, 16711935, 16744448, 16744703,
			128, 65408, 65280, 65535, 0, 255, 32768, 33023, 8388736, 8454016, 8453888, 8454143, 8388608, 8388863, 8421376, 8421631 };

		int SetAmstradPalette(string filename)
		{
			byte[] pal = new byte[368];
			int palLength = ReadCompanionFile(filename, "PAL", "pal", pal, 368);
			int palOffset = GetAmstradHeader(pal, palLength);
			if (palLength != palOffset + 239)
				return -1;
			for (int i = 0; i < 16; i++) {
				int c = pal[palOffset + 3 + i * 12];
				if (c < 64 || c > 95)
					return -1;
				this.ContentPalette[i] = AmstradPalette[c - 64];
			}
			return pal[palOffset];
		}

		static bool UnpackConvImgCpc(byte[] content, int contentOffset, int contentLength, byte[] unpacked, int unpackedLength)
		{
			int unpackedOffset = 0;
			int bits = 0;
			while (contentOffset < contentLength) {
				if (bits <= 1) {
					bits = content[contentOffset++] | 256;
					if (contentOffset >= contentLength)
						return false;
				}
				int compressed = bits & 1;
				bits >>= 1;
				if (compressed == 0) {
					if (unpackedOffset >= unpackedLength)
						return false;
					unpacked[unpackedOffset++] = content[contentOffset++];
				}
				else {
					int b = content[contentOffset++];
					int distance;
					int count;
					if (b >= 128) {
						if (contentOffset >= contentLength)
							return false;
						count = (b >> 4) - 5;
						distance = ((b & 15) << 8) + content[contentOffset++] + 1;
					}
					else if (b >= 64) {
						distance = b - 63;
						count = 2;
					}
					else if (b >= 32) {
						if (contentOffset >= contentLength)
							return false;
						count = b - 30;
						distance = content[contentOffset++] + 1;
					}
					else if (b >= 16) {
						if (contentOffset + 1 >= contentLength)
							return false;
						distance = ((b - 16) << 8) + content[contentOffset++] + 1;
						count = content[contentOffset++] + 1;
					}
					else if (b == 15) {
						if (contentOffset >= contentLength)
							return false;
						count = distance = content[contentOffset++] + 1;
					}
					else if (b >= 2)
						count = distance = b;
					else if (b == 1)
						count = distance = 256;
					else
						return contentOffset == contentLength && unpackedOffset == unpackedLength;
					if (unpackedOffset + count > unpackedLength)
						count = unpackedLength - unpackedOffset;
					if (!RECOIL.CopyPrevious(unpacked, unpackedOffset, distance, count))
						return false;
					unpackedOffset += count;
				}
			}
			return false;
		}

		bool SetAmstradFirmwarePalette(byte[] content, int contentOffset, int count)
		{
			for (int i = 0; i < count; i++) {
				int c = content[contentOffset + i];
				if (c > 26) {
					Array.Clear(this.ContentPalette, i, count - i);
					for (; i < count; i++) {
						if (content[contentOffset + i] != 255)
							return false;
					}
					break;
				}
				this.ContentPalette[i] = SetAmstradFirmwarePalette_triLevel[c / 3 % 3] << 16 | SetAmstradFirmwarePalette_triLevel[c / 9] << 8 | SetAmstradFirmwarePalette_triLevel[c % 3];
			}
			return true;
		}

		static int GetAmstradMode0Index(int x, int b)
		{
			if ((x & 2) == 0)
				b >>= 1;
			return ((b & 1) << 3) + (b >> 2 & 4) + (b >> 1 & 2) + (b >> 6 & 1);
		}

		void DecodeAmstradMode0Line(byte[] content, int lineOffset, int y, int skip = 0)
		{
			for (int x = 0; x < this.Width; x++) {
				int i = x + skip;
				int b = i >= this.Width ? 0 : content[lineOffset + (i >> 2)];
				this.Pixels[y * this.Width + x] = this.ContentPalette[GetAmstradMode0Index(i, b)];
			}
		}

		static int GetAmstradMode1Index(int x, int b)
		{
			b >>= ~x & 3;
			return ((b & 1) << 1) + (b >> 4 & 1);
		}

		void DecodeAmstradMode1Line(byte[] content, int lineOffset, int y)
		{
			for (int x = 0; x < this.Width; x++)
				this.Pixels[y * this.Width + x] = this.ContentPalette[GetAmstradMode1Index(x, content[lineOffset + (x >> 2)])];
		}

		bool DecodeAmstradScrPk(byte[] content, int contentOffset, int contentLength, byte[] unpacked, int width, int height)
		{
			if (!UnpackConvImgCpc(content, contentOffset + 21, contentLength, unpacked, (width >> 2) * height))
				return false;
			int mode = content[contentOffset + 4];
			if (mode > 1 || !SetAmstradFirmwarePalette(content, contentOffset + 5, mode == 0 ? 16 : 4))
				return false;
			SetSize(width, height, mode == 0 ? RECOILResolution.Amstrad2x1 : RECOILResolution.Amstrad1x1);
			for (int y = 0; y < height; y++) {
				for (int x = 0; x < width; x++) {
					int b = unpacked[(x >> 2) * height + y];
					this.Pixels[y * width + x] = this.ContentPalette[mode == 0 ? GetAmstradMode0Index(x, b) : GetAmstradMode1Index(x, b)];
				}
			}
			return true;
		}

		bool DecodeAmstradScr(string filename, byte[] content, int contentLength)
		{
			byte[] unpacked = new byte[31936];
			int contentOffset = GetAmstradHeader(content, contentLength);
			int width = 320;
			int height = 200;
			bool overscan = false;
			switch (contentLength - contentOffset) {
			case 15872:
				width = 256;
				height = 192;
				break;
			case 16336:
			case 16384:
				break;
			case 31936:
				width = 384;
				height = 272;
				overscan = true;
				break;
			default:
				if (content[contentOffset] == 'P' && content[contentOffset + 1] == 'K' && content[contentOffset + 3] == 'L') {
					switch (content[contentOffset + 2]) {
					case (byte) 'S':
						if (DecodeAmstradScrPk(content, contentOffset, contentLength, unpacked, 320, 200))
							return true;
						break;
					case (byte) 'U':
						if (DecodeAmstradScrPk(content, contentOffset, contentLength, unpacked, 256, 192))
							return true;
						break;
					case (byte) 'V':
						if (UnpackConvImgCpc(content, contentOffset + 4, contentLength, unpacked, 31936) && unpacked[1536] == 0) {
							if (!SetAmstradFirmwarePalette(unpacked, 1537, 16))
								return false;
							SetSize(384, 272, RECOILResolution.Amstrad2x1);
							for (int y = 0; y < 272; y++)
								DecodeAmstradMode0Line(unpacked, GetAmstradLineOffset(y, 96, true), y);
							return true;
						}
						break;
					default:
						break;
					}
				}
				if (!AmstradStream.UnpackFile(content, contentOffset, contentLength, unpacked, 16384))
					return false;
				content = unpacked;
				contentOffset = 0;
				break;
			}
			int mode = SetAmstradPalette(filename);
			if (mode < 0) {
				int paletteOffset = contentOffset + (width == 384 ? 1536 : 6096);
				mode = content[paletteOffset];
				if (mode > 4 || !SetAmstradFirmwarePalette(content, paletteOffset + 1, 1 << (4 >> mode % 3)))
					return false;
			}
			switch (mode) {
			case 0:
				SetSize(width, height, RECOILResolution.Amstrad2x1);
				for (int y = 0; y < height; y++)
					DecodeAmstradMode0Line(content, contentOffset + GetAmstradLineOffset(y, width >> 2, overscan), y);
				return true;
			case 1:
				SetSize(width, height, RECOILResolution.Amstrad1x1);
				for (int y = 0; y < height; y++)
					DecodeAmstradMode1Line(content, contentOffset + GetAmstradLineOffset(y, width >> 2, overscan), y);
				return true;
			case 2:
				return DecodeAmstradMode2(content, contentOffset, width << 1, height, overscan);
			case 3:
				SetSize(width, height, RECOILResolution.Amstrad1x1);
				for (int y = 0; y < height; y += 2) {
					int lineOffset = contentOffset + GetAmstradLineOffset(y, width >> 2, overscan);
					DecodeAmstradMode1Line(content, lineOffset, y);
					DecodeAmstradMode0Line(content, lineOffset + 2048, y + 1);
				}
				return true;
			case 4:
				if (width != 320)
					return false;
				int yEgx = content[contentOffset + 14309] - 141;
				if (yEgx >> 1 != 0)
					return false;
				SetSize(640, 400, RECOILResolution.Amstrad1x2);
				for (int y = 0; y < 200; y++) {
					int lineOffset = contentOffset + GetAmstradLineOffset(y, 80, false);
					if (((y ^ yEgx) & 1) == 0)
						DecodeAmstradMode2Line(content, lineOffset, y);
					else {
						for (int x = 0; x < 320; x++) {
							int offset = y * 1280 + (x << 1);
							int b = content[lineOffset + (x >> 2)];
							this.Pixels[offset + 641] = this.Pixels[offset + 640] = this.Pixels[offset + 1] = this.Pixels[offset] = this.ContentPalette[GetAmstradMode1Index(x, b)];
						}
					}
				}
				return true;
			default:
				return false;
			}
		}

		bool DecodeWin(string filename, byte[] content, int contentLength)
		{
			if (contentLength < 6)
				return false;
			int width = content[contentLength - 4] | content[contentLength - 3] << 8;
			if (width == 0 || width > 640)
				return false;
			int height = content[contentLength - 2];
			if (height == 0 || height > 200)
				return false;
			int bytesPerLine = (width + 7) >> 3;
			byte[] unpacked = new byte[16000];
			int contentOffset = GetAmstradHeader(content, contentLength);
			if (contentLength != contentOffset + bytesPerLine * height + 5) {
				if (!AmstradStream.UnpackFile(content, contentOffset, contentLength, unpacked, bytesPerLine * height))
					return false;
				content = unpacked;
				contentOffset = 0;
			}
			if (SetAmstradPalette(filename) != 0)
				return false;
			width >>= 1;
			SetSize(width, height, RECOILResolution.Amstrad2x1);
			for (int y = 0; y < height; y++)
				DecodeAmstradMode0Line(content, contentOffset + y * bytesPerLine, y);
			return true;
		}

		bool DecodeCm5(string filename, byte[] content, int contentLength)
		{
			if (contentLength != 2049)
				return false;
			byte[] gfx = new byte[18433];
			if (ReadCompanionFile(filename, "GFX", "gfx", gfx, 18433) != 18432)
				return false;
			SetSize(288, 256, RECOILResolution.Amstrad1x1);
			for (int y = 0; y < 256; y++) {
				for (int x = 0; x < 288; x++) {
					int c;
					switch (gfx[y * 72 + (x >> 2)] >> (~x & 3) & 17) {
					case 0:
						c = 3 + (y << 3) + x / 48;
						break;
					case 1:
						c = 1 + (y << 3);
						break;
					case 16:
						c = 2 + (y << 3);
						break;
					default:
						c = 0;
						break;
					}
					c = content[c];
					if (c < 64 || c > 95)
						return false;
					this.Pixels[y * 288 + x] = AmstradPalette[c - 64];
				}
			}
			return true;
		}

		bool DecodeSgx(byte[] content, int contentLength)
		{
			int width = 0;
			int height = 0;
			int chunkLeft = 0;
			int rowHeight = 0;
			for (int contentOffset = 0; contentOffset + 3 < contentLength;) {
				int chunkStride = content[contentOffset];
				if (chunkStride == 0)
					break;
				if (chunkStride == 255) {
					if (width == 0)
						width = chunkLeft;
					else if (chunkLeft != width)
						return false;
					chunkLeft = 0;
					contentOffset += 3;
				}
				else {
					int chunkWidth;
					int chunkHeight;
					if (chunkStride <= 63) {
						chunkWidth = content[contentOffset + 1];
						if ((chunkWidth + 3) >> 2 != chunkStride)
							return false;
						chunkHeight = content[contentOffset + 2];
						contentOffset += 3;
					}
					else if (chunkStride == 64) {
						if (contentOffset + 8 >= contentLength || content[contentOffset + 1] != 5)
							return false;
						chunkStride = content[contentOffset + 2] | content[contentOffset + 3] << 8;
						chunkWidth = content[contentOffset + 4] | content[contentOffset + 5] << 8;
						if ((chunkWidth + 1) >> 1 != chunkStride)
							return false;
						chunkHeight = content[contentOffset + 6] | content[contentOffset + 7] << 8;
						contentOffset += 8;
					}
					else
						return false;
					if (chunkLeft == 0)
						height += rowHeight = chunkHeight;
					else if (chunkHeight != rowHeight)
						return false;
					chunkLeft += chunkWidth;
					contentOffset += chunkHeight * chunkStride;
					if (contentOffset > contentLength)
						return false;
				}
			}
			if (width == 0)
				width = chunkLeft;
			else if (chunkLeft != width)
				return false;
			if (!SetSize(width, height, RECOILResolution.Amstrad1x1))
				return false;
			chunkLeft = 0;
			int chunkTop = 0;
			rowHeight = 0;
			for (int contentOffset = 0; contentOffset + 3 < contentLength;) {
				int chunkStride = content[contentOffset];
				if (chunkStride == 0)
					break;
				if (chunkStride == 255) {
					chunkLeft = 0;
					chunkTop += rowHeight;
					contentOffset += 3;
				}
				else {
					int chunkWidth;
					if (chunkStride <= 63) {
						chunkWidth = content[contentOffset + 1];
						rowHeight = content[contentOffset + 2];
						contentOffset += 3;
						for (int y = 0; y < rowHeight; y++) {
							for (int x = 0; x < chunkWidth; x++) {
								int b = content[contentOffset + (x >> 2)] >> (~x & 3);
								this.Pixels[(chunkTop + y) * width + chunkLeft + x] = DecodeSgx_palette4[(b >> 3 & 2) + (b & 1)];
							}
							contentOffset += chunkStride;
						}
					}
					else {
						chunkStride = content[contentOffset + 2] | content[contentOffset + 3] << 8;
						chunkWidth = content[contentOffset + 4] | content[contentOffset + 5] << 8;
						rowHeight = content[contentOffset + 6] | content[contentOffset + 7] << 8;
						contentOffset += 8;
						for (int y = 0; y < rowHeight; y++) {
							for (int x = 0; x < chunkWidth; x++) {
								int c = GetNibble(content, contentOffset, x);
								this.Pixels[(chunkTop + y) * width + chunkLeft + x] = DecodeSgx_palette16[c];
							}
							contentOffset += chunkStride;
						}
					}
					chunkLeft += chunkWidth;
				}
			}
			return true;
		}

		bool SetAmstradFirmwarePalette16(byte[] content) { return content[5] == 1 && SetAmstradFirmwarePalette(content, 6, 16); }

		bool DecodePphFrame(string filename, string upperExt, string lowerExt, byte[] bitmap, byte[] pph, int frame)
		{
			int bitmapStride = this.Width >> 2;
			int bitmapLength = this.Height * bitmapStride;
			if (ReadCompanionFile(filename, upperExt, lowerExt, bitmap, bitmapLength + 1) != bitmapLength)
				return false;
			int yOffset = frame * this.Height;
			switch (pph[0]) {
			case 3:
				for (int y = 0; y < this.Height; y++)
					DecodeAmstradMode0Line(bitmap, y * bitmapStride, yOffset + y, (y ^ frame) & 1);
				break;
			case 4:
				for (int y = 0; y < this.Height; y++)
					DecodeAmstradMode0Line(bitmap, y * bitmapStride, yOffset + y);
				break;
			case 5:
				int paletteOffset = 6;
				int paletteLines = 0;
				for (int y = 0; y < this.Height; y++) {
					if (paletteLines == 0) {
						if (!SetAmstradFirmwarePalette(pph, paletteOffset, 4))
							return false;
						paletteOffset += 4;
						if (paletteOffset < (1 + pph[5]) * 5) {
							paletteLines = pph[paletteOffset++];
							if (paletteLines == 0)
								return false;
						}
						else
							paletteLines = 272;
					}
					DecodeAmstradMode1Line(bitmap, y * bitmapStride, yOffset + y);
					paletteLines--;
				}
				break;
			default:
				throw new NotImplementedException();
			}
			return true;
		}

		bool DecodePph(string filename, byte[] content, int contentLength)
		{
			if (contentLength < 10)
				return false;
			RECOILResolution resolution;
			switch (content[0]) {
			case 3:
				if (contentLength != 22 || !SetAmstradFirmwarePalette16(content))
					return false;
				resolution = RECOILResolution.Amstrad1x1;
				break;
			case 4:
				if (contentLength != 22 || !SetAmstradFirmwarePalette16(content))
					return false;
				resolution = RECOILResolution.Amstrad2x1;
				break;
			case 5:
				if (contentLength != (1 + content[5]) * 5)
					return false;
				resolution = RECOILResolution.Amstrad1x1;
				break;
			default:
				return false;
			}
			int width = content[1] | content[2] << 8;
			if (width == 0 || width > 384 || (width & 3) != 0)
				return false;
			int height = content[3] | content[4] << 8;
			if (height == 0 || height > 272)
