				int transparent = content[offset];
				if (transparent > 1)
					return false;
				int columns = content[offset + 1];
				int rows = content[offset + 2];
				if (offset + 3 + rows * columns * (9 - transparent) > contentLength)
					return false;
				if (maxColumns < columns)
