				return false;
			int bitmapOffset = s.ContentOffset;
			int width = 0;
			int height = 0;
			for (int x = 0;;) {
				switch (s.ReadChar()) {
				case '*':
				case '0':
				case '1':
					x++;
					continue;
				case '\n':
					break;
				default:
					return false;
				}
				if (x == 0)
					break;
				if (height == 0)
					width = x;
				else if (x != width)
					return false;
				height++;
				x = 0;
			}
			int attributesOffset = s.ContentOffset;
			int attributesHeight = 0;
			RECOILResolution resolution = RECOILResolution.Spectrum1x1;
			SetZxPalette();
