							return false;
						b = s.ReadHexByte();
						if (b < 0)
							return false;
						this.ContentPalette[i] = GetG3R3B2Color(b);
					}
					if (s.ReadChar() != '\n' || !s.IsEof())
						return false;
					resolution = RECOILResolution.SpectrumUlaPlus1x1;
					break;
				}
				if (s.ReadHexByte() < 0)
					return false;
				switch (s.ReadChar()) {
				case ' ':
					break;
				case '\n':
					attributesHeight++;
					break;
				default:
					return false;
				}
			}
			if ((attributesHeight != height && attributesHeight != (height + 7) >> 3) || !SetSize(width, height, resolution))
				return false;
			s.ContentOffset = attributesOffset;
			for (int y = 0; y < height; y++) {
				if (attributesHeight != height) {
					if ((y & 7) == 0)
						attributesOffset = s.ContentOffset;
					else
						s.ContentOffset = attributesOffset;
				}
				int a = 0;
				for (int x = 0; x < width; x++) {
					if ((x & 7) == 0) {
						if (x > 0 && s.ReadChar() != ' ')
							return false;
						a = s.ReadHexByte();
					}
					this.Pixels[y * width + x] = this.ContentPalette[(a >> 2 & 48) | (content[bitmapOffset++] != '1' ? 8 | (a >> 3 & 7) : a & 7)];
				}
				if (content[bitmapOffset] == '\r')
					bitmapOffset++;
				if (content[bitmapOffset++] != '\n' || s.ReadChar() != '\n')
					return false;
			}
			return true;
		}

