		static readonly byte[] Msx2DefaultPalette = { 0, 0, 0, 0, 17, 6, 51, 7, 23, 1, 39, 3, 81, 1, 39, 6,
			113, 1, 115, 3, 97, 6, 100, 6, 17, 4, 101, 2, 85, 5, 119, 7 };

		static int GetMsxHeader(byte[] content)
		{
			if (content[1] != 0 || content[2] != 0 || content[5] != 0 || content[6] != 0)
				return -1;
			return content[3] | content[4] << 8;
		}

		static bool IsMsxPalette(byte[] content, int contentOffset)
		{
			int ored = 0;
			for (int i = 0; i < 16; i++) {
				int rb = content[contentOffset + (i << 1)];
				int g = content[contentOffset + (i << 1) + 1];
				if ((rb & 136) != 0 || (g & 248) != 0)
					return false;
				ored |= rb | g;
			}
			return ored != 0;
		}

		void SetMsxPalette(byte[] content, int contentOffset, int colors)
		{
			for (int i = 0; i < colors; i++) {
				int rb = content[contentOffset + (i << 1)];
				int g = content[contentOffset + (i << 1) + 1];
				int rgb = (rb & 112) << 12 | (rb & 7) | (g & 7) << 8;
				this.ContentPalette[i] = rgb << 5 | rgb << 2 | (rgb >> 1 & 197379);
			}
		}

		void SetMsx2Palette(byte[] content, int contentOffset, int contentLength)
		{
			if (contentLength >= contentOffset + 32)
				SetMsxPalette(content, contentOffset, 16);
			else
				SetMsxPalette(Msx2DefaultPalette, 0, 16);
		}

		void DecodeSc2Sc4(byte[] content, int contentOffset, RECOILResolution resolution)
		{
			SetSize(256, 192, resolution);
			for (int y = 0; y < 192; y++) {
				int fontOffset = contentOffset + ((y & 192) << 5) + (y & 7);
				for (int x = 0; x < 256; x++) {
					int b = fontOffset + (content[contentOffset + 6144 + ((y & ~7) << 2) + (x >> 3)] << 3);
					int c = content[8192 + b];
					this.Pixels[(y << 8) + x] = this.ContentPalette[(content[b] >> (~x & 7) & 1) == 0 ? c & 15 : c >> 4];
				}
			}
		}

		void DecodeMsxSprites(byte[] content, int mode, int attributesOffset, int patternsOffset)
		{
			int height = mode <= 4 ? 192 : 212;
			for (int y = 0; y < height; y++) {
				for (int x = 0; x < 256; x++) {
					int color = 0;
					bool enableOr = false;
					int spritesPerLine = mode >= 4 ? 8 : 4;
					for (int sprite = 0; sprite < 32; sprite++) {
						int attributeOffset = attributesOffset + (sprite << 2);
						int spriteY = content[attributeOffset];
						if (spriteY == (mode >= 4 ? 216 : 208))
							break;
						int row = (y - spriteY - 1) & 255;
						if (row >= 16)
							continue;
						if (--spritesPerLine < 0)
							break;
						int c = content[mode >= 4 ? attributesOffset - 512 + (sprite << 4) + row : attributeOffset + 3];
						if (mode < 4 || (c & 64) == 0) {
							if (color != 0)
								break;
							enableOr = true;
						}
						else if (!enableOr)
							continue;
						int column = x - content[attributeOffset + 1];
						if (c >= 128)
							column += 32;
						if (column < 0 || column >= 16)
							continue;
						int pattern = patternsOffset + ((content[attributeOffset + 2] & 252) << 3) + row;
						if ((content[pattern + ((column & 8) << 1)] >> (~column & 7) & 1) == 0)
							continue;
						color |= c;
						if (mode >= 4)
							color |= 16;
					}
					if (color != 0) {
						int offset;
						switch (mode) {
						case 6:
							offset = (y << 10) + (x << 1);
							this.Pixels[offset + 512] = this.Pixels[offset] = this.ContentPalette[color >> 2 & 3];
							this.Pixels[offset + 513] = this.Pixels[offset + 1] = this.ContentPalette[color & 3];
							break;
						case 7:
							offset = (y << 10) + (x << 1);
							this.Pixels[offset + 513] = this.Pixels[offset + 512] = this.Pixels[offset + 1] = this.Pixels[offset] = this.ContentPalette[color & 15];
							break;
						default:
							this.Pixels[(y << 8) + x] = this.ContentPalette[color & 15];
							break;
						}
					}
				}
			}
		}

		bool DecodeSc2(byte[] content, int contentLength)
		{
			if (contentLength < 14343 || content[0] != 254 || GetMsxHeader(content) < 14335)
				return false;
			if (IsMsxPalette(content, 7047)) {
				SetMsxPalette(content, 7047, 16);
				DecodeSc2Sc4(content, 7, RECOILResolution.Msx21x1);
			}
			else {
				SetMsx1Palette();
				DecodeSc2Sc4(content, 7, RECOILResolution.Msx11x1);
			}
			if (contentLength == 16391)
				DecodeMsxSprites(content, 2, 6919, 14343);
			return true;
		}

		void DecodeSc3Screen(byte[] content, int contentOffset, bool isLong)
		{
			SetSize(256, 192, RECOILResolution.Msx14x4);
			for (int y = 0; y < 192; y++) {
