					c = content[contentOffset + (c << 3) + (y >> 2 & 7)] >> (~x & 4) & 15;
					this.Pixels[(y << 8) + x] = this.ContentPalette[c];
				}
			}
		}

		bool DecodeSc3(byte[] content, int contentLength)
		{
			if (contentLength < 1543 || content[0] != 254 || GetMsxHeader(content) < 1535)
				return false;
			if (contentLength >= 8263 && IsMsxPalette(content, 8231))
				SetMsxPalette(content, 8231, 16);
			else
				SetMsx1Palette();
			DecodeSc3Screen(content, 7, contentLength >= 2823);
			if (contentLength == 16391)
				DecodeMsxSprites(content, 3, 6919, 14343);
			return true;
		}

		bool DecodeSc4(byte[] content, int contentLength)
		{
			if (contentLength < 14343 || content[0] != 254 || GetMsxHeader(content) < 14335)
				return false;
			if (IsMsxPalette(content, 7047))
				SetMsxPalette(content, 7047, 16);
			else
				SetMsxPalette(Msx2DefaultPalette, 0, 16);
			DecodeSc2Sc4(content, 7, RECOILResolution.Msx21x1);
			if (contentLength >= 16391)
				DecodeMsxSprites(content, 4, 7687, 14343);
			return true;
		}

		int GetMsx128Height(byte[] content, int contentLength, bool sr)
		{
			if (contentLength < 135 || content[0] != 254)
				return -1;
			int header = GetMsxHeader(content);
			if (header < 127)
				return -1;
			int height = (header + 1) >> 7;
			if (contentLength < 7 + (height << 7))
				return -1;
			if (sr && height == 256)
				return 256;
			return Math.Min(height, 212);
		}

		static int ClampU5(int x) { return x < 0 ? 0 : x > 31 ? 31 : x; }

		int DecodeMsxYjk(byte[] content, int contentOffset, int x, int width, bool usePalette)
		{
			int y = content[contentOffset + x] >> 3;
			if (usePalette && (y & 1) != 0)
				return this.ContentPalette[y >> 1];
			int rgb;
			if ((x | 3) >= width) {
				rgb = y * 65793;
			}
			else {
				x = contentOffset + (x & ~3);
				int k = (content[x] & 7) | (content[x + 1] & 7) << 3;
				int j = (content[x + 2] & 7) | (content[x + 3] & 7) << 3;
				k -= (k & 32) << 1;
				j -= (j & 32) << 1;
				int r = ClampU5(y + j);
				int g = ClampU5(y + k);
				int b = ClampU5((5 * y - 2 * j - k + 2) >> 2);
				rgb = r << 16 | g << 8 | b;
			}
			return rgb << 3 | (rgb >> 2 & 460551);
		}

		void DecodeMsxScreen(byte[] content, int contentOffset, byte[] interlace, int height, int mode, int interlaceMask)
		{
			if (interlaceMask != 0) {
				SetSize(512, height << 1, mode >= 10 ? RECOILResolution.Msx2Plus2x1i : mode >> 1 == 3 ? RECOILResolution.Msx21x1i : RECOILResolution.Msx22x1i);
				this.Frames = 2;
			}
			else if (mode >> 1 == 3)
				SetSize(512, height << 1, RECOILResolution.Msx21x2);
			else
				SetSize(256, height, mode >= 10 ? RECOILResolution.Msx2Plus1x1 : RECOILResolution.Msx21x1);
			for (int y = 0; y < this.Height; y++) {
				byte[] screen = (y & interlaceMask) == 0 ? content : interlace;
				int screenOffset = (y & interlaceMask) == 0 || content != interlace ? contentOffset : contentOffset + (mode <= 6 ? 27143 : 54279);
				for (int x = 0; x < this.Width; x++) {
					int rgb = 0;
					switch (mode) {
					case 5:
						rgb = this.ContentPalette[GetNibble(screen, screenOffset + (y >> interlaceMask << 7), x >> interlaceMask)];
						break;
					case 6:
						rgb = this.ContentPalette[screen[screenOffset + (y >> 1 << 7) + (x >> 2)] >> ((~x & 3) << 1) & 3];
						break;
					case 7:
						rgb = this.ContentPalette[GetNibble(screen, screenOffset + (y >> 1 << 8), x)];
						break;
					case 8:
						rgb = this.ContentPalette[screen[screenOffset + (y >> interlaceMask << 8) + (x >> interlaceMask)]];
						break;
					case 10:
						rgb = DecodeMsxYjk(screen, screenOffset + (y >> interlaceMask << 8), x >> interlaceMask, 256, true);
						break;
					case 12:
						rgb = DecodeMsxYjk(screen, screenOffset + (y >> interlaceMask << 8), x >> interlaceMask, 256, false);
						break;
					default:
						throw new NotImplementedException();
					}
					this.Pixels[y * this.Width + x] = rgb;
				}
			}
		}

		bool DecodeMsxSc(string filename, byte[] content, int contentOffset, string upperExt, string lowerExt, int height, int mode)
		{
			if (filename != null) {
				byte[] interlace = new byte[54279];
				int interlaceLength = 7 + (height << (mode <= 6 ? 7 : 8));
				if (ReadCompanionFile(filename, upperExt, lowerExt, interlace, interlaceLength) == interlaceLength && interlace[0] == 254 && GetMsxHeader(interlace) >= interlaceLength - 8) {
					DecodeMsxScreen(content, contentOffset, interlace, height, mode, 1);
					return true;
				}
			}
			DecodeMsxScreen(content, contentOffset, null, height, mode, 0);
			return false;
		}

		bool DecodeSc5(string filename, byte[] content, int contentLength)
		{
			int height = GetMsx128Height(content, contentLength, false);
			if (height <= 0)
				return false;
			SetMsx2Palette(content, 30343, contentLength);
			if (!DecodeMsxSc(filename, content, 7, "S15", "s15", height, 5) && contentLength == 32775)
				DecodeMsxSprites(content, 5, 30215, 30727);
			return true;
		}

		void SetMsxCompanionPalette(string filename, string upperExt, string lowerExt)
		{
			byte[] palette = new byte[32];
			SetMsxPalette(ReadCompanionFile(filename, upperExt, lowerExt, palette, 32) == 32 ? palette : Msx2DefaultPalette, 0, 16);
		}

		bool DecodeSr5(string filename, byte[] content, int contentLength)
		{
			int height = GetMsx128Height(content, contentLength, true);
			if (height <= 0)
				return false;
			SetMsxCompanionPalette(filename, "PL5", "pl5");
			SetSize(256, height, RECOILResolution.Msx21x1);
			DecodeNibbles(content, 7, 128);
			return true;
		}

		bool DecodeMsx6(byte[] content, int contentOffset)
		{
			int height = GetOriginalHeight();
			for (int y = 0; y < height; y++) {
				for (int x = 0; x < this.Width; x++) {
					int offset = y * this.Width + x;
					int b = content[contentOffset + (offset >> 2)];
					SetScaledPixel(x, y, this.ContentPalette[b >> ((~offset & 3) << 1) & 3]);
				}
			}
			return true;
		}

		void SetMsx6DefaultPalette()
		{
			this.ContentPalette[0] = 0;
			this.ContentPalette[1] = 2396708;
			this.ContentPalette[2] = 2415396;
			this.ContentPalette[3] = 7208813;
		}

		bool DecodeSc6(string filename, byte[] content, int contentLength)
		{
			int height = GetMsx128Height(content, contentLength, false);
			if (height <= 0)
				return false;
			if (contentLength >= 30351)
				SetMsxPalette(content, 30343, 4);
			else
				SetMsx6DefaultPalette();
			if (!DecodeMsxSc(filename, content, 7, "S16", "s16", height, 6) && contentLength == 32775)
				DecodeMsxSprites(content, 6, 30215, 30727);
			return true;
		}

		void SetMsx6Palette(string filename)
		{
			byte[] palette = new byte[8];
			if (ReadCompanionFile(filename, "PL6", "pl6", palette, 8) == 8)
				SetMsxPalette(palette, 0, 4);
			else
				SetMsx6DefaultPalette();
		}

		bool DecodeSr6(string filename, byte[] content, int contentLength)
		{
			int height = GetMsx128Height(content, contentLength, true);
			if (height <= 0)
				return false;
			SetSize(512, height << 1, RECOILResolution.Msx21x2);
			SetMsx6Palette(filename);
			return DecodeMsx6(content, 7);
		}

		bool DecodeGl6(string filename, byte[] content, int contentLength)
		{
			if (contentLength < 5)
				return false;
			int width = content[0] | content[1] << 8;
			int height = content[2] | content[3] << 8;
			if (contentLength < 4 + ((width * height + 3) >> 2) || !SetSize(width, height << 1, RECOILResolution.Msx21x2))
				return false;
			if (filename != null)
				SetMsx6Palette(filename);
			else {
				this.ContentPalette[0] = 16777215;
				this.ContentPalette[1] = 0;
				this.ContentPalette[3] = this.ContentPalette[2] = 0;
			}
			return DecodeMsx6(content, 4);
		}

		static byte[] UnpackSr(byte[] content, int contentLength, byte[] unpacked)
		{
			if (contentLength < 7)
				return null;
			switch (content[0]) {
			case 254:
				if (contentLength < 54279 || GetMsxHeader(content) < 54271)
					return null;
				return content;
			case 253:
				if (7 + GetMsxHeader(content) != contentLength)
					return null;
				SrStream rle = new SrStream { Content = content, ContentOffset = 7, ContentLength = contentLength };
				rle.Unpack(unpacked, 7, 1, 54279);
				return unpacked;
			default:
				return null;
			}
		}

		bool DecodeSc7(string filename, byte[] content, int contentLength)
		{
			if (contentLength < 54279 || content[0] != 254 || GetMsxHeader(content) < 54271)
				return false;
			SetMsx2Palette(content, 64135, contentLength);
			if (!DecodeMsxSc(filename, content, 7, "S17", "s17", 212, 7) && contentLength == 64167)
				DecodeMsxSprites(content, 7, 64007, 61447);
			return true;
		}

		bool DecodeSri(string filename, byte[] content, int contentLength)
		{
			if (contentLength != 108544)
				return false;
			SetMsxCompanionPalette(filename, "PL7", "pl7");
			SetSize(512, 424, RECOILResolution.Msx21x1i);
			this.Frames = 2;
			DecodeNibbles(content, 0, 256);
			return true;
		}

		static bool IsMsx256Lines(byte[] content, int contentLength) { return contentLength == 65543 && content[0] == 254 && GetMsxHeader(content) == 65535; }

		bool DecodeSr7(string filename, byte[] content, int contentLength)
		{
			byte[] unpacked = new byte[54279];
			int height;
			if (IsMsx256Lines(content, contentLength))
				height = 512;
			else {
				byte[] source = UnpackSr(content, contentLength, unpacked);
				if (source == null)
					return false;
				content = source;
				height = 424;
			}
			SetMsxCompanionPalette(filename, "PL7", "pl7");
			SetSize(512, height, RECOILResolution.Msx21x2);
			DecodeNibbles(content, 7, 256);
			return true;
		}

		bool DecodeGl16(string filename, byte[] content, int contentLength, RECOILResolution resolution, string upperExt, string lowerExt)
		{
			if (contentLength < 5)
				return false;
			int width = content[0] | content[1] << 8;
			int height = content[2] | content[3] << 8;
			if (contentLength < 4 + ((width * height + 1) >> 1) || !SetScaledSize(width, height, resolution))
				return false;
			SetMsxCompanionPalette(filename, upperExt, lowerExt);
			for (int y = 0; y < height; y++)
				for (int x = 0; x < width; x++)
					SetScaledPixel(x, y, this.ContentPalette[GetNibble(content, 4, y * width + x)]);
			return true;
		}

		bool DecodeGl5(string filename, byte[] content, int contentLength) { return DecodeGl16(filename, content, contentLength, RECOILResolution.Msx21x1, "PL5", "pl5"); }

		bool DecodeGl7(string filename, byte[] content, int contentLength) { return DecodeGl16(filename, content, contentLength, RECOILResolution.Msx21x2, "PL7", "pl7"); }

		void SetSc8Palette()
		{
			for (int c = 0; c < 256; c++) {
				int rgb = (c & 28) << 14 | (c & 224) << 3 | SetSc8Palette_blues[c & 3];
				this.ContentPalette[c] = rgb << 5 | rgb << 2 | (rgb >> 1 & 197379);
			}
		}

		bool DecodeSc8(string filename, byte[] content, int contentLength)
		{
			byte[] unpacked = new byte[54279];
			int height;
			if (IsMsx256Lines(content, contentLength))
				height = 256;
			else {
				byte[] source = UnpackSr(content, contentLength, unpacked);
				if (source == null)
					return false;
				content = source;
				height = 212;
			}
			SetSc8Palette();
			if (!DecodeMsxSc(filename, content, 7, "S18", "s18", height, 8) && contentLength == 64167) {
				SetMsxPalette(DecodeSc8_spritePalette, 0, 16);
				DecodeMsxSprites(content, 8, 64007, 61447);
			}
			return true;
		}

		bool DecodeGl8(byte[] content, int contentLength)
		{
			if (contentLength < 5)
				return false;
			int width = content[0] | content[1] << 8;
			int height = content[2] | content[3] << 8;
			if (contentLength != 4 + width * height || !SetSize(width, height, RECOILResolution.Msx21x1))
				return false;
			SetSc8Palette();
			DecodeBytes(content, 4);
			return true;
		}

		bool DecodePct(byte[] content, int contentLength)
		{
			if (contentLength < 384 || (!IsStringAt(content, 0, "DYNAMIC") && !IsStringAt(content, 0, "E U R O")) || !IsStringAt(content, 7, " PUBLISHER "))
				return false;
			int height;
			int contentOffset;
			if (IsStringAt(content, 18, "SCREEN")) {
				height = 704;
				contentOffset = 384;
			}
			else if (IsStringAt(content, 18, "FONT")) {
				height = 160;
				contentOffset = 512;
			}
			else
				return false;
			SetSize(512, height << 1, RECOILResolution.Msx21x2);
			CciStream rle = new CciStream { Content = content, ContentOffset = contentOffset, ContentLength = contentLength };
			for (int y = 0; y < height; y++) {
				int b = 0;
				for (int x = 0; x < 512; x++) {
					if ((x & 7) == 0) {
						b = rle.ReadRle();
						if (b < 0)
							return false;
					}
					int offset = (y << 10) + x;
					this.Pixels[offset + 512] = this.Pixels[offset] = (b >> ((x ^ 3) & 7) & 1) == 0 ? 16777215 : 0;
				}
			}
			return true;
		}

		bool DecodeDdGraph(string filename, byte[] content, int contentLength)
		{
			if (contentLength < 4)
				return false;
			int width = content[0];
			if (width == 0 || width > 128)
				return false;
			int height = content[1];
			if (height == 0 || height > 212)
				return false;
			int verbatimLines = content[2];
			if (verbatimLines == 0 || verbatimLines > height)
				return false;
			ZimStream stream = new ZimStream { Content = content, ContentOffset = 3, ContentLength = contentLength };
			int flagsOffset = 64;
			byte[] unpacked = new byte[27136];
			int unpackedOffset = 0;
			for (int y = 0; y < height; y++) {
				for (int x = 0; x < width; x++) {
					if (flagsOffset >= 64) {
						if (!stream.UnpackFlags2())
							return false;
						flagsOffset = 0;
					}
					int b = stream.ReadUnpacked(stream.Flags2, flagsOffset++);
					if (b < 0)
						return false;
					if (y >= verbatimLines)
						b ^= unpacked[unpackedOffset - width];
					unpacked[unpackedOffset++] = (byte) b;
				}
			}
			if (stream.ContentOffset != stream.ContentLength)
				return false;
			SetMsxCompanionPalette(filename, "PL5", "pl5");
			SetSize(width << 1, height, RECOILResolution.Msx21x1);
			DecodeNibbles(unpacked, 0, width);
			return true;
		}

		void DecodeMsxYjkScreen(byte[] content, int contentOffset, bool usePalette)
		{
			int width = GetOriginalWidth();
			for (int y = 0; y < this.Height; y++)
				for (int x = 0; x < width; x++)
					SetScaledPixel(x, y, DecodeMsxYjk(content, contentOffset + y * width, x, width, usePalette));
		}

		void DecodeSccSca(string filename, byte[] content, int contentLength, int height, bool usePalette)
		{
			if (!DecodeMsxSc(filename, content, 7, usePalette ? "S1A" : "S1C", usePalette ? "s1a" : "s1c", height, usePalette ? 10 : 12) && contentLength == 64167 && content[0] == 254) {
				SetMsxPalette(content, 64135, 16);
				DecodeMsxSprites(content, 12, 64007, 61447);
			}
		}

		bool DecodeScc(string filename, byte[] content, int contentLength)
		{
			int height;
			if (IsMsx256Lines(content, contentLength))
				height = 256;
			else if (contentLength >= 49159 && content[0] == 254 && GetMsxHeader(content) == 49151)
				height = 192;
			else {
				byte[] unpacked = new byte[54279];
				byte[] source = UnpackSr(content, contentLength, unpacked);
				if (source == null)
					return false;
				content = source;
				height = 212;
			}
			DecodeSccSca(filename, content, contentLength, height, false);
			return true;
		}

		bool DecodeSca(string filename, byte[] content, int contentLength)
		{
			if (contentLength < 64167 || content[0] != 254 || GetMsxHeader(content) < 54271)
				return false;
			int height;
			if (IsMsx256Lines(content, contentLength)) {
				SetMsxCompanionPalette(filename, "PLA", "pla");
				height = 256;
			}
			else {
				SetMsxPalette(content, 64135, 16);
				height = 212;
			}
			DecodeSccSca(filename, content, contentLength, height, true);
			return true;
		}

		bool DecodeGlYjk(string filename, byte[] content, int contentLength)
		{
			if (contentLength < 8)
				return false;
			int width = content[0] | content[1] << 8;
			int height = content[2] | content[3] << 8;
			if (contentLength != 4 + width * height || !SetSize(width, height, RECOILResolution.Msx2Plus1x1))
				return false;
			if (filename != null)
				SetMsxCompanionPalette(filename, "PLA", "pla");
			DecodeMsxYjkScreen(content, 4, filename != null);
			return true;
		}

		bool SetG9bPalette(byte[] content, int colors)
		{
			for (int c = 0; c < colors; c++) {
				int rgb = GetR8G8B8Color(content, 16 + c * 3);
				if ((rgb & 14737632) != 0)
					return false;
				this.ContentPalette[c] = rgb << 3 | (rgb >> 2 & 460551);
			}
			return true;
		}

		const int G9bYjk = 0;

		const int G9bYuv = 1;

		void DecodeG9bUnpacked(byte[] content, int depth, int headerLength)
		{
			int pixelsLength;
			switch (depth) {
			case 2:
				DecodeMsx6(content, 28);
				break;
			case 4:
				DecodeNibbles(content, 64, (this.Width + 1) >> 1);
				break;
			case 8:
				DecodeBytes(content, headerLength);
				break;
			case 0:
				DecodeMsxYjkScreen(content, 16, false);
				break;
			case 1:
				pixelsLength = this.Width * this.Height;
				for (int i = 0; i < pixelsLength; i++) {
					int y = content[16 + i] >> 3;
					int x = 16 + (i & ~3);
					int v = (content[x] & 7) | (content[x + 1] & 7) << 3;
					int u = (content[x + 2] & 7) | (content[x + 3] & 7) << 3;
					u -= (u & 32) << 1;
					v -= (v & 32) << 1;
					int r = ClampU5(y + u);
					int g = ClampU5((((5 * y - v) >> 1) - u) >> 1);
					int b = ClampU5(y + v);
					int rgb = r << 16 | g << 8 | b;
					this.Pixels[i] = rgb << 3 | (rgb >> 2 & 460551);
				}
				break;
			case 16:
				pixelsLength = this.Width * this.Height;
				for (int i = 0; i < pixelsLength; i++) {
					int c = content[16 + (i << 1)] | content[17 + (i << 1)] << 8;
					int rgb = (c & 992) << 14 | (c & 31744) << 1 | (c & 31) << 3;
					this.Pixels[i] = rgb | (rgb >> 5 & 460551);
				}
				break;
			default:
				throw new NotImplementedException();
			}
		}

		bool DecodeG9b(byte[] content, int contentLength)
		{
			if (contentLength < 17 || content[0] != 'G' || content[1] != '9' || content[2] != 'B' || content[3] != 11 || content[4] != 0)
				return false;
			int depth = content[5];
			int headerLength = 16 + content[7] * 3;
			int width = content[8] | content[9] << 8;
			int height = content[10] | content[11] << 8;
			if (contentLength <= headerLength || !SetSize(width, height, RECOILResolution.MsxV99901x1))
				return false;
			int unpackedLength = headerLength + ((width * depth + 7) >> 3) * height;
			switch (depth) {
			case 2:
				if (content[7] != 4 || !SetG9bPalette(content, 4))
					return false;
				break;
			case 4:
				if (content[7] != 16 || !SetG9bPalette(content, 16))
					return false;
				break;
			case 8:
				switch (content[7]) {
				case 0:
					if ((width & 3) != 0)
						return false;
					switch (content[6]) {
					case 64:
						SetSc8Palette();
						break;
					case 128:
						depth = 0;
						break;
					case 192:
						depth = 1;
						break;
					default:
						return false;
					}
					break;
				case 64:
					if (!SetG9bPalette(content, 64))
						return false;
					Array.Clear(this.ContentPalette, 64, 192);
					break;
				default:
					return false;
				}
				break;
			case 16:
				break;
			default:
				return false;
			}
			switch (content[12]) {
			case 0:
				if (contentLength != unpackedLength)
					return false;
				DecodeG9bUnpacked(content, depth, headerLength);
				return true;
			case 1:
				byte[] unpacked = new byte[unpackedLength];
				G9bStream s = new G9bStream { Content = content, ContentLength = contentLength };
				bool ok = s.Unpack(unpacked, headerLength, unpackedLength);
				if (ok)
					DecodeG9bUnpacked(unpacked, depth, headerLength);
				return ok;
			default:
				return false;
			}
		}

		bool UnpackMif(byte[] content, int contentLength, byte[] unpacked, int unpackedLength, bool palette)
		{
			BitStream s = new BitStream { Content = content, ContentOffset = palette ? 34 : 2, ContentLength = contentLength };
			int[] offsets = new int[5461];
			int codes = 0;
			int codeBits = 2;
			for (int unpackedOffset = 0; unpackedOffset < unpackedLength;) {
				if (codes >= 5461)
					return false;
				offsets[codes++] = unpackedOffset;
				if (codes >> codeBits != 0)
					codeBits++;
				switch (s.ReadBit()) {
				case 0:
					int code = s.ReadBits(codeBits);
					if (code < 0 || code >= codes)
						return false;
					if (code == codes - 1) {
						codes = 0;
						codeBits = 2;
						break;
					}
					int sourceOffset = offsets[code];
					int endOffset = offsets[code + 1];
					if (unpackedOffset + endOffset - sourceOffset >= unpackedLength)
						return false;
					do
						unpacked[unpackedOffset++] = unpacked[sourceOffset++];
					while (sourceOffset <= endOffset);
					break;
				case 1:
					int b = s.ReadBits(8);
					if (b < 0)
						return false;
					unpacked[unpackedOffset++] = (byte) b;
					break;
				default:
					return false;
				}
			}
			if (s.ReadBit() != 0 || s.ReadBits(codeBits) <= codes || s.ContentOffset != contentLength)
				return false;
			if (palette)
				SetMsxPalette(content, 2, 16);
			return true;
		}

		bool DecodeMif(byte[] content, int contentLength)
		{
			if (contentLength < 35)
				return false;
			byte[] unpacked = new byte[108544];
			switch (content[0]) {
			case 0:
				if (!UnpackMif(content, contentLength, unpacked, 27136, true))
					return false;
				SetSize(256, 212, RECOILResolution.Msx21x1);
				DecodeNibbles(unpacked, 0, 128);
				return true;
			case 1:
				if (!UnpackMif(content, contentLength, unpacked, 27136, true))
					return false;
				SetSize(512, 424, RECOILResolution.Msx21x2);
				DecodeMsx6(unpacked, 0);
				return true;
			case 2:
				if (!UnpackMif(content, contentLength, unpacked, 54272, true))
					return false;
				SetSize(512, 424, RECOILResolution.Msx21x2);
				DecodeNibbles(unpacked, 0, 256);
				return true;
			case 3:
				if (!UnpackMif(content, contentLength, unpacked, 54272, false))
					return false;
				SetSc8Palette();
				SetSize(256, 212, RECOILResolution.Msx21x1);
				DecodeBytes(unpacked, 0);
				return true;
			case 4:
				if (!UnpackMif(content, contentLength, unpacked, 54272, true))
					return false;
				SetSize(256, 212, RECOILResolution.Msx2Plus1x1);
				DecodeMsxYjkScreen(unpacked, 0, true);
				return true;
			case 5:
				if (!UnpackMif(content, contentLength, unpacked, 54272, false))
					return false;
				SetSize(256, 212, RECOILResolution.Msx2Plus1x1);
				DecodeMsxYjkScreen(unpacked, 0, false);
				return true;
			case 8:
				if (!UnpackMif(content, contentLength, unpacked, 14336, true))
					return false;
				DecodeSc2Sc4(unpacked, 0, RECOILResolution.Msx21x1);
				return true;
			case 9:
				if (!UnpackMif(content, contentLength, unpacked, 1536, true))
					return false;
				DecodeSc3Screen(unpacked, 0, false);
				return true;
			case 16:
				if (!UnpackMif(content, contentLength, unpacked, 54272, true))
					return false;
				SetSize(512, 424, RECOILResolution.Msx22x1i);
				this.Frames = 2;
				DecodeNibbles(unpacked, 0, 128);
				return true;
			case 17:
				if (!UnpackMif(content, contentLength, unpacked, 54272, true))
					return false;
				SetSize(512, 424, RECOILResolution.Msx21x1i);
				this.Frames = 2;
				DecodeMsx6(unpacked, 0);
				return true;
			case 18:
				if (!UnpackMif(content, contentLength, unpacked, 108544, true))
					return false;
				SetSize(512, 424, RECOILResolution.Msx21x1i);
				this.Frames = 2;
				DecodeNibbles(unpacked, 0, 256);
				return true;
			case 19:
				if (!UnpackMif(content, contentLength, unpacked, 108544, false))
					return false;
				SetSc8Palette();
				SetSize(512, 424, RECOILResolution.Msx22x1i);
				this.Frames = 2;
				DecodeBytes(unpacked, 0);
				return true;
			case 20:
				if (!UnpackMif(content, contentLength, unpacked, 108544, true))
					return false;
				SetSize(512, 424, RECOILResolution.Msx2Plus2x1i);
				this.Frames = 2;
				DecodeMsxYjkScreen(unpacked, 0, true);
				return true;
			case 21:
				if (!UnpackMif(content, contentLength, unpacked, 108544, false))
					return false;
				SetSize(512, 424, RECOILResolution.Msx2Plus2x1i);
				this.Frames = 2;
				DecodeMsxYjkScreen(unpacked, 0, false);
				return true;
			default:
				return false;
			}
		}

		static int GetMigMode(int reg0, int reg1, int reg19, int length) { return (reg0 & 14) | (reg1 & 24) << 1 | (reg19 & 24) << 3 | length << 8; }

		bool DecodeMig(byte[] content, int contentLength)
		{
			if (contentLength < 16 || !IsStringAt(content, 0, "MSXMIG") || Get32LittleEndian(content, 6) != contentLength - 6)
				return false;
			byte[] unpacked = new byte[108800];
			MigStream s = new MigStream { Content = content, ContentLength = contentLength };
			int unpackedLength = s.Unpack(unpacked);
			int colors = 0;
			byte[] registers = new byte[256];
			for (int unpackedOffset = 0; unpackedOffset < unpackedLength;) {
				switch (unpacked[unpackedOffset]) {
				case 0:
					if (unpackedOffset + 1 >= unpackedLength)
						return false;
					int c = unpacked[unpackedOffset + 1];
					if (unpackedOffset + 2 + c * 3 > unpackedLength)
						return false;
					for (int i = 0; i < c; i++) {
						int offset = unpackedOffset + 2 + i * 3;
						int r = unpacked[offset];
						int m = unpacked[offset + 2];
						registers[r] = (byte) ((registers[r] & ~m) | (unpacked[offset + 1] & m));
					}
					unpackedOffset += 2 + c * 3;
					break;
				case 1:
					if (unpackedOffset + 2 >= unpackedLength || unpacked[unpackedOffset + 1] != 0)
						return false;
					colors = unpacked[unpackedOffset + 2];
					if (unpackedOffset + 3 + (colors << 1) > unpackedLength)
						return false;
					SetMsxPalette(unpacked, unpackedOffset + 3, colors);
					unpackedOffset += 3 + (colors << 1);
					break;
				case 2:
					if (unpackedOffset + 7 >= unpackedLength || unpacked[unpackedOffset + 1] != 0 || unpacked[unpackedOffset + 2] != 0 || unpacked[unpackedOffset + 3] != 0 || unpacked[unpackedOffset + 4] != 0 || unpacked[unpackedOffset + 6] != 0)
						return false;
					int length = unpacked[unpackedOffset + 5];
					unpackedOffset += 7;
					int interlaceMask;
					switch (registers[9] & 12) {
					case 0:
						if (unpackedOffset + (length << 8) + 1 != unpackedLength)
							return false;
						interlaceMask = 0;
						break;
					case 12:
						if (unpackedOffset + (length << 9) + 7 + 1 != unpackedLength || unpacked[unpackedOffset + (length << 8)] != 2 || unpacked[unpackedOffset + (length << 8) + 1] != 0 || unpacked[unpackedOffset + (length << 8) + 4] != 0 || unpacked[unpackedOffset + (length << 8) + 5] != length || unpacked[unpackedOffset + (length << 8) + 6] != 0)
							return false;
						interlaceMask = 1;
						break;
					default:
						return false;
					}
					int mode;
					switch (GetMigMode(registers[0], registers[1], registers[25], length)) {
					case 14338:
						if (colors < 16 || interlaceMask != 0)
							return false;
						DecodeSc2Sc4(unpacked, unpackedOffset, RECOILResolution.Msx21x1);
						return true;
					case 1552:
						if (colors < 16 || interlaceMask != 0)
							return false;
						DecodeSc3Screen(unpacked, unpackedOffset, false);
						return true;
					case 27142:
						if (colors < 16)
							return false;
						mode = 5;
						break;
					case 27144:
						if (colors < 4)
							return false;
						mode = 6;
						break;
					case 54282:
						if (colors < 16)
							return false;
						mode = 7;
						break;
					case 54286:
						SetSc8Palette();
						mode = 8;
						break;
					case 54478:
						if (colors < 16)
							return false;
						mode = 10;
						break;
					case 54350:
						mode = 12;
						break;
					default:
						return false;
					}
					DecodeMsxScreen(unpacked, unpackedOffset, unpacked, 212, mode, interlaceMask);
					return true;
				default:
					return false;
				}
			}
			return false;
		}

		bool DecodeHgr(byte[] content, int contentLength)
		{
			if (contentLength < 8184)
				return false;
			SetSize(280, 192, RECOILResolution.AppleII1x1);
			for (int y = 0; y < 192; y++) {
				int lineOffset = (y & 7) << 10 | (y & 56) << 4 | (y >> 6) * 40;
				for (int x = 0; x < 280; x++) {
					int c = content[lineOffset + x / 7] >> x % 7 & 1;
					if (c != 0)
						c = 16777215;
					this.Pixels[y * 280 + x] = c;
				}
			}
			return true;
		}

		bool DecodeAppleIIDhr(byte[] content, int contentLength)
		{
			if (contentLength != 16384)
				return false;
			SetSize(560, 384, RECOILResolution.AppleIIe1x2);
			for (int y = 0; y < 192; y++) {
				int lineOffset = (y & 7) << 10 | (y & 56) << 4 | (y >> 6) * 40;
				for (int x = 0; x < 560; x++) {
					int b = x / 7;
					int c = content[((b & 1) << 13) + lineOffset + (b >> 1)] >> x % 7 & 1;
					if (c != 0)
						c = 16777215;
					int pixelsOffset = y * 1120 + x;
					this.Pixels[pixelsOffset + 560] = this.Pixels[pixelsOffset] = c;
				}
			}
			return true;
		}

		void SetAppleIIGSPalette(byte[] content, int contentOffset, int reverse)
		{
			for (int c = 0; c < 16; c++) {
				int offset = contentOffset + ((c ^ reverse) << 1);
				int gb = content[offset];
				int r = content[offset + 1] & 15;
				int g = gb >> 4;
				int b = gb & 15;
				int rgb = r << 16 | g << 8 | b;
				rgb |= rgb << 4;
				this.ContentPalette[c] = rgb;
			}
		}

		void DecodeShrLine(byte[] content, int y)
		{
			for (int x = 0; x < 320; x++)
				this.Pixels[y * 320 + x] = this.ContentPalette[GetNibble(content, y * 160, x)];
		}

		bool DecodeAppleIIShrUnpacked(byte[] content)
		{
			SetSize(320, 200, RECOILResolution.AppleIIGS1x1);
			for (int y = 0; y < 200; y++) {
				SetAppleIIGSPalette(content, 32256 + ((content[32000 + y] & 15) << 5), 0);
				DecodeShrLine(content, y);
			}
			return true;
		}

		bool DecodeAppleIIShr(byte[] content, int contentLength)
		{
			if (contentLength == 32768)
				return DecodeAppleIIShrUnpacked(content);
			byte[] unpacked = new byte[32768];
			PackBytesStream stream = new PackBytesStream { Content = content, ContentOffset = 0, ContentLength = contentLength };
			for (int unpackedOffset = 0; unpackedOffset < 32768; unpackedOffset++) {
				int b = stream.ReadUnpacked();
				if (b < 0)
					return false;
				unpacked[unpackedOffset] = (byte) b;
			}
			return stream.ReadUnpacked() < 0 && DecodeAppleIIShrUnpacked(unpacked);
		}

		bool DecodeSh3(byte[] content, int contentLength)
		{
			if (contentLength != 38400)
				return false;
			SetSize(320, 200, RECOILResolution.AppleIIGS1x1);
			for (int y = 0; y < 200; y++) {
				SetAppleIIGSPalette(content, 32000 + (y << 5), 15);
				DecodeShrLine(content, y);
			}
			return true;
		}

		void DrawSprByte(int x1, int y, int b)
		{
			for (int x = 0; x < 8; x++) {
				if ((b >> (7 - x) & 1) != 0)
					this.Pixels[y * 320 + x1 + x] = 16777215;
			}
		}

		bool DecodeAppleSpr(byte[] content, int contentLength)
		{
			SetSize(320, 200, RECOILResolution.AppleII1x1);
			Array.Clear(this.Pixels, 0, 64000);
			AppleSprStream s = new AppleSprStream { Content = content, ContentOffset = 0, ContentLength = contentLength };
			for (;;) {
				int cols = s.ReadSprInt();
				if (cols < 0)
					return false;
				int rows = s.ReadSprInt();
				if (rows < 0)
					return false;
				int order = s.ReadSprInt();
				if (order < 0)
					return false;
				int x = s.ReadSprInt();
				if (x < 0)
					return false;
				int y = s.ReadSprInt();
				if (y < 0)
					return false;
				if (rows == 0)
					break;
				if (cols == 0 || x + (cols << 3) > 320 || y + rows > 200)
					return false;
				if (order == 2) {
					for (int col = 0; col < cols; col++) {
						for (int row = 0; row < rows; row++) {
							int b = s.ReadSprInt();
							if (b < 0)
								return false;
							DrawSprByte(x + (col << 3), y + row, b);
						}
					}
				}
				else {
					for (int row = 0; row < rows; row++) {
						for (int col = 0; col < cols; col++) {
							int b = s.ReadSprInt();
							if (b < 0)
								return false;
							DrawSprByte(x + (col << 3), y + row, b);
						}
					}
				}
			}
			return true;
		}

		bool DecodePackBytes(PackBytesStream stream, int pixelsOffset, int unpackedBytes)
		{
			for (int x = 0; x < unpackedBytes; x++) {
				int b = stream.ReadUnpacked();
				if (b < 0)
					return false;
				if (this.Resolution == RECOILResolution.AppleIIGS1x2) {
					int offset = (pixelsOffset << 1) + (x << 2);
					this.Pixels[offset + this.Width] = this.Pixels[offset] = this.ContentPalette[8 + (b >> 6)];
					this.Pixels[offset + this.Width + 1] = this.Pixels[offset + 1] = this.ContentPalette[12 + (b >> 4 & 3)];
					this.Pixels[offset + this.Width + 2] = this.Pixels[offset + 2] = this.ContentPalette[b >> 2 & 3];
					this.Pixels[offset + this.Width + 3] = this.Pixels[offset + 3] = this.ContentPalette[4 + (b & 3)];
				}
				else {
					this.Pixels[pixelsOffset + (x << 1)] = this.ContentPalette[b >> 4];
					this.Pixels[pixelsOffset + (x << 1) + 1] = this.ContentPalette[b & 15];
				}
			}
			return true;
		}

		bool DecodePaintworks(byte[] content, int contentLength)
		{
			if (contentLength < 1041)
				return false;
			SetSize(320, 396, RECOILResolution.AppleIIGS1x1);
			SetAppleIIGSPalette(content, 0, 0);
			PackBytesStream stream = new PackBytesStream { Content = content, ContentOffset = 546, ContentLength = contentLength };
			return DecodePackBytes(stream, 0, 63360);
		}

		bool Decode3201(byte[] content, int contentLength)
		{
			if (contentLength < 6654 || content[0] != 193 || content[1] != 208 || content[2] != 208 || content[3] != 0)
				return false;
			SetSize(320, 200, RECOILResolution.AppleIIGS1x1);
			PackBytesStream stream = new PackBytesStream { Content = content, ContentOffset = 6404, ContentLength = contentLength };
			for (int y = 0; y < 200; y++) {
				SetAppleIIGSPalette(content, 4 + (y << 5), 15);
				if (!DecodePackBytes(stream, y * 320, 160))
					return false;
			}
			return true;
		}

		bool DecodeApfShr(byte[] content, int contentLength)
		{
			if (contentLength < 1249 || content[4] != 4 || !IsStringAt(content, 5, "MAIN") || content[14] != 0)
				return false;
			int paletteCount = content[13];
			if (paletteCount > 16)
				return false;
			int dirOffset = 17 + (paletteCount << 5);
			if (dirOffset >= contentLength)
				return false;
			int mode = content[9] & 240;
			int width = content[11] | content[12] << 8;
			int height = content[dirOffset - 2] | content[dirOffset - 1] << 8;
			int bytesPerLine;
			switch (mode) {
			case 0:
				if ((width & 1) != 0 || !SetSize(width, height, RECOILResolution.AppleIIGS1x1))
					return false;
				bytesPerLine = width >> 1;
				break;
			case 128:
				if ((width & 3) != 0 || !SetSize(width, height << 1, RECOILResolution.AppleIIGS1x2))
					return false;
				bytesPerLine = width >> 2;
				break;
			default:
				return false;
			}
			int multipalOffset = -1;
			int contentOffset = 0;
			if (height == 200) {
				for (int chunkLength = Get32LittleEndian(content, 0);;) {
					if (chunkLength <= 0)
						return false;
					contentOffset += chunkLength;
					if (contentOffset < 0 || contentOffset > contentLength - 6415)
						break;
					chunkLength = Get32LittleEndian(content, contentOffset);
					if (chunkLength == 6415 && content[contentOffset + 4] == 8 && IsStringAt(content, contentOffset + 5, "MULTIPAL") && content[contentOffset + 13] == 200 && content[contentOffset + 14] == 0) {
						multipalOffset = contentOffset + 15;
						break;
					}
				}
			}
			contentOffset = dirOffset + (height << 2);
			if (contentOffset >= contentLength)
				return false;
			PackBytesStream stream = new PackBytesStream { Content = content, ContentOffset = contentOffset, ContentLength = contentLength };
			for (int y = 0; y < height; y++) {
				if (multipalOffset >= 0)
					SetAppleIIGSPalette(content, multipalOffset + (y << 5), 0);
				else {
					int lineMode = content[dirOffset + (y << 2) + 2];
					int palette = lineMode & 15;
					if ((lineMode & 240) != mode || palette >= paletteCount || content[dirOffset + (y << 2) + 3] != 0)
						return false;
					SetAppleIIGSPalette(content, 15 + (palette << 5), 0);
				}
				int nextLineOffset = stream.ContentOffset + content[dirOffset + (y << 2)] + (content[dirOffset + (y << 2) + 1] << 8);
				if (!DecodePackBytes(stream, y * width, bytesPerLine))
					return false;
				stream.ContentOffset = nextLineOffset;
			}
			return true;
		}

		static int GetSamCoupeColor(int c)
		{
			int rgb = 0;
			if ((c & 1) != 0)
				rgb |= 73;
			if ((c & 2) != 0)
				rgb |= 4784128;
			if ((c & 4) != 0)
				rgb |= 18688;
			if ((c & 8) != 0)
				rgb |= 2368548;
			if ((c & 16) != 0)
				rgb |= 146;
			if ((c & 32) != 0)
				rgb |= 9568256;
			if ((c & 64) != 0)
				rgb |= 37376;
			return rgb;
		}

		void SetSamCoupePalette(byte[] content, int contentOffset, int colors)
		{
			for (int i = 0; i < colors; i++)
				this.ContentPalette[i] = GetSamCoupeColor(content[contentOffset + i]);
		}

		static int GetSamCoupeMode12Color(byte[] content, int bitmapOffset, int attributeOffset, int x)
		{
			int a = content[attributeOffset + (x >> 3)];
			return (a >> 3 & 8) | (((content[bitmapOffset + (x >> 3)] >> (~x & 7) & 1) == 0 ? a >> 3 : a) & 7);
		}

		int DecodeSamCoupeScreen(byte[] content, int contentOffset, int contentLength, int mode, int interruptOffset)
		{
			if (interruptOffset >= contentLength)
				return -1;
			SetSamCoupePalette(content, interruptOffset - 40, 16);
			int width = GetOriginalWidth();
			for (int y = 0; y < 192; y++) {
				while (interruptOffset + 3 < contentLength && y == content[interruptOffset] + 1) {
					int c = content[interruptOffset + 1];
					if (c > 15)
						return -1;
					this.ContentPalette[c] = GetSamCoupeColor(content[interruptOffset + 2]);
					interruptOffset += 4;
				}
				int row = y << (this.Frames - 1);
				if (contentOffset != 0)
					row++;
				for (int x = 0; x < width; x++) {
					int c;
					switch (mode) {
					case 1:
						c = GetSamCoupeMode12Color(content, GetZxLineOffset(y), 6144 + (y >> 3 << 5), x);
						break;
					case 2:
						c = GetSamCoupeMode12Color(content, y << 5, 8192 + (y << 5), x);
						break;
					case 3:
						c = content[y << 7 | x >> 2] >> ((~x & 3) << 1);
						c = (c & 1) << 1 | (c >> 1 & 1);
						break;
					case 4:
						c = GetNibble(content, contentOffset + (y << 7), x);
						break;
					default:
						throw new NotImplementedException();
					}
					SetScaledPixel(x, row, this.ContentPalette[c]);
				}
			}
			if (interruptOffset >= contentLength || content[interruptOffset] != 255)
				return -1;
			return interruptOffset + 1;
		}

		bool DecodeSs1(byte[] content, int contentLength)
		{
			SetSize(256, 192, RECOILResolution.SamCoupe1x1);
			return DecodeSamCoupeScreen(content, 0, contentLength, 1, 6952) == contentLength;
		}

		bool DecodeSs2(byte[] content, int contentLength)
		{
			SetSize(256, 192, RECOILResolution.SamCoupe1x1);
			return DecodeSamCoupeScreen(content, 0, contentLength, 2, 14376) == contentLength;
		}

		bool DecodeSs3(byte[] content, int contentLength)
		{
			SetSize(512, 384, RECOILResolution.SamCoupe1x2);
			return DecodeSamCoupeScreen(content, 0, contentLength, 3, 24616) == contentLength;
		}

		bool DecodeSs4(byte[] content, int contentLength)
		{
			SetSize(256, 192, RECOILResolution.SamCoupe1x1);
			return DecodeSamCoupeScreen(content, 0, contentLength, 4, 24616) == contentLength;
		}

		bool DecodeLce(byte[] content, int contentLength)
		{
			SetSize(512, 384, RECOILResolution.SamCoupe2x1i);
			this.Frames = 2;
			int contentOffset = DecodeSamCoupeScreen(content, 0, contentLength, 4, 24616);
			if (contentOffset < 0)
				return false;
			return DecodeSamCoupeScreen(content, contentOffset, contentLength, 4, contentOffset + 24616) == contentLength;
		}

		void SetSamCoupeAttrPalette(byte[] content, int contentOffset)
		{
			for (int i = 0; i < 64; i++)
				this.ContentPalette[i] = GetSamCoupeColor(content[contentOffset + (i >> 1 & 8) + (i & 7)]);
		}

		bool DecodeSsx(byte[] content, int contentLength)
		{
			switch (contentLength) {
			case 6928:
				SetSamCoupeAttrPalette(content, 6912);
				SetSize(256, 192, RECOILResolution.SamCoupe1x1);
				DecodeZx(content, 0, 6144, 3, 0);
				return true;
			case 12304:
				SetSamCoupeAttrPalette(content, 12288);
				SetSize(256, 192, RECOILResolution.SamCoupe1x1);
				DecodeZx(content, -1, 6144, 0, 0);
				return true;
			case 24580:
				SetSamCoupePalette(content, 24576, 4);
				SetSize(512, 384, RECOILResolution.SamCoupe1x2);
				for (int y = 0; y < 192; y++) {
					for (int x = 0; x < 512; x++) {
						int c = content[y << 7 | x >> 2] >> ((~x & 3) << 1) & 3;
						this.Pixels[(y << 10) + x + 512] = this.Pixels[(y << 10) + x] = this.ContentPalette[c];
					}
				}
				return true;
			case 24592:
				SetSamCoupePalette(content, 24576, 16);
				SetSize(256, 192, RECOILResolution.SamCoupe1x1);
				DecodeNibbles(content, 0, 128);
				return true;
			case 98304:
				for (int c = 0; c < 128; c++)
					this.ContentPalette[c] = GetSamCoupeColor(c);
				SetSize(512, 384, RECOILResolution.SamCoupe1x2);
				for (int y = 0; y < 192; y++) {
					for (int x = 0; x < 512; x++) {
						int c = content[(y << 9) + x];
						if (c >= 128)
							return false;
						this.Pixels[(y << 10) + x + 512] = this.Pixels[(y << 10) + x] = this.ContentPalette[c];
					}
				}
				return true;
			default:
				return false;
			}
		}

		static int GetX68KColor(int color)
		{
			int rgb = (color & 1984) << 13 | (color & 63488) | (color & 62) << 2;
			if ((color & 1) != 0)
				rgb |= 263172;
			return rgb | (rgb >> 6 & 197379);
		}

		int RestrictPlatformColor(int rgb, int colors)
		{
			switch (this.Resolution) {
			case RECOILResolution.FmTowns1x1:
				return (rgb & 16316664) | (rgb >> 5 & 460551);
			case RECOILResolution.Msx21x1:
			case RECOILResolution.Msx21x2:
			case RECOILResolution.Msx21x1i:
			case RECOILResolution.Msx22x1i:
			case RECOILResolution.Msx2Plus1x1:
			case RECOILResolution.Msx2Plus2x1i:
				rgb &= 14737632;
				return rgb | rgb >> 3 | (rgb >> 6 & 197379);
			case RECOILResolution.Pc881x2:
				rgb &= 15790320;
				return rgb | rgb >> 4;
			case RECOILResolution.Pc88Va1x1:
				return (rgb & 16317688) | (rgb >> 5 & 458759) | (rgb >> 6 & 768);
			case RECOILResolution.Pc981x1:
				if (colors == 16) {
					rgb &= 15790320;
					rgb |= rgb >> 4;
				}
				return rgb;
			case RECOILResolution.X68K1x1:
				return (rgb & 16316664) | (rgb >> 10 & 1) * 263172 | (rgb >> 6 & 197379);
			default:
				return rgb;
			}
		}

		bool DecodeX68KPicChain(BitStream stream, int pixelsOffset, int color)
		{
			for (;;) {
				switch (stream.ReadBits(2)) {
				case 0:
					switch (stream.ReadBit()) {
					case 0:
						return true;
					case 1:
						break;
					default:
						return false;
					}
					switch (stream.ReadBit()) {
					case 0:
						pixelsOffset -= 2;
						break;
					case 1:
						pixelsOffset += 2;
						break;
					default:
						return false;
					}
					break;
				case 1:
					pixelsOffset--;
					break;
				case 2:
					break;
				case 3:
					pixelsOffset++;
					break;
				default:
					return false;
				}
				pixelsOffset += this.Width;
				if (pixelsOffset < 0 || pixelsOffset >= this.Width * this.Height)
					return false;
				this.Pixels[pixelsOffset] = color;
			}
		}

		bool DecodeX68KPicScreen(X68KPicStream stream, int pixelsLength, int platform, int depth)
		{
			for (int pixelsOffset = 0; pixelsOffset < pixelsLength; pixelsOffset++)
				this.Pixels[pixelsOffset] = -1;
			RecentInts colors = new RecentInts();
			int color = 0;
			for (int pixelsOffset = -1;;) {
				int length = stream.ReadLength();
				if (length < 0)
					return false;
				while (--length > 0) {
					int got = this.Pixels[++pixelsOffset];
					if (got < 0)
						this.Pixels[pixelsOffset] = color;
					else
						color = got;
					if (pixelsOffset >= pixelsLength - 1)
						return true;
				}
				if (depth <= 8) {
					color = stream.ReadBits(depth);
					if (color < 0)
						return false;
					color = this.ContentPalette[color];
				}
				else {
					switch (stream.ReadBit()) {
					case 0:
						color = stream.ReadBits(depth);
						if (color < 0)
							return false;
						switch (platform) {
						case 0:
							if (depth == 15)
								color <<= 1;
							color = GetX68KColor(color);
							break;
						case 17:
							color = GetG6R5B5Color(color);
							break;
						default:
							break;
						}
						colors.Add(color);
						break;
					case 1:
						color = stream.ReadBits(7);
						if (color < 0)
							return false;
						color = colors.Get(color);
						break;
					default:
						return false;
					}
				}
				this.Pixels[++pixelsOffset] = color;
				if (pixelsOffset >= pixelsLength - 1)
					return true;
				switch (stream.ReadBit()) {
				case 0:
					break;
				case 1:
					if (!DecodeX68KPicChain(stream, pixelsOffset, color))
						return false;
					break;
				default:
					return false;
				}
			}
		}

		bool DecodeX68KPic(byte[] content, int contentLength)
		{
			if (contentLength < 14 || content[0] != 'P' || content[1] != 'I' || content[2] != 'C')
				return false;
			RECOILResolution resolution = IsStringAt(content, 3, "/MM/") ? RECOILResolution.Msx21x1 : RECOILResolution.X68K1x1;
			X68KPicStream stream = new X68KPicStream { Content = content, ContentOffset = 3, ContentLength = contentLength };
			for (;;) {
				int b = stream.ReadByte();
				if (b < 0)
					return false;
				if (b == 26)
					break;
				if (b == '/' && resolution == RECOILResolution.Msx21x1 && stream.ContentOffset + 4 < contentLength && content[stream.ContentOffset] == 'M' && content[stream.ContentOffset + 1] == 'S') {
					b = content[stream.ContentOffset + 2];
					if (b >= 'A' && b <= 'C')
						resolution = RECOILResolution.Msx2Plus1x1;
				}
			}
			if (!stream.SkipUntilByte(0))
				return false;
			int platform = stream.ReadBits(16);
			int depth = stream.ReadBits(16);
			int width = stream.ReadBits(16);
			int height = stream.ReadBits(16);
			int pixelsLength = width * height;
			switch (platform) {
			case 0:
				if (!SetSize(width, height, resolution))
					return false;
				break;
			case 2:
				if (!SetSize(width, height, RECOILResolution.FmTowns1x1))
					return false;
				stream.ContentOffset += 6;
				break;
			case 17:
				return depth == 16 && SetSize(width, height, RECOILResolution.Pc88Va1x1) && DecodeX68KPicScreen(stream, pixelsLength, 17, 16);
			case 31:
				if (!SetSize(width, height, RECOILResolution.X68K1x1))
					return false;
				stream.ContentOffset += 6;
				break;
			case 33:
				if (depth != 16 || !SetSize(width, height << 1, RECOILResolution.Pc88Va1x1) || !DecodeX68KPicScreen(stream, pixelsLength, 33, 16))
					return false;
				for (int offset = pixelsLength - 1; offset >= 0; offset--) {
					int color = this.Pixels[offset];
					this.Pixels[(offset << 1) + 1] = GetG3R3B2Color(color >> 8);
					this.Pixels[offset << 1] = GetG3R3B2Color(color & 255);
				}
				return true;
			case 194:
				if (!SetSize(width, height, RECOILResolution.FmTowns1x1))
					return false;
				break;
			default:
				return false;
			}
			switch (depth) {
			case 4:
			case 8:
				for (int c = 0; c < 1 << depth; c++) {
					int color = stream.ReadBits(16);
					if (color < 0)
						return false;
					this.ContentPalette[c] = RestrictPlatformColor(GetX68KColor(color), 1 << depth);
				}
				break;
			case 15:
			case 16:
				break;
			default:
				return false;
			}
			return DecodeX68KPicScreen(stream, pixelsLength, 0, depth);
		}

		void SetPc88EightPixels(int column, int y, int b)
		{
			for (int x = 0; x < 8; x++) {
				int offset = y * 1280 + column + x;
				this.Pixels[offset + 640] = this.Pixels[offset] = (b >> (7 - x) & 65793) * 255;
			}
		}

		bool DecodeDaVinci(byte[] content, int contentLength)
		{
			if ((contentLength & 255) != 0)
				return false;
			SetSize(640, 400, RECOILResolution.Pc881x2);
			DaVinciStream rle = new DaVinciStream { Content = content, ContentOffset = 0, ContentLength = contentLength };
			for (int y = 0; y < 200; y++) {
				for (int column = 0; column < 640; column += 8) {
					int b = rle.ReadRle();
					if (b < 0)
						return false;
					SetPc88EightPixels(column, y, b);
				}
			}
			return rle.RepeatCount == 0 && contentLength - rle.ContentOffset < 256;
		}

		bool DecodeArtMaster88(byte[] content, int contentLength)
		{
			if (contentLength < 42 || !IsStringAt(content, 0, "SS_SIF    0.0") || content[19] != 'B' || content[20] != 'R' || content[21] != 'G' || content[24] != 128 || content[25] != 2)
				return false;
			ArtMaster88Stream rle = new ArtMaster88Stream { Content = content, ContentOffset = 40, ContentLength = contentLength };
			if (content[16] == 'I' && !rle.SkipChunk())
				return false;
			switch (content[26] | content[27] << 8) {
			case 200:
				SetSize(640, 400, RECOILResolution.Pc881x2);
				if (content[18] == 'B' && !rle.SkipChunk())
					return false;
				if (!rle.ReadPlanes(3, 16000))
					return false;
				for (int y = 0; y < 200; y++) {
					for (int column = 0; column < 80; column++) {
						int offset = y * 80 + column;
						SetPc88EightPixels(column << 3, y, rle.Planes[1][offset] << 16 | rle.Planes[2][offset] << 8 | rle.Planes[0][offset]);
					}
				}
				break;
			case 400:
				SetSize(640, 400, RECOILResolution.Pc981x1);
				if (content[17] != 'R' || rle.ContentOffset + 50 >= contentLength || content[rle.ContentOffset + 1] != 0)
					return false;
				int paletteLength = content[rle.ContentOffset];
				int planes;
				switch (paletteLength) {
				case 50:
					planes = 3;
					break;
				case 98:
					planes = 4;
					break;
				default:
					return false;
				}
				if (rle.ContentOffset + paletteLength >= contentLength)
					return false;
				for (int c = 0; c < 1 << planes; c++) {
					int offset = rle.ContentOffset + 2 + c * 6;
					int rgb = content[offset] << 16 | content[offset + 2] << 8 | content[offset + 4];
					if ((rgb & 15790320) != 0 || content[offset + 1] != 0 || content[offset + 3] != 0 || content[offset + 5] != 0)
						return false;
					this.ContentPalette[c] = rgb * 17;
				}
				rle.ContentOffset += paletteLength;
				if (content[18] == 'B' && !rle.SkipChunk())
					return false;
				if (!rle.ReadPlanes(planes, 32000))
					return false;
				for (int y = 0; y < 400; y++) {
					for (int column = 0; column < 80; column++) {
						int offset = y * 80 + column;
						for (int x = 0; x < 8; x++) {
							int c = 0;
							for (int plane = 0; plane < planes; plane++)
								c |= (rle.Planes[plane][offset] >> (7 - x) & 1) << plane;
							this.Pixels[y * 640 + (column << 3) + x] = this.ContentPalette[c];
						}
					}
				}
				break;
			default:
				return false;
			}
			return true;
		}

		static int GetKtyTile(byte[] content, int contentOffset) { return content[contentOffset + 1] << 16 | content[contentOffset + 2] << 8 | content[contentOffset]; }

		void SetKtyFourPixels(int pixelsOffset, int tile)
		{
			for (int x = 0; x < 4; x++)
				this.Pixels[pixelsOffset + x] = (tile >> (3 - x) & 65793) * 255;
		}

		void SetKtyTileOffset(int pixelsOffset, int mode, byte[] content, int tileOffset)
		{
			int tile = GetKtyTile(content, tileOffset);
			SetKtyFourPixels(pixelsOffset, tile >> 4);
			SetKtyFourPixels(pixelsOffset + 640, tile);
			if (mode != 0) {
				if (mode >= 2)
					tile = GetKtyTile(content, tileOffset + 3);
				SetKtyFourPixels(pixelsOffset + 1280, tile >> 4);
				SetKtyFourPixels(pixelsOffset + 1920, tile);
			}
		}

		void SetKtyTile(int x, int y, int mode, byte[] content, int tileOffset)
		{
			if (mode != 0)
				y <<= 1;
			SetKtyTileOffset((y * 320 + x) << 2, mode, content, tileOffset);
		}

		bool DecodeKty(byte[] content, int contentLength)
		{
			SetSize(640, 400, RECOILResolution.Pc88Va1x1);
			for (int i = 0; i < 256000; i += 4)
				this.Pixels[i] = 1;
			int mode = 0;
			for (int contentOffset = 0; contentOffset < contentLength;) {
				int b = content[contentOffset++];
				if (b == 255) {
					if (mode != 0)
						mode = 2;
					for (int y = 0; y < 100; y++) {
						for (int x = 0; x < 160; x++) {
							int pixelsOffset = (y * (mode == 0 ? 320 : 640) + x) << 2;
							if (this.Pixels[pixelsOffset] == 1) {
								int nextOffset = contentOffset + (mode == 0 ? 3 : 6);
								if (nextOffset > contentLength)
									return false;
								SetKtyTileOffset(pixelsOffset, mode, content, contentOffset);
								contentOffset = nextOffset;
							}
						}
					}
					if (contentOffset != contentLength)
						return false;
					if (mode == 0) {
						for (int pixelsOffset = 127360; pixelsOffset >= 0; pixelsOffset -= 640) {
							Array.Copy(this.Pixels, pixelsOffset, this.Pixels, (pixelsOffset << 1) + 640, 640);
							Array.Copy(this.Pixels, pixelsOffset, this.Pixels, pixelsOffset << 1, 640);
						}
						this.Resolution = RECOILResolution.Pc881x2;
					}
					return true;
				}
				mode = b;
				int tileOffset = contentOffset;
				contentOffset += mode < 2 ? 3 : 6;
				for (;;) {
					if (contentOffset >= contentLength)
						return false;
					int hi = content[contentOffset++];
					if (hi == 255)
						break;
					if (contentOffset + 2 > contentLength)
						return false;
					int offset = (hi & 63) << 8 | content[contentOffset++];
					int left = offset % 160;
					int top = offset / 160;
					if (top >= 100)
						return false;
					int right;
					int bottom;
					if (hi >= 128) {
						right = left;
						bottom = content[contentOffset++];
					}
					else {
						right = content[contentOffset++];
						if (right < left || right >= 160)
							return false;
						if (hi >= 64)
							bottom = top;
						else if (contentOffset >= contentLength)
							return false;
						else {
							bottom = content[contentOffset++];
							if (bottom < top || bottom >= 100)
								return false;
						}
					}
					for (int y = top; y <= bottom; y++) {
						for (int x = left; x <= right; x++)
							SetKtyTile(x, y, mode, content, tileOffset);
					}
				}
				for (;;) {
					if (contentOffset >= contentLength)
						return false;
					int x = content[contentOffset++];
					if (x == 255)
						break;
					if (x >= 160 || contentOffset >= contentLength)
						return false;
					int y = content[contentOffset++];
					if (y >= 100)
						return false;
					SetKtyTile(x, y, mode, content, tileOffset);
				}
			}
			return false;
		}

		bool DecodeEbd(byte[] content, int contentLength)
		{
			if (contentLength < 368 || contentLength % 320 != 48)
				return false;
			for (int c = 0; c < 16; c++) {
				int rgb = GetR8G8B8Color(content, c * 3);
				if (((rgb >> 4 ^ rgb) & 986895) != 0) {
					if ((rgb & 15790320) != 0)
						return false;
					rgb *= 17;
				}
				this.ContentPalette[c] = rgb;
			}
			return DecodeAmigaPlanar(content, 48, 640, contentLength / 320, RECOILResolution.Pc981x1, 4, this.ContentPalette);
		}

		bool DecodeNl3(byte[] content, int contentLength)
		{
			Nl3Stream stream = new Nl3Stream { Content = content, ContentOffset = 0, ContentLength = contentLength };
			for (int i = 0; i < 64; i++) {
				int c = stream.ReadValue();
				if (c < 0 || c > 127)
					return false;
				c |= stream.ReadValue() << 7;
				if (c < 0 || c >= 729)
					return false;
				this.ContentPalette[i] = Get729Color(c);
			}
			SetSize(160, 100, RECOILResolution.Pc981x1);
			for (int x = 0; x < 160; x++) {
				for (int y = 0; y < 100; y++) {
					int b = stream.ReadRle();
					if (b < 0)
						return false;
					this.Pixels[y * 160 + x] = this.ContentPalette[b];
				}
			}
			return true;
		}

		bool DecodeMl1Chain(X68KPicStream stream, int pixelsOffset, int rgb)
		{
			for (;;) {
				switch (stream.ReadBit()) {
				case 0:
					break;
				case 1:
					switch (stream.ReadBits(2)) {
					case 0:
						pixelsOffset++;
						break;
					case 1:
						pixelsOffset--;
						break;
					case 2:
						return true;
					case 3:
						switch (stream.ReadBit()) {
						case 0:
							pixelsOffset += 2;
							break;
						case 1:
							pixelsOffset -= 2;
							break;
						default:
							return false;
						}
						break;
					default:
						return false;
					}
					break;
				default:
					return false;
				}
				pixelsOffset += this.Width;
				if (pixelsOffset < 0 || pixelsOffset >= this.Width * this.Height)
					return false;
				this.Pixels[pixelsOffset] = rgb;
			}
		}

		const int Ml1SingleImage = -1;

		int DecodeMl1Mx1(X68KPicStream stream, int imageOffset)
		{
			if (stream.ReadBits(32) != 825241626 || stream.ReadBits(32) < 0 || stream.ReadBits(16) < 0)
				return -1;
			int left = stream.ReadBits(16);
			int top = stream.ReadBits(16);
			int width = stream.ReadBits(16) - left + 1;
			int height = stream.ReadBits(16) - top + 1;
			for (int i = 0; i < 624; i++) {
				if (stream.ReadBit() < 0)
					return -1;
			}
			int mode = stream.ReadBits(2);
			int lastColor;
			switch (mode) {
			case 0:
				lastColor = 127;
				break;
			case 1:
			case 2:
				lastColor = stream.ReadBits(7);
				break;
			default:
				return -1;
			}
			if (imageOffset == -1) {
				if (!SetSize(width, height, RECOILResolution.Pc981x1))
					return -1;
				imageOffset = 0;
			}
			Array.Clear(this.ContentPalette, 0, 256);
			for (int i = 0; i <= lastColor; i++) {
				int j = 0;
				if (mode > 0)
					j = stream.ReadBits(7);
				int c = stream.ReadBits(10);
				if (c < 0 || c >= 729)
					return -1;
				this.ContentPalette[mode == 1 ? j : i] = Get729Color(c);
			}
			for (int y = 0; y < height; y++) {
				for (int x = 0; x < width; x++)
					this.Pixels[imageOffset + y * this.Width + x] = 1;
			}
			int distance = 1;
			int rgb = 0;
			for (int y = 0; y < height; y++) {
				for (int x = 0; x < width; x++) {
					int pixelsOffset = imageOffset + y * this.Width + x;
					if (--distance > 0) {
						int old = this.Pixels[pixelsOffset];
						if (old == 1)
							this.Pixels[pixelsOffset] = rgb;
						else
							rgb = old;
					}
					else {
						distance = stream.ReadLength();
						if (distance < 0)
							return -1;
						int c = mode == 2 ? stream.ReadLength() - 1 : stream.ReadBits(7);
						if (c < 0 || c >= 128)
							return -1;
						rgb = this.ContentPalette[c];
						switch (stream.ReadBit()) {
						case 0:
							break;
						case 1:
							if (!DecodeMl1Chain(stream, pixelsOffset, rgb))
								return -1;
							break;
						default:
							return -1;
						}
						this.Pixels[pixelsOffset] = rgb;
					}
				}
			}
			return distance == 1 && stream.ReadLength() == width * height + 1 ? height : -1;
		}

		bool DecodeMl1(byte[] content, int contentLength)
		{
			X68KPicStream stream = new X68KPicStream { Content = content, ContentOffset = 0, ContentLength = contentLength };
			return DecodeMl1Mx1(stream, -1) > 0;
		}

		bool DecodeMx1Tiles(Mx1Stream stream, int width, int height, int shift)
		{
			if (!SetSize(width << shift, height << shift, RECOILResolution.Pc981x1))
				return false;
			for (int y = 0; y < this.Height; y += height) {
				for (int x = 0; x < this.Width; x += width) {
					if (!stream.FindImage() || DecodeMl1Mx1(stream, y * this.Width + x) < 0)
						return false;
				}
			}
			return true;
		}

		bool DecodeMx1(byte[] content, int contentLength)
		{
			Mx1Stream stream = new Mx1Stream { Content = content, ContentOffset = 0, ContentLength = contentLength };
			if (!stream.FindImage() || DecodeMl1Mx1(stream, -1) < 0)
				return false;
			if (!stream.FindImage())
				return true;
			int sameSizeImages = 1;
			int width = this.Width;
			int height = this.Height;
			do {
				if (DecodeMl1Mx1(stream, -1) < 0)
					return false;
				if (sameSizeImages > 0 && this.Width == width && this.Height == height)
					sameSizeImages++;
				else {
					if (width < this.Width)
						width = this.Width;
					if (sameSizeImages > 0) {
						height *= sameSizeImages;
						sameSizeImages = 0;
					}
					height += this.Height;
				}
			}
			while (stream.FindImage());
			stream.ContentOffset = 0;
			switch (sameSizeImages) {
			case 4:
				return DecodeMx1Tiles(stream, width, height, 1);
			case 16:
				return DecodeMx1Tiles(stream, width, height, 2);
			case 0:
				break;
			default:
				height *= sameSizeImages;
				break;
			}
			if (!SetSize(width, height, RECOILResolution.Pc981x1))
				return false;
			Array.Clear(this.Pixels, 0, width * height);
			int imageOffset = 0;
			while (stream.FindImage())
				imageOffset += DecodeMl1Mx1(stream, imageOffset) * width;
			return true;
		}

		bool DecodeZim(byte[] content, int contentLength)
		{
			if (contentLength < 700 || !IsStringAt(content, 0, "FORMAT-A"))
				return false;
			int contentOffset = 512 + ((content[506] | content[507] << 8) << 1);
			if (contentOffset + 26 > contentLength || content[contentOffset] != 0 || content[contentOffset + 1] != 0 || content[contentOffset + 2] != 0 || content[contentOffset + 3] != 0 || content[contentOffset + 20] != 1 || content[contentOffset + 21] != 0)
				return false;
			int width = content[contentOffset + 4] + (content[contentOffset + 5] << 8) + 1;
			int height = content[contentOffset + 6] + (content[contentOffset + 7] << 8) + 1;
			if (!SetSize(width, height, RECOILResolution.Pc981x1))
				return false;
			contentOffset += 24;
			if (content[contentOffset - 2] != 0 || content[contentOffset - 1] != 0) {
				if (contentOffset + 66 > contentLength)
					return false;
				for (int c = 0; c < 16; c++) {
					this.ContentPalette[c] = GetKtyTile(content, contentOffset);
					contentOffset += 4;
				}
			}
			else {
				for (int c = 0; c < 16; c++)
					this.ContentPalette[c] = GetZxPaletteColor(c);
				this.ContentPalette[8] = 16777215;
			}
			int pixelsLength = width * height;
			for (int pixelsOffset = 0; pixelsOffset < pixelsLength; pixelsOffset++)
				this.Pixels[pixelsOffset] = this.ContentPalette[0];
			byte[] flags3 = new byte[64];
			byte[] data = new byte[512];
			ZimStream stream = new ZimStream { Content = content, ContentOffset = contentOffset, ContentLength = contentLength };
			int skip = stream.ReadWord();
			stream.ContentOffset += skip << 1;
			for (;;) {
				int dot = stream.ReadWord();
				switch (dot) {
				case -1:
					return false;
				case 0:
					return true;
				default:
					break;
				}
				int x = stream.ReadWord();
				if (x < 0 || x >= width)
					return false;
				int y = stream.ReadWord();
				if (y < 0 || y >= height)
					return false;
				int len = stream.ReadWord();
				if (len < 0)
					return false;
				stream.ContentLength = stream.ContentOffset + len;
				if (stream.ContentLength >= contentLength)
					return false;
				int size = stream.ReadWord();
				if (size > 512 || (size & 3) != 0 || size << 1 < dot)
					return false;
				int pixelsOffset = y * width + x;
				if (pixelsOffset + dot > pixelsLength)
					return false;
				stream.UnpackFlags2();
				stream.Unpack(stream.Flags2, flags3, 64);
				stream.Unpack(flags3, data, size);
				stream.ContentLength = contentLength;
				for (int i = 1; i < size; i++)
					data[i] ^= data[i - 1];
				for (int i = 2; i < size; i++)
					data[i] ^= data[i - 2];
				size >>= 2;
				for (int i = 0; i < dot; i++) {
					int bit = ~i & 7;
					int c = (data[i >> 3] >> bit & 1) << 3 | (data[size + (i >> 3)] >> bit & 1) << 2 | (data[2 * size + (i >> 3)] >> bit & 1) << 1 | (data[3 * size + (i >> 3)] >> bit & 1);
					this.Pixels[pixelsOffset + i] = this.ContentPalette[c];
				}
			}
		}

		bool DecodeQ4(byte[] content, int contentLength)
		{
			if (contentLength < 22 || (content[2] != 2 && (content[1] > 1 || content[3] > 1)) || content[8] + (content[9] << 8) != contentLength || !IsStringAt(content, 11, "MAJYO"))
				return false;
			Q4Stream rle = new Q4Stream { Content = content, ContentOffset = 16, ContentLength = contentLength };
			int nextChunkOffset = rle.StartChunk();
			if (nextChunkOffset < 0 || !rle.UnpackQ4())
				return false;
			for (int i = 0; i < 16; i++) {
				int rgb = 0;
				for (int c = 0; c < 3; c++) {
					if (rle.ReadRle() < 0)
						return false;
					int b = rle.ReadRle();
					if (b < 0)
						return false;
					rgb = rgb << 8 | b * 17;
				}
				this.ContentPalette[(i & 8) | (i & 1) << 2 | (i >> 1 & 3)] = rgb;
			}
			SetSize(640, 400, RECOILResolution.Pc981x1);
			int chunkPixels = 0;
			for (int i = 0; i < 256000; i++) {
				if (--chunkPixels <= 0) {
					if (nextChunkOffset >= contentLength - 6)
						return false;
					chunkPixels = (content[nextChunkOffset + 4] | content[nextChunkOffset + 5] << 8) << 1;
					rle.Content = content;
					rle.ContentOffset = nextChunkOffset;
					rle.ContentLength = contentLength;
					nextChunkOffset = rle.StartChunk();
					if (nextChunkOffset < 0 || !rle.UnpackQ4())
						return false;
				}
				this.Pixels[i] = this.ContentPalette[Math.Max(rle.ReadRle(), 0)];
			}
			return true;
		}

		static int PackPiPlatform(string s) { return s[0] | s[1] << 8 | s[2] << 16 | s[3] << 24; }

		static RECOILResolution GetPiPlatform(byte[] content, int contentOffset, bool highPixel)
		{
			switch (Get32LittleEndian(content, contentOffset)) {
			case 1314344788:
				return RECOILResolution.FmTowns1x1;
			case 808993616:
				return RECOILResolution.Pc801x2;
			case 943211344:
				return RECOILResolution.Pc881x2;
			case 1096172368:
				return highPixel ? RECOILResolution.Pc881x2 : RECOILResolution.Pc88Va1x1;
			case 827872077:
			case 844649293:
			case 1347965773:
			case 1381520205:
				return highPixel ? RECOILResolution.Msx21x2 : RECOILResolution.Msx21x1;
			case 1261975128:
				return RECOILResolution.X68K1x1;
			default:
				return highPixel ? RECOILResolution.Pc881x2 : RECOILResolution.Pc981x1;
			}
		}

		void SetPiPalette(byte[] content, int paletteOffset, int colors, int rOffset)
		{
			for (int c = 0; c < colors; c++) {
				int offset = paletteOffset + c * 3;
				this.ContentPalette[c] = RestrictPlatformColor(content[offset + rOffset] << 16 | content[offset + 1 - rOffset] << 8 | content[offset + 2], colors);
			}
		}

		bool DecodePi(byte[] content, int contentLength)
		{
			if (contentLength < 18 || content[0] != 'P' || content[1] != 'i')
				return false;
			PiStream s = new PiStream { Content = content, ContentOffset = 2, ContentLength = contentLength };
			if (!s.SkipUntilByte(26) || !s.SkipUntilByte(0))
				return false;
			int contentOffset = s.ContentOffset;
			if (contentOffset + 14 > contentLength || content[contentOffset] != 0)
				return false;
			int depth = content[contentOffset + 3];
			if (depth != 4 && depth != 8)
				return false;
			RECOILResolution resolution = GetPiPlatform(content, contentOffset + 4, content[contentOffset + 1] == 2 && content[contentOffset + 2] == 1);
			contentOffset += 8 + (content[contentOffset + 8] << 8) + content[contentOffset + 9];
			if (contentOffset + 6 >= contentLength)
				return false;
			int width = content[contentOffset + 2] << 8 | content[contentOffset + 3];
			int height = content[contentOffset + 4] << 8 | content[contentOffset + 5];
			if (!SetScaledSize(width, height, resolution))
				return false;
			s.ContentOffset = contentOffset + 6 + (3 << depth);
			if (s.Unpack(width, height, depth)) {
				SetPiPalette(content, contentOffset + 6, 1 << depth, 0);
				DecodeBytes(s.Indexes, 0);
				return true;
			}
			return false;
		}

		bool DecodeMaki1(byte[] content, int contentLength)
		{
