					int column = x >> 3;
					int c = colors[(y & 1) * columns + column];
					if ((bitmap[y * columns + column] >> (~x & 7) & 1) == 0)
						c >>= 4;
					this.Pixels[y * width + x] = DecodeBrus_palette[c & 15];
				}
			}
			return true;
		}

