		static bool IsGodot(byte[] content, int contentLength) { return content[0] == 'G' && content[1] == 'O' && content[2] == 'D' && content[contentLength - 1] == 173; }

		bool DecodeGodot(int width, int height, byte[] content, int contentOffset, int contentLength, bool compressed)
		{
			if (!SetSize(width, height, RECOILResolution.C641x1))
				return false;
			UflStream rle = new UflStream { Content = content, ContentOffset = contentOffset, ContentLength = contentLength, Escape = 173 };
			for (int row = 0; row < height; row += 8) {
				for (int column = 0; column < width; column += 8) {
					for (int y = 0; y < 8; y++) {
						int pixelsOffset = (row + y) * width + column;
						for (int x = 0; x < 4; x++) {
							int b = compressed ? rle.ReadRle() : rle.ReadByte();
							if (b < 0)
								return false;
							this.Pixels[pixelsOffset++] = this.C64Palette[DecodeGodot_byBrightness[b >> 4]];
							this.Pixels[pixelsOffset++] = this.C64Palette[DecodeGodot_byBrightness[b & 15]];
						}
					}
				}
			}
			return true;
		}

