		void DecodeC64HiresFrame(byte[] content, int bitmapOffset, int videoMatrixOffset, bool afli, int stride, int pixelsOffset)
		{
			for (int y = 0; y < this.Height; y++) {
				for (int x = 0; x < this.Width; x++) {
					int offset = (y & ~7) * stride + (x & ~7) + (y & 7);
					int c = content[bitmapOffset + offset] >> (~x & 7) & 1;
					int v;
					if (videoMatrixOffset >= 0) {
						offset >>= 3;
						if (afli)
							offset += (y & 7) << 10;
						v = content[videoMatrixOffset + offset];
					}
					else
						v = -videoMatrixOffset;
					c = c == 0 ? v & 15 : v >> 4;
					this.Pixels[pixelsOffset + y * this.Width + x] = this.C64Palette[c];
				}
			}
		}

