		bool DecodeMwi(byte[] content, int contentLength)
		{
			if (contentLength < 7)
				return false;
			int width = content[3] << 1;
			int height = content[4];
			if (!SetSize(width, height, RECOILResolution.C642x1))
				return false;
			int charactersPerRow = (width + 7) >> 3;
			int left = (content[1] & 3) << 1;
			if (left != 0)
				charactersPerRow++;
			int rows = (height + 7) >> 3;
			int top = content[2] & 7;
			if (top != 0)
				rows++;
			if (contentLength != 5 + rows * charactersPerRow * 10)
				return false;
			for (int y = 0; y < height; y++) {
				int screenY = top + y;
				for (int x = 0; x < width; x++) {
					int screenX = left + x;
					int offset = 5 + ((screenY >> 3) * charactersPerRow + (screenX >> 3)) * 10;
					int c;
					switch (content[offset + 2 + (screenY & 7)] >> (~screenX & 6) & 3) {
					case 1:
						c = content[offset] >> 4;
						break;
					case 2:
						c = content[offset];
						break;
					case 3:
						c = content[offset + 1];
						break;
					default:
						c = 0;
						break;
					}
					this.Pixels[y * width + x] = this.C64Palette[c & 15];
				}
			}
			return true;
		}

		bool DecodeC64Shp(byte[] content, int contentLength)
		{
			if (contentLength < 8)
				return false;
			int columns = 40;
			int height = 200;
			UflStream rle = new UflStream();
			switch (content[2]) {
			case 0:
				rle.Escape = content[3];
				rle.ContentOffset = 5;
				break;
			case 128:
				rle.Escape = content[3];
				rle.ContentOffset = 4;
				break;
			case 167:
				if (content[3] != 25)
					return false;
				columns = 39;
				rle.Escape = content[4];
				rle.ContentOffset = 5;
				break;
			case 168:
				height = content[3] << 3;
				if (height == 0 || height > 200)
					return false;
				rle.Escape = content[4];
				rle.ContentOffset = 5;
				break;
			case 232:
				if (content[3] != 25)
					return false;
				rle.Escape = content[5];
				rle.ContentOffset = 6;
				break;
			default:
				return false;
			}
			rle.Content = content;
			rle.ContentLength = contentLength;
			int bitmapLength = height * columns;
			byte[] unpacked = new byte[10001];
			if (!rle.Unpack(unpacked, 0, 1, bitmapLength))
				return false;
			rle.Escape = 0;
			if (!rle.Unpack(unpacked, bitmapLength, 1, (bitmapLength >> 3) * 9))
				return false;
			switch (content[2]) {
			case 0:
				rle.Escape = 255;
				break;
			case 232:
				if (rle.ReadByte() != 255)
					return false;
				rle.Escape = 216;
				break;
			default:
				if (rle.ContentOffset != contentLength)
					return false;
				SetSize(columns << 3, height, RECOILResolution.C641x1);
				DecodeC64HiresFrame(unpacked, 0, bitmapLength, false, columns, 0);
				return true;
			}
			unpacked[10000] = content[4];
			return rle.Unpack(unpacked, 9000, 1, 10000) && rle.ContentOffset == contentLength && DecodeKoa(unpacked, 10001);
		}

