								continue;
							}
							switch (compression) {
							case 1:
								repeatCount = content[contentOffset] + 1;
								break;
							case 2:
								repeatCount = ((content[contentOffset] << 8) + content[contentOffset + 1] + 1) << 1;
								break;
							case 3:
