				return false;
			}
		}

		bool DecodeFalconPnt(byte[] content, int contentLength)
		{
			if (contentLength < 128 || content[0] != 'P' || content[1] != 'N' || content[2] != 'T' || content[3] != 0 || content[4] != 1 || content[5] != 0 || content[12] != 0 || content[14] != 0)
				return false;
			int colors = content[6] << 8 | content[7];
			if (colors > 256)
				return false;
			int bitmapOffset = 128 + colors * 6;
			int bitmapLength = Get32BigEndian(content, 16);
			if (bitmapLength <= 0 || contentLength < bitmapOffset + bitmapLength)
				return false;
			int width = content[8] << 8 | content[9];
			int height = content[10] << 8 | content[11];
			if (width <= 0 || height > 16777216 / width)
				return false;
			int bitplanes = content[13];
			int unpackedLength = ((width + 15) >> 4 << 1) * height * bitplanes;
			switch (content[15]) {
			case 0:
				return bitmapLength == unpackedLength && DecodePntUnpacked(content, content, bitmapOffset, width, height);
			case 1:
				byte[] unpacked = new byte[unpackedLength];
				PackBitsStream rle = new PackBitsStream { Content = content, ContentOffset = bitmapOffset, ContentLength = contentLength };
				return rle.UnpackBitplaneLines(unpacked, width, height, bitplanes, true, false) && DecodePntUnpacked(content, unpacked, 0, width, height);
			default:
				return false;
			}
		}

		bool DecodeUimg(byte[] content, int contentLength)
		{
			if (contentLength < 15 || !IsStringAt(content, 0, "UIMG") || content[6] != 0)
				return false;
			int palette = content[7];
			if (palette > 4)
				return false;
			int depth = content[8];
			int chunk = content[9];
			int width = content[10] << 8 | content[11];
			int height = content[12] << 8 | content[13];
			int bitmapOffset = 14 + (DecodeUimg_paletteUnit[palette] << depth);
			int pixelsLength = width * height;
			switch (chunk) {
			case 255:
			case 0:
				if (palette == 0 || depth > 8 || (width & 15) != 0 || contentLength != bitmapOffset + (pixelsLength >> 3) * depth)
					return false;
				break;
			case 1:
				if (palette == 0 || depth > 8 || contentLength != bitmapOffset + pixelsLength)
					return false;
				break;
			case 2:
			case 3:
			case 4:
				if (palette != 0 || depth != chunk << 3 || contentLength != 14 + pixelsLength * chunk)
					return false;
				break;
			default:
				return false;
			}
			switch (palette) {
			case 0:
				if (!SetSize(width, height, RECOILResolution.Falcon1x1))
					return false;
				break;
			case 1:
				if (!SetSize(width, height, depth > 4 ? RECOILResolution.Falcon1x1 : IsStePalette(content, 14, 1 << depth) ? RECOILResolution.Ste1x1 : RECOILResolution.St1x1))
					return false;
				Array.Clear(this.ContentPalette, 0, 256);
				SetStPalette(content, 14, 1 << depth);
				break;
			case 2:
				if (!SetSize(width, height, RECOILResolution.Tt1x1))
					return false;
				Array.Clear(this.ContentPalette, 0, 256);
				SetStPalette(content, 14, 1 << depth);
				break;
			case 3:
				if (!SetSize(width, height, RECOILResolution.Falcon1x1))
					return false;
				Array.Clear(this.ContentPalette, 0, 256);
				SetFalconPalette(content, 14, 1 << depth);
				break;
			case 4:
				if (!SetSize(width, height, RECOILResolution.Falcon1x1))
					return false;
				SetStVdiPalette(content, 14, 1 << depth, depth);
				break;
			default:
				return false;
			}
			switch (chunk) {
			case 0:
				DecodeBitplanes(content, bitmapOffset, (width >> 3) * depth, depth, 0, width, height);
				return true;
			case 1:
				DecodeBytes(content, bitmapOffset);
				return true;
			case 2:
				for (int i = 0; i < pixelsLength; i++)
					this.Pixels[i] = GetFalconTrueColor(content, 14 + (i << 1));
				return true;
			case 3:
				DecodeR8G8B8Colors(content, 14, pixelsLength, this.Pixels, 0);
				return true;
			case 4:
				DecodeR8G8G8X8Colors(content, 15, pixelsLength);
				return true;
			case 255:
				switch (depth) {
				case 1:
					DecodeBitplanes(content, bitmapOffset, width >> 3, 1, 0, width, height);
					return true;
				case 2:
					DecodeMsx6(content, bitmapOffset);
					return true;
				case 4:
					DecodeNibbles(content, bitmapOffset, width >> 1);
					return true;
				default:
					return false;
				}
			default:
				throw new NotImplementedException();
			}
		}

		internal void SetOcsColor(int c, int r, int gb)
		{
			int rgb = (r & 15) << 16 | (gb & 240) << 4 | (gb & 15);
			this.ContentPalette[c] = rgb * 17;
		}

		internal void SetOcsPalette(byte[] content, int contentOffset, int colors)
		{
			for (int c = 0; c < colors; c++) {
				int r = content[contentOffset++];
				int gb = content[contentOffset++];
				SetOcsColor(c, r, gb);
			}
		}

		bool DecodeInfo(byte[] content, int contentLength)
		{
			if (contentLength < 98 || content[0] != 227 || content[1] != 16 || content[2] != 0 || content[3] != 1)
				return false;
			int[] palette;
			switch (Get32BigEndian(content, 44)) {
			case 0:
				palette = DecodeInfo_os1Palette;
				break;
			case 1:
				palette = DecodeInfo_os2Palette;
				break;
			default:
				return false;
			}
			int contentOffset = Get32BigEndian(content, 66) == 0 ? 78 : 134;
			int width = content[contentOffset + 4] << 8 | content[contentOffset + 5];
			int height = content[contentOffset + 6] << 8 | content[contentOffset + 7];
			int bitplanes = content[contentOffset + 8] << 8 | content[contentOffset + 9];
			switch (bitplanes) {
			case 2:
				break;
			case 3:
				if (palette == DecodeInfo_os1Palette)
					return false;
				break;
			default:
				return false;
			}
			int bytesPerLine = (width + 15) >> 4 << 1;
			int bitplaneLength = height * bytesPerLine;
			contentOffset += 20;
			return contentLength >= contentOffset + bitplanes * bitplaneLength && DecodeAmigaPlanar(content, contentOffset, width, height, RECOILResolution.Amiga1x2, bitplanes, palette);
		}

		bool DecodeAbkSprite(byte[] content, int contentLength)
		{
			int sprites = content[4] << 8 | content[5];
			int contentOffset = 6;
			int width = 0;
			int height = 0;
			for (int sprite = 0; sprite < sprites; sprite++) {
				if (contentOffset + 10 >= contentLength || content[contentOffset + 4] != 0)
					return false;
				int spriteWidth = (content[contentOffset] << 8 | content[contentOffset + 1]) << 4;
				int spriteHeight = content[contentOffset + 2] << 8 | content[contentOffset + 3];
				int bitplanes = content[contentOffset + 5];
				if (bitplanes == 0 || bitplanes > 5)
					return false;
				width += spriteWidth;
				if (height < spriteHeight)
					height = spriteHeight;
				if (width <= 0 || height > 16777216 / width)
					return false;
				contentOffset += 10 + (spriteWidth >> 3) * spriteHeight * bitplanes;
			}
			if (contentOffset + 64 != contentLength || !SetSize(width, height, RECOILResolution.Amiga1x1))
				return false;
			SetOcsPalette(content, contentOffset, 32);
			contentOffset = 6;
			int left = 0;
			for (int sprite = 0; sprite < sprites; sprite++) {
				int spriteWidth = (content[contentOffset] << 8 | content[contentOffset + 1]) << 4;
				int spriteHeight = content[contentOffset + 2] << 8 | content[contentOffset + 3];
				int bitplanes = content[contentOffset + 5];
				int bytesPerLine = spriteWidth >> 3;
				int bitplaneLength = height * bytesPerLine;
				for (int y = 0; y < spriteHeight; y++) {
					for (int x = 0; x < spriteWidth; x++)
						this.Pixels[y * width + left + x] = this.ContentPalette[GetBitplanePixel(content, contentOffset + 10 + y * bytesPerLine + (x >> 3), x, bitplanes, bitplaneLength)];
				}
				for (int y = spriteHeight; y < height; y++)
					Array.Clear(this.Pixels, y * width + left, spriteWidth);
				contentOffset += 10 + bitplanes * bitplaneLength;
				left += spriteWidth;
			}
			return true;
		}

		bool DecodeAbk(byte[] content, int contentLength)
		{
			if (contentLength < 82 || content[0] != 'A' || content[1] != 'm')
				return false;
			switch (content[2]) {
			case (byte) 'S':
				return content[3] == 'p' && DecodeAbkSprite(content, contentLength);
			case (byte) 'I':
				return content[3] == 'c' && DecodeAbkSprite(content, contentLength);
			case (byte) 'B':
				break;
			default:
				return false;
			}
			if (content[3] != 'k' || contentLength < 135 || !IsStringAt(content, 12, "Pac.Pic") || content[110] != 6 || content[111] != 7 || content[112] != 25 || content[113] != 99 || content[124] != 0)
				return false;
			int width = content[118] << 8 | content[119];
			if ((width & 1) != 0)
				return false;
			int lumps = content[120] << 8 | content[121];
			int lumpLines = content[122] << 8 | content[123];
			int height = lumps * lumpLines;
			int bitplanes = content[125];
			if (bitplanes == 0 || bitplanes > 5 || !SetSize(width << 3, height, RECOILResolution.Amiga1x1))
				return false;
			int rleOffset = 110 + Get32BigEndian(content, 126);
			if (rleOffset < 0 || rleOffset >= contentLength)
				return false;
			int pointsOffset = 110 + Get32BigEndian(content, 130);
			if (pointsOffset < 0)
				return false;
			byte[] unpacked = new byte[bitplanes * width * height];
			int picOffset = 135;
			int pic = content[134];
			int rleBits = content[rleOffset++] << 8 | 128;
			int pointsBits = 0;
			for (int bitplane = 0; bitplane < bitplanes; bitplane++) {
				for (int lump = 0; lump < lumps; lump++) {
					for (int x = 0; x < width; x++) {
						for (int y = 0; y < lumpLines; y++) {
							rleBits <<= 1;
							if ((rleBits & 255) == 0) {
								pointsBits <<= 1;
								if ((pointsBits & 255) == 0) {
									if (pointsOffset >= contentLength)
										return false;
									pointsBits = content[pointsOffset++] << 1 | 1;
								}
								if ((pointsBits >> 8 & 1) != 0) {
									if (rleOffset >= contentLength)
										return false;
									rleBits = content[rleOffset++] << 1 | 1;
								}
								else
									rleBits >>= 8;
							}
							if ((rleBits >> 8 & 1) != 0) {
								if (picOffset >= contentLength)
									return false;
								pic = content[picOffset++];
							}
							unpacked[((bitplane * lumps + lump) * lumpLines + y) * width + x] = (byte) pic;
						}
					}
				}
			}
			SetOcsPalette(content, 46, 32);
			return DecodeAmigaPlanar(unpacked, 0, width << 3, height, RECOILResolution.Amiga1x1, bitplanes, this.ContentPalette);
		}

		static RECOILResolution GetAmigaAspectRatio(int xRatio, int yRatio, RECOILResolution resolution)
		{
			if (xRatio <= 0 || yRatio <= 0)
				return resolution;
			if (xRatio > yRatio * 6)
				return RECOILResolution.Amiga8x1;
			if (xRatio > yRatio * 3)
				return RECOILResolution.Amiga4x1;
			if (xRatio * 2 > yRatio * 3)
				return RECOILResolution.Amiga2x1;
			if (yRatio > xRatio * 3)
				return RECOILResolution.Amiga1x4;
			if (yRatio * 2 > xRatio * 3)
				return resolution == RECOILResolution.Amiga1x1 ? RECOILResolution.Amiga1x2 : RECOILResolution.St1x2;
			return resolution;
		}

		static RECOILResolution GetCamgAspectRatio(int camg, RECOILResolution resolution)
		{
			int log;
			switch (camg & ~61439) {
			case 0:
			case 69632:
			case 135168:
			case 462848:
			case 790528:
			case 856064:
				camg &= 32812;
				log = 0;
				break;
			case 266240:
				return RECOILResolution.Amiga1x1;
			case 331776:
			case 528384:
			case 724992:
			case 921600:
				camg &= 32812;
				log = -1;
				break;
			case 200704:
			case 397312:
				camg &= 32805;
				log = -1;
				break;
			case 593920:
			case 659456:
				camg &= 33285;
				log = 0;
				break;
			default:
				return resolution;
			}
			switch (camg & 33312) {
			case 0:
				break;
			case 32768:
				log++;
				break;
			case 32800:
				log += 2;
				break;
			case 512:
				log--;
				break;
			default:
				return resolution;
			}
			switch (camg & 13) {
			case 0:
				break;
			case 4:
				log--;
				break;
			case 5:
				log -= 2;
				break;
			case 8:
				log++;
				break;
			default:
				return resolution;
			}
			switch (log) {
			case 0:
				return RECOILResolution.Amiga1x1;
			case -1:
				return RECOILResolution.Amiga2x1;
			case -2:
				return RECOILResolution.Amiga4x1;
			case -3:
				return RECOILResolution.Amiga8x1;
			case 1:
				return RECOILResolution.Amiga1x2;
			case 2:
				return RECOILResolution.Amiga1x4;
			default:
				return resolution;
			}
		}

		bool DecodeDeep(byte[] content, int contentLength)
		{
			int width = 0;
			int height = 0;
			int compression = 0;
			RECOILResolution resolution = RECOILResolution.Amiga1x1;
			DeepStream rle = new DeepStream { Content = content };
			int tvdcOffset = -1;
			for (int contentOffset = 12; contentOffset < contentLength - 7;) {
				int chunkLength = Get32BigEndian(content, contentOffset + 4);
				int chunkEndOffset = contentOffset + 8 + chunkLength;
				if (chunkEndOffset > contentLength || chunkEndOffset < contentOffset + 8)
					break;
				if (IsStringAt(content, contentOffset, "DGBL")) {
					if (chunkLength < 8 || content[contentOffset + 12] != 0)
						return false;
					width = content[contentOffset + 8] << 8 | content[contentOffset + 9];
					height = content[contentOffset + 10] << 8 | content[contentOffset + 11];
					compression = content[contentOffset + 13];
					resolution = GetAmigaAspectRatio(content[contentOffset + 14], content[contentOffset + 15], resolution);
				}
				else if (IsStringAt(content, contentOffset, "DPEL")) {
					if (!rle.SetDpel(contentOffset, chunkLength))
						return false;
				}
				else if (IsStringAt(content, contentOffset, "DLOC")) {
					if (chunkLength < 4)
						return false;
					width = content[contentOffset + 8] << 8 | content[contentOffset + 9];
					height = content[contentOffset + 10] << 8 | content[contentOffset + 11];
				}
				else if (IsStringAt(content, contentOffset, "TVDC")) {
					if (chunkLength != 32)
						return false;
					tvdcOffset = contentOffset + 8;
				}
				else if (IsStringAt(content, contentOffset, "DBOD")) {
					if (chunkEndOffset + 8 < contentLength && IsStringAt(content, chunkEndOffset, "DBOD"))
						return false;
					if (rle.Components <= 0 || !SetScaledSize(width, height, resolution))
						return false;
					rle.ContentOffset = contentOffset + 8;
					rle.ContentLength = chunkEndOffset;
					for (int y = 0; y < height; y++) {
						if (compression == 5) {
							if (tvdcOffset < 0 || !rle.ReadDeltaLine(width, tvdcOffset))
								return false;
						}
						for (int x = 0; x < width; x++) {
							int rgb;
							switch (compression) {
							case 0:
								rgb = rle.ReadValue();
								break;
							case 1:
								rgb = rle.ReadRle();
								break;
							case 5:
								rgb = rle.Line[x];
								break;
							default:
								return false;
							}
							if (rgb < 0)
								return false;
							SetScaledPixel(x, y, rgb);
						}
					}
					return true;
				}
				contentOffset = (chunkEndOffset + 1) & ~1;
			}
			return false;
		}

		bool DecodeRgbn(byte[] content, int contentOffset, int contentLength, int width, int height, bool rgb8)
		{
			int rgb = 0;
			int count = 0;
			for (int y = 0; y < height; y++) {
				for (int x = 0; x < width; x++) {
					if (count == 0) {
						if (rgb8) {
							if (contentOffset > contentLength - 4)
								return false;
							rgb = GetR8G8B8Color(content, contentOffset);
							count = content[contentOffset + 3] & 127;
							contentOffset += 4;
						}
						else {
							if (contentOffset > contentLength - 2)
								return false;
							rgb = content[contentOffset];
							count = content[contentOffset + 1];
							rgb = (((rgb & 240) << 4 | (rgb & 15)) << 8 | count >> 4) * 17;
							count &= 7;
							contentOffset += 2;
						}
						if (count == 0) {
							if (contentOffset >= contentLength)
								return false;
							count = content[contentOffset++];
							if (count == 0) {
								if (contentOffset > contentLength - 2)
									return false;
								count = content[contentOffset] << 8 | content[contentOffset + 1];
								contentOffset += 2;
							}
						}
					}
					SetScaledPixel(x, y, rgb);
					count--;
				}
			}
			return true;
		}

		bool DecodeRast(byte[] content, int contentOffset, int contentLength, byte[] unpacked, int width, int height, int bitplanes)
		{
			if (!SetSizeStOrFalcon(width, height, bitplanes, false))
				return false;
			RastPalette rast = new RastPalette { Content = content, ContentOffset = contentOffset + 8, ContentLength = contentLength, Colors = 1 << bitplanes };
			DecodeScaledBitplanes(unpacked, 0, width, height, bitplanes, false, rast);
			return true;
		}

		int DecodeHamPixel(int rgb, int c, int holdBits)
		{
			switch (c >> holdBits) {
			case 0:
				return this.ContentPalette[c];
			case 1:
				c = c << (8 - holdBits) & 255;
				c |= c >> holdBits;
				return (rgb & 16776960) | c;
			case 2:
				c = c << (8 - holdBits) & 255;
				c |= c >> holdBits;
				return (rgb & 65535) | c << 16;
			case 3:
				c = c << (8 - holdBits) & 255;
				c |= c >> holdBits;
				return (rgb & 16711935) | c << 8;
			default:
				throw new NotImplementedException();
			}
		}

		void DecodeHam(byte[] unpacked, int width, int height, int bitplanes, MultiPalette multiPalette)
		{
			int bytesPerLine = ((width + 15) >> 4 << 1) * bitplanes;
			int holdBits = bitplanes > 6 ? 6 : 4;
			for (int y = 0; y < height; y++) {
				if (multiPalette != null)
					multiPalette.SetLinePalette(this, y);
				int rgb = this.ContentPalette[0];
				for (int x = 0; x < width; x++) {
					int c = GetBitplaneWordsPixel(unpacked, y * bytesPerLine, x, bitplanes);
					rgb = DecodeHamPixel(rgb, c, holdBits);
					SetScaledPixel(x, y, rgb);
				}
			}
		}

		int GetHameNibble(byte[] content, int contentOffset, int x)
		{
			int c = GetStLowPixel(content, contentOffset, x);
			int rgb = this.ContentPalette[c];
			return (rgb >> 20 & 8) | (rgb >> 13 & 4) | (rgb >> 6 & 2) | (rgb >> 4 & 1);
		}

		int GetHameByte(byte[] content, int contentOffset, int x) { return GetHameNibble(content, contentOffset, x << 1) << 4 | GetHameNibble(content, contentOffset, (x << 1) + 1); }

		bool IsHame(byte[] content, int contentOffset)
		{
			for (int i = 0; i < 7; i++) {
				if (GetHameByte(content, contentOffset, i) != IsHame_magic[i])
					return false;
			}
			switch (GetHameByte(content, contentOffset, 7)) {
			case 20:
			case 24:
				return true;
			default:
				return false;
			}
		}

		void DecodeHame(byte[] content, int width)
		{
			int[] palette = new int[512];
			int[] paletteLength = new int[2];
			bool hame = false;
			for (int y = 0; y < this.Height; y++) {
				int lineOffset = y * width;
				int paletteOffset = this.Resolution == RECOILResolution.AmigaHame2x1 && (y & 1) != 0 ? 256 : 0;
				if (IsHame(content, lineOffset)) {
					paletteOffset += paletteLength[paletteOffset >> 8];
					for (int c = 0; c < 64; c++) {
						int offset = 8 + c * 3;
						palette[paletteOffset + c] = GetHameByte(content, lineOffset, offset) << 16 | GetHameByte(content, lineOffset, offset + 1) << 8 | GetHameByte(content, lineOffset, offset + 2);
					}
					paletteLength[paletteOffset >> 8] = (paletteLength[paletteOffset >> 8] + 64) & 255;
					hame = GetHameByte(content, lineOffset, 7) == 24;
					Array.Clear(this.Pixels, y * this.Width, this.Width);
				}
				else {
					int paletteBank = 0;
					int rgb = 0;
					for (int x = 0; x < width; x++) {
						int c = GetHameByte(content, lineOffset, x);
						if (hame) {
							switch (c >> 6) {
							case 0:
								if (c < 60)
									rgb = palette[paletteOffset + paletteBank + c];
								else
									paletteBank = (c - 60) << 6;
								break;
							case 1:
								rgb = (c & 63) << 2 | (rgb & 16776960);
								break;
							case 2:
								rgb = (c & 63) << 18 | (rgb & 65535);
								break;
							default:
								rgb = (c & 63) << 10 | (rgb & 16711935);
								break;
							}
						}
						else
							rgb = palette[paletteOffset + c];
						SetScaledPixel(x, y, rgb);
					}
				}
			}
		}

		const int DctvMaxWidth = 2048;

		int GetDctvValue(byte[] content, int contentOffset, int x, int bitplanes)
		{
			int c = GetBitplaneWordsPixel(content, contentOffset, x, bitplanes);
			int rgb = this.ContentPalette[c];
			return (rgb << 2 & 64) | (rgb >> 19 & 16) | (rgb >> 5 & 4) | (rgb >> 15 & 1);
		}

		bool IsDctv(byte[] content, int contentOffset, int bitplanes)
		{
			if (GetDctvValue(content, contentOffset, 0, bitplanes) >> 6 != 0)
				return false;
			int r = 125;
			for (int x = 1; x < 256; x++) {
				if (GetDctvValue(content, contentOffset, x, bitplanes) >> 6 == (r & 1))
					return false;
				if ((r & 1) != 0)
					r ^= 390;
				r >>= 1;
			}
			return true;
		}

		static int ClampByte(int x) { return x <= 0 ? 0 : x >= 255 ? 255 : x; }

		bool DecodeDctv(byte[] content, int width, int height, RECOILResolution resolution, int bitplanes)
		{
			if (!IsDctv(content, 0, bitplanes))
				return false;
			int interlace;
			int bytesPerLine = ((width + 15) >> 4 << 1) * bitplanes;
			if (resolution == RECOILResolution.Amiga1x2) {
				interlace = 0;
				height--;
				resolution = RECOILResolution.AmigaDctv1x2;
			}
			else {
				if (!IsDctv(content, bytesPerLine, bitplanes))
					return false;
				interlace = 1;
				height -= 2;
				resolution = RECOILResolution.AmigaDctv1x1;
			}
			SetScaledSize(width, height, resolution);
			int contentOffset = bytesPerLine << interlace;
			int[] chroma = new int[2048];
			for (int y = 0; y < height; y++) {
				int odd = y >> interlace & 1;
				int rgb = 0;
				int o = 0;
				int p = 0;
				for (int x = 0; x < width; x++) {
					if ((x & 1) == odd) {
						int n = x + 1 < width ? GetDctvValue(content, contentOffset, x, bitplanes) << 1 | GetDctvValue(content, contentOffset, x + 1, bitplanes) : 0;
						int i = (o + n) >> 1;
						i = i <= 64 ? 0 : i >= 224 ? 255 : (i - 64) * 8 / 5;
						int u = n + p - (o << 1);
						if (u < 0)
							u += 3;
						u >>= 2;
						if (((x + 1) & 2) == 0)
							u = -u;
						int chromaOffset = (x & ~1) | (y & interlace);
						int v = y > interlace ? chroma[chromaOffset] : 0;
						chroma[chromaOffset] = u;
						if (odd == 0) {
							u = v;
							v = chroma[chromaOffset];
						}
						p = o;
						o = n;
						int r = i + v * 4655 / 2560;
						int b = i + u * 8286 / 2560;
						int g = i - (v * 2372 + u * 1616) / 2560;
						rgb = ClampByte(r) << 16 | ClampByte(g) << 8 | ClampByte(b);
					}
					SetScaledPixel(x, y, rgb);
				}
				contentOffset += bytesPerLine;
			}
			return true;
		}

		bool DecodeIffUnpacked(byte[] unpacked, int width, int height, RECOILResolution resolution, int bitplanes, int colors, int camg, MultiPalette multiPalette)
		{
			if (!SetScaledSize(width, height, resolution))
				return false;
			if (bitplanes <= 8) {
				if (colors == 0) {
					colors = 1 << bitplanes;
					for (int c = 0; c < colors; c++)
						this.ContentPalette[c] = c * 255 / colors * 65793;
				}
				if ((camg & 2048) != 0 || (bitplanes == 6 && colors == 16)) {
					DecodeHam(unpacked, width, height, bitplanes, multiPalette);
				}
				else if (width >= 400 && (resolution == RECOILResolution.Amiga1x2 || resolution == RECOILResolution.Amiga1x1) && bitplanes == 4 && multiPalette == null && IsHame(unpacked, 0)) {
					if (resolution == RECOILResolution.Amiga1x2)
						SetSize(width >> 1, height, RECOILResolution.AmigaHame1x1);
					else
						SetSize(width, height, RECOILResolution.AmigaHame2x1);
					DecodeHame(unpacked, width >> 1);
				}
				else if (width >= 256 && width <= 2048 && height >= 3 && (resolution == RECOILResolution.Amiga1x2 || resolution == RECOILResolution.Amiga1x1) && multiPalette == null && DecodeDctv(unpacked, width, height, resolution, bitplanes)) {
				}
				else {
					DecodeScaledBitplanes(unpacked, 0, width, height, bitplanes, bitplanes == 6 && ((camg & 128) != 0 || colors == 32), multiPalette);
				}
			}
			else {
				int bytesPerBitplane = (width + 15) >> 4 << 1;
				for (int y = 0; y < height; y++) {
					for (int x = 0; x < width; x++) {
						int offset = (y * bytesPerBitplane + (x >> 3 & ~1)) * bitplanes + (x >> 3 & 1);
						int c = GetBitplanePixel(unpacked, offset, x, 24, 2);
						SetScaledPixel(x, y, (c & 255) << 16 | (c & 65280) | c >> 16);
					}
				}
			}
			return true;
		}

		bool DecodeIff(byte[] content, int contentLength, RECOILResolution resolution)
		{
			if (contentLength < 56 || !IsStringAt(content, 0, "FORM"))
				return false;
			if (IsStringAt(content, 8, "DEEP") || IsStringAt(content, 8, "TVPP"))
				return DecodeDeep(content, contentLength);
			int contentOffset = 8;
			if (IsStringAt(content, 8, "DPSTDPAH") && Get32BigEndian(content, 16) == 24 && IsStringAt(content, 44, "FORM"))
				contentOffset = 52;
			else if (IsStringAt(content, 8, "ANIMFORM"))
				contentOffset = 20;
			IffType type;
			if (IsStringAt(content, contentOffset, "ILBM"))
				type = IffType.Ilbm;
			else if (IsStringAt(content, contentOffset, "PBM "))
				type = IffType.Pbm;
			else if (IsStringAt(content, contentOffset, "ACBM"))
				type = IffType.Acbm;
			else if (IsStringAt(content, contentOffset, "RGB8"))
				type = IffType.Rgb8;
			else if (IsStringAt(content, contentOffset, "RGBN"))
				type = IffType.Rgbn;
			else
				return false;
			contentOffset += 4;
			int width = 0;
			int height = 0;
			int bitplanes = 0;
			bool hasMask = false;
			int compression = 0;
			bool ocsPalette = false;
			int colors = 0;
			int camg = 0;
			CtblPalette ctbl = new CtblPalette();
			ShamLacePalette sham = new ShamLacePalette();
			PchgPalette pchg = new PchgPalette();
			MultiPalette multiPalette = null;
			while (contentOffset < contentLength - 7) {
				int chunkLength = Get32BigEndian(content, contentOffset + 4);
				int chunkEndOffset = contentOffset + 8 + chunkLength;
				if (chunkEndOffset > contentLength || chunkEndOffset < contentOffset + 8) {
					chunkEndOffset = contentLength;
					chunkLength = contentLength - contentOffset - 8;
				}
				if (IsStringAt(content, contentOffset, "BMHD") && chunkLength >= 16) {
					width = content[contentOffset + 8] << 8 | content[contentOffset + 9];
					height = content[contentOffset + 10] << 8 | content[contentOffset + 11];
					bitplanes = content[contentOffset + 16];
					hasMask = content[contentOffset + 17] == 1;
					compression = content[contentOffset + 18];
					switch (type) {
					case IffType.Pbm:
						if (bitplanes != 8 || compression > 1)
							return false;
						break;
					case IffType.Rgb8:
						if (bitplanes != 25 || compression != 4)
							return false;
						break;
					case IffType.Rgbn:
						if (bitplanes != 13 || compression != 4)
							return false;
						break;
					default:
						if (bitplanes == 0 || (bitplanes > 8 && bitplanes != 24 && bitplanes != 32) || compression > 2)
							return false;
						break;
					}
					int pixelsCount = width * height;
					if (pixelsCount <= 0 || pixelsCount > 16777216)
						return false;
					ocsPalette = content[contentOffset + 19] != 128;
					resolution = GetAmigaAspectRatio(content[contentOffset + 22], content[contentOffset + 23], resolution);
				}
				else if (IsStringAt(content, contentOffset, "CMAP")) {
					colors = chunkLength / 3;
					if (colors > 256)
						return false;
					if (colors > 32)
						ocsPalette = false;
					for (int c = 0; c < colors; c++) {
						this.ContentPalette[c] = GetR8G8B8Color(content, contentOffset + 8 + c * 3);
						if ((this.ContentPalette[c] & 986895) != 0)
							ocsPalette = false;
					}
					if (ocsPalette) {
						for (int c = 0; c < colors; c++)
							this.ContentPalette[c] |= this.ContentPalette[c] >> 4;
					}
					Array.Clear(this.ContentPalette, colors, 256 - colors);
				}
				else if (IsStringAt(content, contentOffset, "CAMG") && chunkLength >= 4) {
					camg = Get32BigEndian(content, contentOffset + 8);
					resolution = GetCamgAspectRatio(camg, resolution);
				}
				else if ((IsStringAt(content, contentOffset, "CTBL") || IsStringAt(content, contentOffset, "BEAM")) && height > 0) {
					ctbl.Colors = (chunkLength >> 1) / height;
					if (ctbl.Colors <= 32) {
						ctbl.Content = content;
						ctbl.ContentOffset = contentOffset + 8;
						multiPalette = ctbl;
					}
				}
				else if (IsStringAt(content, contentOffset, "SHAM") && chunkLength >= 2 && content[contentOffset + 8] == 0 && content[contentOffset + 9] == 0) {
					if (chunkLength == 2 + (height << 5)) {
						ctbl.Content = content;
						ctbl.ContentOffset = contentOffset + 10;
						ctbl.Colors = 16;
						multiPalette = ctbl;
					}
					else if (chunkLength == 2 + (height >> 1 << 5)) {
						sham.Content = content;
						sham.ContentOffset = contentOffset + 10;
						multiPalette = sham;
					}
				}
				else if (IsStringAt(content, contentOffset, "PCHG")) {
					pchg.Content = content;
					pchg.ContentOffset = contentOffset + 8;
					pchg.ContentLength = chunkEndOffset;
					if (!pchg.Init())
						return false;
					multiPalette = pchg;
				}
				else if (IsStringAt(content, contentOffset, "BODY")) {
					if (width == 0)
						return false;
					if (compression == 4)
						return SetScaledSize(width, height, resolution) && DecodeRgbn(content, contentOffset + 8, chunkEndOffset, width, height, type == IffType.Rgb8);
					int bytesPerLine = ((width + 15) >> 4 << 1) * bitplanes;
					byte[] unpacked;
					if (compression == 2) {
						unpacked = new byte[bytesPerLine * height];
						VdatStream rle = new VdatStream { Content = content, ContentOffset = contentOffset + 8 };
						for (int bitplane = 0; bitplane < bitplanes; bitplane++) {
							if (rle.ContentOffset + 14 > chunkEndOffset || !IsStringAt(content, rle.ContentOffset, "VDAT"))
								return false;
							int nextContentOffset = rle.ContentOffset + 8 + Get32BigEndian(content, rle.ContentOffset + 4);
							if (nextContentOffset > chunkEndOffset)
								return false;
							rle.ValueOffset = rle.ContentLength = rle.ContentOffset + 8 + (content[rle.ContentOffset + 8] << 8) + content[rle.ContentOffset + 9];
							rle.ValueLength = nextContentOffset;
							rle.ContentOffset += 10;
							for (int x = bitplane << 1; x < bytesPerLine; x += bitplanes << 1) {
								int unpackedOffset = x;
								for (int y = 0; y < height; y++) {
									int b = rle.ReadRle();
									if (b < 0)
										return false;
									unpacked[unpackedOffset] = (byte) (b >> 8);
									unpacked[unpackedOffset + 1] = (byte) b;
									unpackedOffset += bytesPerLine;
								}
							}
							rle.ContentOffset = nextContentOffset;
						}
						resolution = resolution == RECOILResolution.Amiga1x2 ? RECOILResolution.St1x2 : RECOILResolution.St1x1;
					}
					else {
						PackBitsStream rle = new PackBitsStream { Content = content, ContentOffset = contentOffset + 8, ContentLength = chunkEndOffset };
						if (type == IffType.Pbm) {
							if (colors == 0 || !SetScaledSize(width, height, resolution))
								return false;
							for (int y = 0; y < height; y++) {
								for (int x = 0; x < width; x++) {
									int b = compression == 0 ? rle.ReadByte() : rle.ReadRle();
									if (b < 0)
										return false;
									SetScaledPixel(x, y, this.ContentPalette[b]);
								}
								if ((width & 1) != 0 && (compression == 0 ? rle.ReadByte() : rle.ReadRle()) < 0)
									return false;
							}
							return true;
						}
						unpacked = new byte[bytesPerLine * height];
						if (!rle.UnpackBitplaneLines(unpacked, width, height, bitplanes, compression == 1, hasMask))
							return false;
					}
					if (bitplanes <= 8 && chunkEndOffset < contentLength - 8) {
						int nextChunkOffset = (chunkEndOffset + 1) & ~1;
						if (IsStringAt(content, nextChunkOffset, "RAST"))
							return DecodeRast(content, nextChunkOffset, contentLength, unpacked, width, height, bitplanes);
						if (IsStringAt(content, chunkEndOffset, "RAST")) {
							return DecodeRast(content, chunkEndOffset, contentLength, unpacked, width, height, bitplanes);
						}
					}
					return DecodeIffUnpacked(unpacked, width, height, resolution, bitplanes, colors, camg, multiPalette);
				}
				else if (IsStringAt(content, contentOffset, "ABIT")) {
					if (width == 0 || chunkLength != ((width + 15) >> 4 << 1) * height * bitplanes)
						return false;
					contentOffset += 8;
					byte[] unpacked = new byte[chunkLength];
					for (int bitplane = 0; bitplane < bitplanes; bitplane++) {
						for (int unpackedOffset = bitplane << 1; unpackedOffset < chunkLength; unpackedOffset += bitplanes << 1) {
							unpacked[unpackedOffset] = content[contentOffset++];
							unpacked[unpackedOffset + 1] = content[contentOffset++];
						}
					}
					return DecodeIffUnpacked(unpacked, width, height, resolution, bitplanes, colors, camg, multiPalette);
				}
				contentOffset = (chunkEndOffset + 1) & ~1;
			}
			return false;
		}

		static int ParseAtari8ExecutableHeader(byte[] content, int contentOffset)
		{
			if (content[contentOffset] != 255 || content[contentOffset + 1] != 255)
				return -1;
			int startAddress = content[contentOffset + 2] | content[contentOffset + 3] << 8;
			int endAddress = content[contentOffset + 4] | content[contentOffset + 5] << 8;
			return endAddress - startAddress + 1;
		}

		static int GetAtari8ExecutableOffset(byte[] content, int contentLength)
		{
			if (contentLength >= 7) {
				int blockLength = ParseAtari8ExecutableHeader(content, 0);
				if (blockLength > 0 && 6 + blockLength == contentLength)
					return 6;
			}
			return 0;
		}

		bool SetAtari8RawSize(byte[] content, int contentLength, RECOILResolution resolution)
		{
			int contentOffset = GetAtari8ExecutableOffset(content, contentLength);
			int height = (contentLength - contentOffset) / 40;
			if (height == 0 || height > 240)
				return false;
			SetSize(320, height, resolution);
			return true;
		}

		readonly byte[] GtiaColors = new byte[16];

		void SetGtiaColor(int reg, int value)
		{
			value &= 254;
			switch (reg) {
			case 0:
			case 1:
			case 2:
			case 3:
				this.GtiaColors[reg] = (byte) value;
				break;
			case 4:
			case 5:
			case 6:
			case 7:
				this.GtiaColors[8 + reg] = this.GtiaColors[reg] = (byte) value;
				break;
			case 8:
				this.GtiaColors[11] = this.GtiaColors[10] = this.GtiaColors[9] = this.GtiaColors[8] = (byte) value;
				break;
			default:
				throw new NotImplementedException();
			}
		}

		void SetPM123PF0123Bak(byte[] content, int contentOffset)
		{
			for (int i = 0; i < 8; i++)
				SetGtiaColor(1 + i, content[contentOffset + i]);
		}

		void SetGtiaColors(byte[] content, int contentOffset)
		{
			this.GtiaColors[0] = (byte) (content[contentOffset] & 254);
			SetPM123PF0123Bak(content, contentOffset + 1);
		}

		void SetPF21(byte[] content, int contentOffset)
		{
			this.GtiaColors[6] = (byte) (content[contentOffset] & 254);
			this.GtiaColors[5] = (byte) (content[contentOffset + 1] & 254);
		}

		void SetXeOsDefaultColors()
		{
			this.GtiaColors[8] = 0;
			this.GtiaColors[4] = 40;
			this.GtiaColors[5] = 202;
			this.GtiaColors[6] = 148;
			this.GtiaColors[7] = 70;
		}

		void SetGr15DefaultColors()
		{
			this.GtiaColors[8] = 0;
			this.GtiaColors[4] = 4;
			this.GtiaColors[5] = 8;
			this.GtiaColors[6] = 12;
		}

		void SetBakPF012(byte[] content, int contentOffset, int contentStride)
		{
			for (int i = 0; i < 4; i++)
				this.GtiaColors[i == 0 ? 8 : 3 + i] = (byte) (content[contentOffset + i * contentStride] & 254);
		}

		void SetBakPF0123(byte[] content, int contentOffset)
		{
			for (int i = 0; i < 5; i++)
				this.GtiaColors[i == 0 ? 8 : 3 + i] = (byte) (content[contentOffset + i] & 254);
		}

		void SetPF012Bak(byte[] content, int contentOffset)
		{
			for (int i = 0; i < 4; i++)
				this.GtiaColors[i == 3 ? 8 : 4 + i] = (byte) (content[contentOffset + i] & 254);
		}

		void SetPF0123Bak(byte[] content, int contentOffset)
		{
			for (int i = 0; i < 5; i++)
				this.GtiaColors[4 + i] = (byte) (content[contentOffset + i] & 254);
		}

		void SetPF0123Even(byte[] content, int contentOffset)
		{
			for (int i = 0; i < 4; i++)
				this.GtiaColors[4 + i] = (byte) (content[contentOffset + i * 2] & 254);
		}

		void DecodeAtari8Gr8(byte[] content, int contentOffset, byte[] frame, int frameOffset, int height)
		{
			byte[] colors = new byte[2];
			colors[0] = this.GtiaColors[6];
			colors[1] = (byte) ((this.GtiaColors[6] & 240) | (this.GtiaColors[5] & 14));
			frameOffset -= this.LeftSkip;
			for (int y = 0; y < height; y++) {
				int x;
				for (x = this.LeftSkip; x < this.Width; x++) {
					int c = content[contentOffset + (x >> 3)] >> (~x & 7) & 1;
					frame[frameOffset + x] = colors[c];
				}
				for (; x < this.Width + this.LeftSkip; x++)
					frame[frameOffset + x] = this.GtiaColors[8];
				contentOffset += (this.Width + 7) >> 3;
				frameOffset += this.Width;
			}
		}

		void DecodeAtari8Gr15(byte[] content, int contentOffset, int contentStride, byte[] frame, int frameOffset, int frameStride, int height)
		{
			for (int y = 0; y < height; y++) {
				for (int x = 0; x < this.Width; x++) {
					int c = content[contentOffset + (x >> 3)] >> (~x & 6) & 3;
					frame[frameOffset + x] = this.GtiaColors[c == 0 ? 8 : c + 3];
				}
				contentOffset += contentStride;
				frameOffset += frameStride;
			}
		}

		void DecodeAtari8Gr7(byte[] content, int contentOffset, byte[] frame, int frameOffset, int height)
		{
			for (int y = 0; y < height; y++) {
				for (int x = 0; x < this.Width; x++) {
					int c = content[contentOffset + (x >> 3)] >> (~x & 6) & 3;
					frame[frameOffset + x + this.Width] = frame[frameOffset + x] = this.GtiaColors[c == 0 ? 8 : c + 3];
				}
				contentOffset += this.Width >> 3;
				frameOffset += this.Width << 1;
			}
		}

		void DecodeAtari8Gr3(byte[] content, byte[] frame)
		{
			for (int y = 0; y < this.Height; y++) {
				for (int x = 0; x < this.Width; x++) {
					int c = content[(y >> 3) * (this.Width >> 5) + (x >> 5)] >> (~(x >> 2) & 6) & 3;
					frame[y * this.Width + x] = this.GtiaColors[c == 0 ? 8 : c + 3];
				}
			}
		}

		void DecodeAtari8Gr9(byte[] content, int contentOffset, int contentStride, byte[] frame, int frameOffset, int frameStride, int width, int height)
		{
			for (int y = 0; y < height; y++) {
				for (int x = 0; x < width; x++) {
					int i = x + this.LeftSkip;
					int c = i < 0 || i >= width ? 0 : content[contentOffset + (i >> 3)] >> (~i & 4) & 15;
					frame[frameOffset + x] = (byte) (this.GtiaColors[8] | c);
				}
				contentOffset += contentStride;
				frameOffset += frameStride;
			}
		}

		void DecodeAtari8Gr11(byte[] content, int contentOffset, byte[] frame, int frameOffset, int frameStride, int height)
		{
			frameOffset -= this.LeftSkip;
			for (int y = 0; y < height; y++) {
				int x;
				for (x = this.LeftSkip; x < this.Width; x++) {
					int c = content[contentOffset + (x >> 3)] << (x & 4) & 240;
					c = c == 0 ? this.GtiaColors[8] & 240 : this.GtiaColors[8] | c;
					frame[frameOffset + x] = (byte) c;
				}
				for (; x < this.Width + this.LeftSkip; x++)
					frame[frameOffset + x] = (byte) (this.GtiaColors[8] & 240);
				contentOffset += this.Width >> 3;
				frameOffset += frameStride;
			}
		}

		void DecodeAtari8Gr10(byte[] content, int contentOffset, byte[] frame, int frameOffset, int frameStride, int height)
		{
			frameOffset += 2 - this.LeftSkip;
			for (int y = 0; y < height; y++) {
				int x;
				for (x = this.LeftSkip - 2; x < 0; x++)
					frame[frameOffset + x] = this.GtiaColors[0];
				for (; x < this.Width + this.LeftSkip - 2; x++) {
					int c = content[contentOffset + (x >> 3)] >> (~x & 4) & 15;
					frame[frameOffset + x] = this.GtiaColors[c];
				}
				contentOffset += this.Width >> 3;
				frameOffset += frameStride;
			}
		}

		void DecodeAtari8Gr11PalBlend(byte[] content, int contentOffset, int contentStride, byte[] frame, int y)
		{
			for (; y < this.Height; y += 2) {
				int frameOffset = y * this.Width - this.LeftSkip;
				for (int x = this.LeftSkip; x < this.Width; x++) {
					int c = content[contentOffset + (x >> 3)] << (x & 4) & 240;
					int i = ((y == 0 ? 0 : frame[frameOffset - this.Width + x] & 15) + (y == this.Height - 1 ? 0 : frame[frameOffset + this.Width + x] & 15)) >> 1;
					frame[frameOffset + x] = (byte) (c | i);
					if (y < this.Height - 1)
						frame[frameOffset + this.Width + x] = (byte) (c | (frame[frameOffset + this.Width + x] & 15));
				}
				Array.Clear(frame, frameOffset + this.Width, this.LeftSkip);
				contentOffset += contentStride;
			}
		}

		static int ToAtari8Char(int ascii)
		{
			switch (ascii & 96) {
			case 0:
				return ascii + 64;
			case 32:
			case 64:
				return ascii - 32;
			default:
				return ascii;
			}
		}

		void DecodeAtari8Gr0Line(byte[] characters, int charactersOffset, byte[] font, int fontOffset, byte[] frame, int frameOffset, int lines)
		{
			byte[] colors = new byte[2];
			colors[0] = this.GtiaColors[6];
			colors[1] = (byte) ((this.GtiaColors[6] & 240) | (this.GtiaColors[5] & 14));
			for (int y = 0; y < lines; y++) {
				for (int x = 0; x < this.Width; x++) {
					int ch = charactersOffset + (x >> 3);
					if (characters != null)
						ch = characters[ch];
					int b = GetAtari8Gr0Pixel(font, fontOffset, ch, x, y);
					if (lines == 10) {
						switch (((ch & 96) + y) >> 1) {
						case 4:
						case 20:
						case 36:
						case 48:
							b = ch >> 7;
							break;
						default:
							break;
						}
					}
					frame[frameOffset + x] = colors[b];
				}
				frameOffset += this.Width;
			}
		}

		void DecodeAtari8Gr0(byte[] characters, int charactersOffset, int charactersStride, byte[] font, int fontOffset, byte[] frame)
