				for (int x = 0; x < 8; x++) {
					int c = b >> (7 - x) & 1;
					if (c != 0)
						frame[frameOffset + x * 2 + 1] = frame[frameOffset + x * 2] = (byte) (multi ? frame[frameOffset + x * 2] | color : color);
				}
				frameOffset += this.Width;
			}
		}

