			if (!rle.Unpack(unpacked, 0, 1, 7680))
				return false;
			switch (rle.ReadByte()) {
			case 52:
			case 53:
				unpacked[7680] = 0;
				unpacked[7681] = 52;
				unpacked[7682] = (byte) (contentLength == 3494 ? 56 : 200);
				unpacked[7683] = (byte) (contentLength == 3494 ? 60 : 124);
				break;
			case 81:
				unpacked[7680] = 164;
				unpacked[7681] = 81;
				unpacked[7682] = 185;
				unpacked[7683] = 124;
				break;
			case 228:
				unpacked[7680] = 0;
				unpacked[7681] = 228;
				unpacked[7682] = 200;
				unpacked[7683] = 190;
				break;
			case 4:
				unpacked[7680] = 6;
				unpacked[7681] = 4;
				unpacked[7682] = 0;
				unpacked[7683] = 10;
				break;
			case 48:
				unpacked[7680] = 14;
				unpacked[7681] = 48;
				unpacked[7682] = 199;
				unpacked[7683] = 123;
				break;
			case 116:
				unpacked[7680] = 0;
				unpacked[7681] = 116;
				unpacked[7682] = 88;
				unpacked[7683] = 126;
				break;
			default:
				unpacked[7680] = 0;
				unpacked[7681] = 4;
				unpacked[7682] = 8;
				unpacked[7683] = 12;
				break;
			}
