		bool DecodeAtari8Koala(byte[] content, int contentOffset, int contentLength)
		{
			if (contentOffset + 22 >= contentLength)
				return false;
			int rows = content[contentOffset + 12];
			if (rows > 192)
				return false;
			XeKoalaStream rle = new XeKoalaStream { Content = content, ContentOffset = contentOffset, ContentLength = contentLength };
