			int height = content[10];
			if (sprites == 0 || sprites > 4 || shapes == 0 || shapes > 160 || height == 0 || height > 48 || 11 + totalShapes * height != contentLength)
				return false;
			if (true)
				totalShapes >>= 1;
			int rows = (totalShapes + 15) >> 4;
			if (rows == 1)
				SetSize(totalShapes * 20, height, RECOILResolution.Xe2x1);
			else {
