			byte[] frame1 = new byte[61440];
			byte[] frame2 = new byte[61440];
			int col1 = 15360;
			int col2 = 16640;
			for (int y = 0; y < 192; y++) {
				for (int x = 0; x < 320; x++) {
					int i = 320 * y + x;
					int bit = ~x & 7;
					switch (x) {
					case 94:
					case 166:
					case 214:
					case 262:
					case 306:
						col1++;
						break;
					case 46:
					case 142:
					case 190:
					case 238:
					case 286:
						col2++;
						break;
					default:
						break;
					}
					frame1[i] = (byte) (content[col1] & ((content[i >> 3] >> bit & 1) != 0 ? 240 : 254));
					frame2[i] = (byte) (content[col2] & ((content[7680 + (i >> 3)] >> bit & 1) != 0 ? 240 : 254));
				}
				col1++;
				col2++;
			}
			return ApplyAtari8PaletteBlend(frame1, frame2);
		}

