				}
				DecodeAtari8Gr7(bitmap, y * 40, frame, y * 640, 1);
			}
			return ApplyAtari8Palette(frame);
		}

		bool DecodeGad(byte[] content, int contentLength)
		{
			if (contentLength != 4325)
