				return false;
			int frames = content[8];
			int cols = content[9];
			int rows = content[10];
			int tiles = frames * cols * rows;
			if (contentLength < 11 + tiles || !SetSize(frames * cols << 3, rows << 3, RECOILResolution.Xe2x1))
				return false;
			int pixelsOffset = 0;
			for (int y = 0; y < rows << 3; y++) {
				for (int f = 0; f < frames; f++) {
					for (int x = 0; x < cols << 3; x++) {
						int c = content[11 + (f * rows + (y >> 3)) * cols + (x >> 3)];
						c = 11 + tiles + (c << 3) + (y & 7);
						if (c >= contentLength)
							return false;
						c = content[c] >> (~x & 6) & 3;
						this.Pixels[pixelsOffset++] = this.Atari8Palette[c << 2];
					}
				}
			}
			return true;
		}

		bool DecodeEnvisionCommon(byte[] content, int mode, int columns, int rows, int charactersOffset, int[] fontId2Offset)
		{
			int charWidth;
			int charHeight;
			RECOILResolution resolution;
			switch (mode) {
			case 2:
				charWidth = 8;
				charHeight = 8;
				resolution = RECOILResolution.Xe1x1;
				break;
			case 3:
				charWidth = 8;
				charHeight = 10;
				resolution = RECOILResolution.Xe1x1;
				break;
			case 4:
				charWidth = 8;
				charHeight = 8;
				resolution = RECOILResolution.Xe2x1;
				break;
			case 5:
				charWidth = 8;
				charHeight = 16;
				resolution = RECOILResolution.Xe2x2;
				break;
			case 6:
				charWidth = 16;
				charHeight = 8;
				resolution = RECOILResolution.Xe2x1;
				break;
			case 7:
				charWidth = 16;
				charHeight = 16;
				resolution = RECOILResolution.Xe2x2;
				break;
			default:
				return false;
			}
			if (!SetSize(columns * charWidth, rows * charHeight, resolution))
				return false;
			byte[] frame = new byte[this.Width * this.Height];
			for (int row = 0; row < rows; row++) {
				int fontOffset;
				if (fontId2Offset != null) {
					fontOffset = fontId2Offset[content[8 + columns * rows + 256 + row]];
					if (fontOffset == 0)
						return false;
				}
				else {
					fontOffset = 10 + columns * rows;
				}
				int frameOffset = row * charHeight * this.Width;
				switch (mode >> 1) {
				case 1:
					DecodeAtari8Gr0Line(content, charactersOffset, content, fontOffset, frame, frameOffset, charHeight);
					break;
				case 2:
					DecodeAtari8Gr12Line(content, charactersOffset, content, fontOffset, frame, frameOffset, mode & 1);
					break;
				case 3:
					DecodeAtari8Gr1Line(content, charactersOffset, content, fontOffset, frame, frameOffset, mode & 1);
					break;
				default:
					throw new NotImplementedException();
				}
				charactersOffset += columns;
			}
			ApplyAtari8Palette(frame);
			return true;
		}

		bool DecodeEnvision(byte[] content, int contentLength)
		{
			if (contentLength < 1505)
				return false;
			int columns = content[1] + 1;
			int rows = content[2] + 1;
			if (rows > 204)
				return false;
			int fontOffset = 8 + columns * rows + 463;
			if (contentLength < fontOffset || contentLength != fontOffset + content[fontOffset - 1] * 1033)
				return false;
			int[] fontId2Offset = new int[256];
			for (; fontOffset < contentLength; fontOffset += 1033)
				fontId2Offset[content[fontOffset]] = fontOffset + 1 + 8;
			SetPF0123Bak(content, 3);
			return DecodeEnvisionCommon(content, content[0] & 127, columns, rows, 8, fontId2Offset);
		}

		bool DecodeEnvisionPC(byte[] content, int contentLength)
		{
			if (contentLength < 1035 || content[2] >= 128)
				return false;
			int columns = content[1] | content[2] << 8;
			int rows = content[3] | content[4] << 8;
			int contentOffset = 10 + columns * rows + 1024;
			while (contentOffset < contentLength) {
				switch (content[contentOffset++]) {
				case 0:
					break;
				case 1:
					if (contentOffset + 6 >= contentLength || content[contentOffset + 1] >= 5 || content[contentOffset + 3] >= 5 || content[contentOffset + 5] >= 5)
						return false;
					contentOffset += (content[contentOffset] + (content[contentOffset + 1] << 8)) * (content[contentOffset + 2] + (content[contentOffset + 3] << 8)) * (content[contentOffset + 4] + (content[contentOffset + 5] << 8) + 1);
					break;
				case 2:
					contentOffset += columns * rows;
					break;
				case 3:
					contentOffset += 1027;
					break;
				default:
					return false;
				}
			}
			if (contentOffset > contentLength)
				return false;
			SetBakPF0123(content, 5);
			return DecodeEnvisionCommon(content, content[0], columns, rows, 10, null);
		}

		bool DecodeMcs(byte[] content, int contentLength)
		{
			if (contentLength != 10185)
				return false;
			SetSize(320, 192, RECOILResolution.Xe2x1);
			byte[] frame = new byte[61440];
			for (int y = 0; y < 192; y++) {
				int fontOffset = 9 + (y / 24 << 10);
				for (int x = 0; x < 320; x++) {
					int ch = content[8201 + (y >> 3) * 40 + (x >> 3)];
					int c;
					switch (content[fontOffset + ((ch & 127) << 3) + (y & 7)] >> (~x & 6) & 3) {
					case 0:
						c = x / 80;
						int pmgBit = (x >> 3) % 10;
						int pmgOffset;
						if (pmgBit < 8) {
							pmgBit = 7 - pmgBit;
							pmgOffset = 9305 + (c << 7);
						}
						else {
							pmgBit = c << 1 | (pmgBit ^ 9);
							pmgOffset = 9177;
						}
						if ((content[pmgOffset + (y >> 1)] >> pmgBit & 1) == 0)
							c = 8;
						break;
					case 1:
						c = 4;
						break;
					case 2:
						c = 5;
						break;
					default:
						c = 6 + (ch >> 7);
						break;
					}
					frame[y * 320 + x] = (byte) (content[c] & 254);
				}
			}
			return ApplyAtari8Palette(frame);
		}

		static int Gr12GtiaNibbleToGr8(int nibble, int ch, bool gtia10)
		{
			switch (nibble) {
			case 0:
			case 1:
			case 4:
			case 5:
				return 0;
			case 2:
			case 6:
				return 1;
			case 3:
			case 7:
				return (ch & 128) == 0 ? 2 : 3;
			case 8:
				return gtia10 ? 8 : 4;
			case 9:
				return 4;
			case 10:
				return 5;
			case 11:
				return (ch & 128) == 0 ? 6 : 7;
			case 12:
				return gtia10 || (ch & 128) == 0 ? 8 : 12;
			case 13:
				return (ch & 128) == 0 ? 8 : 12;
			case 14:
				return (ch & 128) == 0 ? 9 : 13;
			case 15:
				return (ch & 128) == 0 ? 10 : 15;
			default:
				return 0;
			}
		}

		static int Gr12GtiaByteToGr8(int b, int ch, bool gtia10)
		{
			return Gr12GtiaNibbleToGr8(b >> 4, ch, gtia10) << 4 | Gr12GtiaNibbleToGr8(b & 15, ch, gtia10);
		}

		const int IceFontFrame1 = -1;

