		bool DecodeIp2(byte[] content, int contentLength)
		{
			if (contentLength != 17358 || content[0] != 1)
				return false;
			SetSize(320, 192, RECOILResolution.Xe2x1);
			this.GtiaColors[8] = (byte) (content[1] & 254);
			this.GtiaColors[4] = (byte) (content[5] & 254);
			this.GtiaColors[5] = (byte) (content[7] & 254);
			this.GtiaColors[6] = (byte) (content[9] & 254);
			this.GtiaColors[7] = (byte) (content[11] & 254);
			byte[] frame1 = new byte[61440];
			DecodeIceFrame(content, 16398, 14, frame1, IceFrameMode.Gr12);
			this.LeftSkip = 2;
			for (int i = 0; i < 4; i++) {
				this.GtiaColors[i] = (byte) (content[1 + i] & 254);
				SetGtiaColor(4 + i, content[6 + i * 2]);
			}
			SetGtiaColor(8, content[13]);
			byte[] frame2 = new byte[61440];
			DecodeIceFrame(content, 16398, 1038, frame2, IceFrameMode.Gr0Gtia10);
			return ApplyAtari8PaletteBlend(frame1, frame2);
		}

		void DecodeAtari8RgbScreen(byte[] screens, int screensOffset, int color, byte[] frame)
		{
			if (this.Resolution == RECOILResolution.Xe4x1) {
				this.GtiaColors[8] = (byte) color;
				DecodeAtari8Gr9(screens, screensOffset, 40, frame, 0, this.Width, this.Width, this.Height);
			}
			else {
				this.GtiaColors[8] = 0;
				this.GtiaColors[4] = (byte) (color | 4);
				this.GtiaColors[5] = (byte) (color | 10);
				this.GtiaColors[6] = (byte) (color | 14);
				DecodeAtari8Gr15(screens, screensOffset, 40, frame, 0, this.Width, this.Height);
			}
		}

		bool DecodeAtari8Rgb(byte[] content, int contentLength)
		{
			if (contentLength < 9 || !IsStringAt(content, 0, "RGB1"))
				return false;
			int titleLength = content[4];
			if (contentLength < 9 + titleLength)
				return false;
			int width = content[6 + titleLength];
			int height = content[7 + titleLength];
			if (width == 0 || (width & 1) != 0 || width > 80 || height == 0 || height > 192 || content[8 + titleLength] != 1)
				return false;
			switch (content[5 + titleLength]) {
			case 9:
				SetSize(width << 2, height, RECOILResolution.Xe4x1);
				break;
			case 15:
				SetSize(width << 2, height, RECOILResolution.Xe2x1);
				break;
			default:
				return false;
			}
			int[] leftRgbs = new int[192];
			byte[] screens = new byte[23040];
			RgbStream rle = new RgbStream { Content = content, ContentOffset = 9 + titleLength, ContentLength = contentLength };
			for (int x = 0; x < width; x++) {
				for (int y = 0; y < height; y++) {
					int rgb = rle.ReadRle();
					if (rgb < 0)
						return false;
					if ((x & 1) == 0)
						leftRgbs[y] = rgb;
					else {
						int leftRgb = leftRgbs[y];
						int screenOffset = y * 40 + (x >> 1);
						screens[screenOffset] = (byte) ((leftRgb >> 4 & 240) | rgb >> 8);
						screens[7680 + screenOffset] = (byte) ((leftRgb & 240) | (rgb >> 4 & 15));
						screens[15360 + screenOffset] = (byte) ((leftRgb << 4 & 240) | (rgb & 15));
					}
				}
			}
			byte[] frame1 = new byte[61440];
			DecodeAtari8RgbScreen(screens, 0, 48, frame1);
			byte[] frame2 = new byte[61440];
			DecodeAtari8RgbScreen(screens, 7680, 192, frame2);
			byte[] frame3 = new byte[61440];
			DecodeAtari8RgbScreen(screens, 15360, 112, frame3);
			return ApplyAtari8PaletteBlend3(frame1, frame2, frame3);
		}

		bool DrawBlazingPaddlesVector(byte[] content, int contentLength, byte[] frame, int frameOffset, int index, int startAddress)
		{
			if (index * 2 + 1 >= contentLength)
				return false;
			int contentOffset = content[index * 2] + (content[index * 2 + 1] << 8) - startAddress;
			if (contentOffset < 0)
				return false;
			while (contentOffset < contentLength) {
				int control = content[contentOffset++];
				if (control == 8)
					return true;
				for (; control >= 0; control -= 16) {
					if ((control & 4) == 0)
						frame[frameOffset + 1] = frame[frameOffset] = 14;
					switch (control & 3) {
					case 0:
						frameOffset += 2;
						break;
					case 1:
						frameOffset -= 2;
						break;
					case 2:
						frameOffset -= this.Width;
						break;
					case 3:
						frameOffset += this.Width;
						break;
					default:
						throw new NotImplementedException();
					}
				}
			}
			return false;
		}

		bool DecodeBlazingPaddlesVectors(byte[] content, int contentLength, int startAddress)
		{
			int x = 0;
			int y = 0;
			int i;
			int lineI = 0;
			int lineTop = 0;
			int lineBottom = 0;
			int[] xs = new int[256];
			int[] ys = new int[256];
			int width = 0;
			BlazingPaddlesBoundingBox box = new BlazingPaddlesBoundingBox();
			for (i = 0; i < 256; i++) {
				if (!box.Calculate(content, contentLength, i, startAddress))
					break;
				int shapeWidth = box.Right - box.Left + 2;
				if (x + shapeWidth > 160) {
					y -= lineTop;
					while (lineI < i)
						ys[lineI++] = y;
					if (width < x)
						width = x;
					x = 0;
					y += lineBottom + 2;
					lineTop = box.Top;
					lineBottom = box.Bottom;
				}
				xs[i] = x - box.Left;
				x += shapeWidth;
				if (lineTop > box.Top)
					lineTop = box.Top;
				if (lineBottom < box.Bottom)
					lineBottom = box.Bottom;
			}
			y -= lineTop;
			while (lineI < i)
				ys[lineI++] = y;
			if (width < x)
				width = x;
			y += lineBottom + 1;
			if (i == 0 || width > 160 || y > 240)
				return false;
			SetSize(width << 1, y, RECOILResolution.Xe2x1);
			byte[] frame = new byte[76800];
			for (int j = 0; j < i; j++) {
				if (!DrawBlazingPaddlesVector(content, contentLength, frame, (ys[j] * width + xs[j]) << 1, j, startAddress))
					break;
			}
			return ApplyAtari8Palette(frame);
		}

		bool DecodeChr(byte[] content, int contentLength) { return contentLength == 3072 && DecodeBlazingPaddlesVectors(content, contentLength, 28672); }

		bool DecodeShp(byte[] content, int contentLength)
		{
			if (DecodeC64Shp(content, contentLength))
				return true;
			switch (contentLength) {
			case 1024:
				return DecodeBlazingPaddlesVectors(content, contentLength, 31744);
			case 4384:
				return DecodeGr7(content, 528, 3844);
			case 10018:
				return DecodeOcp(content, contentLength);
			default:
				return false;
			}
		}

		static void DrawSpcChar(byte[] pixels, int x1, int y1, int ch)
		{
			if (ch < 32 || ch > 95)
				return;
			byte[] font = FuResource.atari8_fnt;
			int fontOffset = (ch - 32) << 3;
			for (int y = 0; y < 8 && y1 + y < 192; y++) {
				for (int x = 0; x < 4 && x1 + x < 160; x++)
					pixels[(y1 + y) * 160 + x1 + x] = (byte) (font[fontOffset + y] >> (6 - x * 2) & 3);
			}
		}

		static void DrawSpcLine(byte[] pixels, int x1, int y1, int x2, int y2, int color)
		{
			int dx = Math.Abs(x2 - x1);
			int dy = Math.Abs(y2 - y1);
			if (dx >= dy) {
				int e = dx;
				if (x2 < x1) {
					int ty = y1;
					x1 = x2;
					x2 += dx;
					y1 = y2;
					y2 = ty;
				}
				for (; x1 <= x2; x1++) {
					if (x1 < 160 && y1 < 192)
						pixels[160 * y1 + x1] = (byte) color;
					e -= dy * 2;
					if (e < 0) {
						e += dx * 2;
						y1 += y1 < y2 ? 1 : -1;
					}
				}
			}
			else {
				int e = dy;
				if (y2 < y1) {
					int tx = x1;
					x1 = x2;
					x2 = tx;
					y1 = y2;
					y2 += dy;
				}
				for (; y1 <= y2; y1++) {
					if (x1 < 160 && y1 < 192)
						pixels[160 * y1 + x1] = (byte) color;
					e -= dx * 2;
					if (e < 0) {
						e += dy * 2;
						x1 += x1 < x2 ? 1 : -1;
					}
				}
			}
		}

		static void PlotSpcPattern(byte[] pixels, int x, int y, int pattern)
		{
			pixels[y * 160 + x] = (byte) (pattern >> (((~y & 1) << 3) + ((~x & 3) << 1)) & 3);
		}

		static void DrawSpcBrush(byte[] pixels, int x1, int y1, int brush, int pattern)
		{
			for (int y = 0; y < 16 && y1 + y < 192; y++) {
				int brushShape = DrawSpcBrush_brushes[brush * 16 + y];
				for (int x = 0; x < 8 && x1 + x < 160; x++) {
					if ((brushShape >> (7 - x) & 1) != 0)
						PlotSpcPattern(pixels, x, y, pattern);
				}
			}
		}

		static bool FillSpc(byte[] pixels, int x, int y, int pattern)
		{
			if (x >= 160 || y >= 192)
				return false;
			while (y >= 0 && pixels[y * 160 + x] == 0)
				y--;
			while (++y < 192 && pixels[y * 160 + x] == 0) {
				do
					x--;
				while (x >= 0 && pixels[y * 160 + x] == 0);
				int x1 = x;
				while (x < 159) {
					if (pixels[y * 160 + ++x] != 0)
						break;
					PlotSpcPattern(pixels, x, y, pattern);
				}
				x = x1 + ((x - x1 + 1) >> 1);
			}
			return true;
		}

		bool DecodeAtari8Spc(byte[] content, int contentLength)
		{
			if (contentLength < 3 || contentLength != content[0] + (content[1] << 8) + 3 || content[contentLength - 1] != 0)
				return false;
			byte[] pixels = new byte[30720];
			int[] lineColors = new int[96];
			int textX = 0;
			int textY = 0;
			int lineX = 0;
			int lineY = 0;
			int brush = 0;
			int pattern = 8840;
			int lineColor = 3;
			int x;
			int y;
			for (int contentOffset = 2; content[contentOffset] != 0;) {
				switch (content[contentOffset]) {
				case 16:
					if (contentOffset + 3 >= contentLength)
						return false;
					textX = content[contentOffset + 1];
					textY = content[contentOffset + 2];
					contentOffset += 3;
					break;
				case 32:
				case 33:
				case 34:
				case 35:
					if (contentOffset + 1 >= contentLength)
						return false;
					lineColor = content[contentOffset] & 3;
					contentOffset++;
					break;
				case 48:
				case 80:
					if (contentOffset + 2 >= contentLength)
						return false;
					DrawSpcChar(pixels, textX, textY, content[contentOffset + 1]);
					textX += 4;
					contentOffset += 2;
					break;
				case 64:
				case 65:
				case 66:
				case 67:
				case 68:
				case 69:
				case 70:
				case 71:
					if (contentOffset + 1 >= contentLength)
						return false;
					brush = content[contentOffset] & 7;
					contentOffset++;
					break;
				case 96:
					if (contentOffset + 2 >= contentLength)
						return false;
					pattern = content[contentOffset + 1];
					if (pattern >= 71)
						return false;
					pattern = DecodeAtari8Spc_patterns[pattern];
					contentOffset += 2;
					break;
				case 112:
					if (contentOffset + 7 >= contentLength)
						return false;
					for (y = content[contentOffset + 1]; y <= content[contentOffset + 2]; y++) {
						if (y >= 96)
							return false;
						lineColors[y] = contentOffset + 3;
					}
					contentOffset += 7;
					break;
				case 128:
					if (contentOffset + 3 >= contentLength)
						return false;
					lineX = content[contentOffset + 1];
					lineY = content[contentOffset + 2];
					contentOffset += 3;
					break;
				case 160:
					if (contentOffset + 3 >= contentLength)
						return false;
					x = content[contentOffset + 1];
					y = content[contentOffset + 2];
					DrawSpcLine(pixels, lineX, lineY, x, y, lineColor);
					lineX = x;
					lineY = y;
					contentOffset += 3;
					break;
				case 192:
					if (contentOffset + 3 >= contentLength)
						return false;
					DrawSpcBrush(pixels, content[contentOffset + 1], content[contentOffset + 2], brush, pattern);
					contentOffset += 3;
					break;
				case 224:
					if (contentOffset + 3 >= contentLength)
						return false;
					if (!FillSpc(pixels, content[contentOffset + 1], content[contentOffset + 2], pattern))
						return false;
					contentOffset += 3;
					break;
				default:
					return false;
				}
			}
			SetSize(320, 192, RECOILResolution.Xe2x1);
			byte[] frame = new byte[61440];
			for (y = 0; y < 192; y++) {
				int colorsOffset = lineColors[y >> 1];
				byte[] colors = colorsOffset == 0 ? DecodeAtari8Spc_defaultColors : content;
				for (x = 0; x < 160; x++) {
					int offset = y * 320 + x * 2;
					frame[offset + 1] = frame[offset] = (byte) (colors[colorsOffset + pixels[y * 160 + x]] & 254);
				}
			}
			return ApplyAtari8Palette(frame);
		}

		static bool GetMcmSprite(byte[] content, int x, int y)
		{
			if ((y & 7) == 0)
				return false;
			int b = content[11440 + GetMcmSprite_offsets[x >> 4] * 30 + (y >> 3)];
			return (b >> (GetMcmSprite_bits[x >> 4] ^ (x >> 3 & 1)) & 1) != 0;
		}

		bool DecodeMcm(byte[] content, int contentLength)
		{
			if (contentLength != 11626)
				return false;
			SetSize(320, 240, RECOILResolution.Xe2x1);
			byte[] frame = new byte[76800];
			for (int y = 0; y < 240; y++) {
				for (int x = 0; x < 320; x++) {
					int ch = content[10240 + (y & ~7) * 5 + (x >> 3)];
					int c;
					switch (content[(y / 24 << 10) + ((ch & 127) << 3) + (y & 7)] >> (~x & 6) & 3) {
					case 0:
						c = content[GetMcmSprite(content, x, y) ? 11625 : 11620];
						break;
					case 1:
						c = content[11621];
						break;
					case 2:
						c = content[11622];
						break;
					case 3:
						c = content[11623 + (ch >> 7)];
						if (GetMcmSprite(content, x, y))
							c |= content[11625];
						break;
					default:
						throw new NotImplementedException();
					}
					frame[y * 320 + x] = (byte) (c & 254);
				}
			}
			return ApplyAtari8Palette(frame);
		}

		bool DecodeHcm(byte[] content, int contentLength)
		{
			if (contentLength != 8208 || !IsStringAt(content, 0, "HCMA8") || content[5] != 1)
				return false;
			HcmRenderer gtia = new HcmRenderer();
			int leftSprite;
			switch (content[6]) {
			case 0:
				leftSprite = 2;
				gtia.Prior = 0;
				break;
			case 2:
				leftSprite = 1;
				gtia.Prior = 36;
				break;
			default:
				return false;
			}
			gtia.PlayerHpos[3] = gtia.PlayerHpos[3 - leftSprite] = 104;
			gtia.MissileHpos[leftSprite] = gtia.MissileHpos[0] = 136;
			gtia.MissileHpos[3] = gtia.MissileHpos[3 - leftSprite] = 144;
			for (int i = 0; i < 4; i++)
				gtia.MissileSize[i] = gtia.PlayerSize[i] = 4;
			gtia.Colors[8] = (byte) (content[7] & 254);
			gtia.Colors[3 - leftSprite] = gtia.Colors[0] = (byte) (content[8] & 254);
			gtia.Colors[3] = gtia.Colors[leftSprite] = (byte) (content[9] & 254);
			gtia.Colors[4] = (byte) (content[10] & 254);
			gtia.Colors[5] = (byte) (content[11] & 254);
			gtia.Colors[6] = (byte) (content[12] & 254);
			gtia.Content = content;
			gtia.PlayfieldColumns = 32;
			SetSize(256, 192, RECOILResolution.Xe2x1);
			byte[] frame = new byte[49152];
			for (int y = 0; y < 192; y++) {
				gtia.PlayerHpos[leftSprite] = gtia.PlayerHpos[0] = 72;
				gtia.ProcessSpriteDma(content, 816 + y);
				gtia.StartLine(64);
				gtia.DrawSpan(y, 64, 128, AnticMode.FourColor, frame, 256);
				gtia.PlayerHpos[leftSprite] = gtia.PlayerHpos[0] = 152;
				gtia.PlayerGraphics[0] = content[48 + y];
				gtia.PlayerGraphics[leftSprite] = content[304 + y];
				gtia.DrawSpan(y, 128, 192, AnticMode.FourColor, frame, 256);
			}
			return ApplyAtari8Palette(frame);
		}

		bool DecodeGed(byte[] content, int contentLength)
		{
			if (contentLength != 11302 || content[0] != 255 || content[1] != 255 || content[2] != 48 || content[3] != 83 || content[4] != 79 || content[5] != 127)
				return false;
			int cycle = content[3300];
			if (cycle > 7)
				return false;
			GedRenderer gtia = new GedRenderer();
			GtiaRenderer.SetSpriteSizes(gtia.MissileSize, content[3291]);
			gtia.Colors[7] = (byte) (content[3293] & 254);
			gtia.Colors[8] = (byte) (content[3294] & 254);
			int prior = content[3292];
			gtia.Prior = prior;
			for (int i = 0; i < 4; i++) {
				gtia.SetPlayerSize(i, content[3290] >> ((3 - i) << 1));
				gtia.PlayerHpos[i] = (byte) (48 + content[3295 + i]);
				gtia.MissileHpos[i] = (byte) ((prior & 16) == 0 ? gtia.PlayerHpos[i] + (gtia.PlayerSize[i] << 3) : i == 0 ? 48 + content[3299] : gtia.MissileHpos[i - 1] + (gtia.MissileSize[i - 1] << 1));
				gtia.Colors[i] = (byte) (content[3286 + i] & 254);
			}
			gtia.Content = content;
			gtia.PlayfieldColumns = 40;
			SetSize(320, 200, RECOILResolution.Xe2x1);
			byte[] frame = new byte[64000];
			for (int y = 0; y < 200; y++) {
				gtia.ProcessSpriteDma(content, 2034 + y);
				gtia.Poke(content[206 + y] & 31, content[6 + y]);
				gtia.Colors[4] = (byte) (content[406 + y] & 254);
				gtia.Colors[5] = (byte) (content[606 + y] & 254);
				gtia.Colors[6] = (byte) (content[806 + y] & 254);
				gtia.StartLine(48);
				int hpos = gtia.DrawSpan(y, 48, 63 + (cycle << 3), AnticMode.FourColor, frame, 320);
				gtia.Colors[4] = (byte) (content[1006 + y] & 254);
				hpos = gtia.DrawSpan(y, hpos, cycle < 4 ? hpos + 32 : 107 + (cycle << 2), AnticMode.FourColor, frame, 320);
				gtia.Colors[5] = (byte) (content[1206 + y] & 254);
				hpos = gtia.DrawSpan(y, hpos, 123 + (cycle << 2), AnticMode.FourColor, frame, 320);
				gtia.Colors[6] = (byte) (content[1406 + y] & 254);
				hpos = gtia.DrawSpan(y, hpos, hpos + 24, AnticMode.FourColor, frame, 320);
				gtia.Colors[4] = (byte) (content[1606 + y] & 254);
				hpos = gtia.DrawSpan(y, hpos, hpos + 24, AnticMode.FourColor, frame, 320);
				gtia.Colors[5] = (byte) (content[1806 + y] & 254);
				gtia.DrawSpan(y, hpos, 208, AnticMode.FourColor, frame, 320);
			}
			return ApplyAtari8Palette(frame);
		}

		bool DecodePgr(byte[] content, int contentLength)
		{
			if (contentLength < 1776 || 6 + ParseAtari8ExecutableHeader(content, 0) != contentLength || content[2] != 6 || content[3] != 130 || !IsStringAt(content, 8, "PowerGFX"))
				return false;
			PgrRenderer gtia = new PgrRenderer();
			for (int i = 0; i < 14; i++) {
				gtia.Poke(i, content[504 + i]);
				gtia.Poke(14 + i, content[760 + i]);
			}
			gtia.Content = content;
			int dmaCtl = content[774];
			switch (dmaCtl & 243) {
			case 49:
				gtia.PlayfieldColumns = 32;
				break;
			case 50:
				gtia.PlayfieldColumns = 40;
				break;
			default:
				return false;
			}
			int dlOffset = 16;
			int rasterOffset = content[6] + (content[7] << 8) - 33280;
			if (rasterOffset < 1536)
				return false;
			gtia.ScreenOffset = -1;
			int a = 0;
			byte[] frame = new byte[80640];
			RECOILResolution resolution = RECOILResolution.Xe4x1;
			for (int y = 0; y < 240; y++) {
				int hpos = -11;
				int dlOp = content[dlOffset++];
				switch (dlOp) {
				case 0:
				case 14:
				case 15:
					break;
				case 65:
					dlOffset--;
					break;
				case 78:
				case 79:
					hpos += 4;
					gtia.ScreenOffset = content[dlOffset] + (content[dlOffset + 1] << 8) - 33280;
					dlOffset += 2;
					break;
				default:
					return false;
				}
				AnticMode anticMode;
				switch (dlOp & 15) {
				case 14:
					anticMode = AnticMode.FourColor;
					if (resolution == RECOILResolution.Xe4x1 && gtia.Prior < 64)
						resolution = RECOILResolution.Xe2x1;
					break;
				case 15:
					anticMode = AnticMode.HiRes;
					if (gtia.Prior < 64)
						resolution = RECOILResolution.Xe1x1;
					break;
				default:
					anticMode = AnticMode.Blank;
					break;
				}
				if (anticMode != AnticMode.Blank && (gtia.ScreenOffset < 1536 || gtia.ScreenOffset + 40 > contentLength))
					return false;
				gtia.StartLine(44);
				if ((dmaCtl & 12) != 0) {
					hpos += 2;
					if ((dmaCtl & 4) != 0)
						gtia.MissileGraphics = content[264 + y];
					if ((dmaCtl & 8) != 0) {
						hpos += 8;
						gtia.ProcessPlayerDma(content, 520 + y);
					}
				}
				for (int cpuCycles = 1;;) {
					if (rasterOffset >= contentLength)
						return false;
					int rasterOp = content[rasterOffset++];
					if ((rasterOp & 32) != 0) {
						if (rasterOffset >= contentLength)
							return false;
						cpuCycles += 2;
						a = content[rasterOffset++];
					}
					int addr = rasterOp & 31;
					if (addr <= 27) {
						int untilHpos = gtia.AdvanceCpuCycles(hpos, cpuCycles, anticMode != AnticMode.Blank);
						gtia.DrawSpan(y, hpos >= 44 ? hpos : 44, untilHpos < 212 ? untilHpos : 212, anticMode, frame, 336);
						hpos = untilHpos;
						gtia.Poke(addr, a);
						if (rasterOp >= 128)
							break;
						cpuCycles = 4;
					}
					else {
						int nops = (rasterOp >> 6 & 3) | (rasterOp & 3) << 2;
						if (nops == 0)
							break;
						cpuCycles += nops << 1;
					}
				}
				gtia.DrawSpan(y, hpos >= 44 ? hpos : 44, 212, anticMode, frame, 336);
				if (anticMode != AnticMode.Blank)
					gtia.ScreenOffset += gtia.PlayfieldColumns;
			}
			SetSize(336, 240, resolution);
			return ApplyAtari8Palette(frame);
		}

		static bool HasG2fRaster(byte[] content, int contentOffset, int count, int hitClr)
		{
			do {
				switch (content[contentOffset]) {
				case 0:
				case 1:
				case 2:
				case 3:
				case 65:
				case 66:
				case 67:
				case 97:
				case 98:
				case 99:
					break;
				case 129:
				case 130:
				case 131:
					if (content[contentOffset + 1] != hitClr)
						return true;
					break;
				default:
					return true;
				}
				contentOffset += 2;
			}
			while (--count > 0);
			return false;
		}

		bool DecodeMch(byte[] content, int contentLength)
		{
			int columns;
			switch (contentLength) {
			case 9840:
			case 28673:
				columns = 32;
				break;
			case 12000:
			case 30833:
				columns = 40;
				break;
			case 14160:
			case 32993:
				columns = 48;
				break;
			default:
				return false;
			}
			int bitmapLength = columns * 270;
			bool sprites = contentLength > bitmapLength + 1200;
			AnticMode anticMode;
			switch (content[0] & 3) {
			case 0:
				if (sprites && HasG2fRaster(content, bitmapLength + 6080, 6960, 30))
					return false;
				anticMode = AnticMode.FiveColor;
				break;
			case 1:
				anticMode = AnticMode.FiveColor;
				break;
			case 2:
				if (sprites && HasG2fRaster(content, bitmapLength + 6080, 6960, 30))
					return false;
				anticMode = AnticMode.FourColor;
				break;
			default:
				return false;
			}
			RECOILResolution resolution;
			int gtiaMode = 0;
			switch (content[0] & 60) {
			case 0:
				anticMode = AnticMode.HiRes;
				resolution = RECOILResolution.Xe1x1;
				break;
			case 4:
				resolution = RECOILResolution.Xe2x1;
				break;
			case 8:
				anticMode = AnticMode.HiRes;
				resolution = RECOILResolution.Xe4x1;
				gtiaMode = 64;
				break;
			case 24:
				anticMode = AnticMode.HiRes;
				resolution = RECOILResolution.Xe4x1;
				gtiaMode = 128;
				break;
			case 40:
				anticMode = AnticMode.HiRes;
				resolution = RECOILResolution.Xe4x1;
				gtiaMode = 192;
				break;
			default:
				return false;
			}
			SetSize(336, 240, resolution);
			byte[] frame = new byte[80640];
			MchRenderer gtia = new MchRenderer();
			Array.Clear(gtia.PlayerHpos, 0, 4);
			Array.Clear(gtia.MissileHpos, 0, 4);
			Array.Clear(gtia.Colors, 0, 9);
			gtia.Prior = gtiaMode;
			gtia.Content = content;
			gtia.PlayfieldColumns = columns;
			gtia.DliPlus = false;
			for (int i = 0; i < bitmapLength; i += 9) {
				if ((content[i] & 64) != 0) {
					gtia.DliPlus = true;
					break;
				}
			}
			for (int y = 0; y < 240; y++) {
				int colorsOffset = bitmapLength + y;
				gtia.SetG2fColors(colorsOffset, 240, sprites ? 9 : 5, gtiaMode);
				if (sprites) {
					for (int i = 0; i < 4; i++) {
						gtia.PlayerHpos[i] = content[colorsOffset + (9 + i) * 240];
						gtia.MissileHpos[i] = content[colorsOffset + (13 + i) * 240];
					}
					GtiaRenderer.SetSpriteSizes(gtia.PlayerSize, content[colorsOffset + 4080]);
					GtiaRenderer.SetSpriteSizes(gtia.MissileSize, content[colorsOffset + 4320]);
					gtia.Prior = gtiaMode | content[colorsOffset + 4560];
					gtia.ProcessSpriteDma(content, colorsOffset + 4800);
				}
				gtia.StartLine(44);
				gtia.DrawSpan(y, 44, 212, anticMode, frame, 336);
			}
			return ApplyAtari8Palette(frame);
		}

		static bool G2fHasRaster(byte[] content, int contentOffset) { return HasG2fRaster(content, contentOffset, 2880, content[0] < 128 ? 22 : 30); }

		bool DecodeG2fUnpacked(byte[] content, int contentLength, byte[] frame, int yOffset)
		{
			if (contentLength < 155711)
				return false;
			int columns = content[0] & 127;
			switch (columns) {
			case 32:
			case 40:
			case 48:
				break;
			default:
				return false;
			}
			int fontsOffset = 3 + 30 * columns;
			int fontNumberOffset = fontsOffset + (((content[2] & 127) + 1) << 10);
			if (contentLength < fontNumberOffset + 153724)
				return false;
			bool charMode;
			int vbxeOffset = fontNumberOffset + 155231;
			int inverse2Offset = -1;
			switch (content[fontNumberOffset + 147679] & 127) {
			case 1:
				if (G2fHasRaster(content, fontNumberOffset + 147934))
					return false;
				charMode = true;
				break;
			case 2:
				charMode = true;
				break;
			case 3:
				if (G2fHasRaster(content, fontNumberOffset + 147934))
					return false;
				charMode = false;
				break;
			case 66:
				charMode = true;
				inverse2Offset = vbxeOffset + 138244;
				if (contentLength < inverse2Offset + 30 * columns)
					return false;
				break;
			default:
				return false;
			}
			if (contentLength < vbxeOffset + 138243)
				vbxeOffset = -1;
			else {
				switch (content[vbxeOffset]) {
				case 0:
					vbxeOffset = -1;
					break;
				case 1:
					if (content[vbxeOffset + 1] != 8 || content[vbxeOffset + 2] == 0)
						return false;
					this.Resolution = RECOILResolution.Vbxe2x1;
					break;
				default:
					return false;
				}
			}
			G2fRenderer gtia = new G2fRenderer { Content = content, PlayfieldColumns = columns, Inverse2Offset = inverse2Offset, VbxeOffset = vbxeOffset };
			for (int y = 0; y < 240; y++) {
				int row = y >> 3;
				gtia.FontOffset = fontsOffset + ((content[fontNumberOffset + row] & 127) << 10);
				if (gtia.FontOffset >= fontNumberOffset)
					return false;
				int spriteOffset = fontNumberOffset + 2334 + (y << 1);
				int prior = content[spriteOffset + 1] >> 4 & 7;
				if (prior >= 5)
					return false;
				prior = DecodeG2fUnpacked_priors[prior] | (content[spriteOffset + 1025] & 48);
				AnticMode anticMode;
				switch (content[fontNumberOffset + 153694 + row]) {
				case 1:
					this.Resolution = this.Resolution == RECOILResolution.Vbxe2x1 || this.Resolution == RECOILResolution.Vbxe1x1 ? RECOILResolution.Vbxe1x1 : RECOILResolution.Xe1x1;
					anticMode = AnticMode.HiRes;
					break;
				case 2:
					if (this.Resolution == RECOILResolution.Xe4x1)
						this.Resolution = RECOILResolution.Xe2x1;
					anticMode = charMode ? AnticMode.FiveColor : AnticMode.FourColor;
					break;
				case 4:
					prior |= DecodeG2fUnpacked_gtiaModes[content[1] & 7];
					anticMode = AnticMode.HiRes;
					break;
				case 255:
					anticMode = AnticMode.Blank;
					break;
				default:
					return false;
				}
				int colorsOffset = fontNumberOffset + 30 + y;
				gtia.SetG2fColors(colorsOffset, 256, 9, prior);
				int missileGraphics = 0;
				for (int i = 0; i < 4; i++) {
					if (!G2fRenderer.SetSprite(gtia.PlayerHpos, gtia.PlayerSize, i, content, spriteOffset) || !G2fRenderer.SetSprite(gtia.MissileHpos, gtia.MissileSize, i, content, spriteOffset + 512))
						return false;
					gtia.PlayerGraphics[i] = content[colorsOffset + 6400 + (i << 9)];
					missileGraphics |= content[colorsOffset + 6656 + (i << 9)] >> 6 << (i << 1);
				}
				gtia.MissileGraphics = missileGraphics;
				gtia.Prior = prior;
				gtia.StartLine(44);
				gtia.DrawSpan(y, 44, 212, anticMode, frame, 336, yOffset);
			}
			return true;
		}

		const int G2fMaxUnpackedLength = 327078;

		bool DecodeG2fFrame(byte[] content, int contentLength, byte[] frame, int yOffset)
		{
			if (contentLength < 11)
				return false;
			if (IsStringAt(content, 0, "G2FZLIB")) {
				byte[] unpacked = new byte[327078];
				InflateStream stream = new InflateStream { Content = content, ContentOffset = 7, ContentLength = contentLength };
				contentLength = stream.Uncompress(unpacked, 327078);
				return DecodeG2fUnpacked(unpacked, contentLength, frame, yOffset);
			}
			return DecodeG2fUnpacked(content, contentLength, frame, yOffset);
		}

		bool DecodeG2f(byte[] content, int contentLength)
		{
			byte[] frame = new byte[80640];
			this.Resolution = RECOILResolution.Xe4x1;
			if (!DecodeG2fFrame(content, contentLength, frame, 0))
				return false;
			SetSize(336, 240, this.Resolution);
			return ApplyAtari8Palette(frame);
		}

		bool DecodeVsc(string vscFilename, byte[] content, int contentLength)
		{
			Stream s = new Stream { Content = content, ContentOffset = 0, ContentLength = contentLength };
			int height = 0;
			for (;;) {
				int c = s.ReadByte();
				if (c < 0)
					break;
				switch (c) {
				case '\r':
					if (s.ReadByte() != '\n')
						return false;
					height += 240;
					break;
				case '/':
				case ':':
				case '\\':
					return false;
				default:
					if (c < ' ' || c > '~')
						return false;
					break;
				}
			}
			byte[] frame = new byte[336 * height];
			byte[] g2f = new byte[327078];
			s.ContentOffset = 0;
			this.Resolution = RECOILResolution.Xe4x1;
			for (height = 0;; height += 240) {
				int filenameOffset = s.ContentOffset;
				if (!s.SkipUntilByte('\n'))
					break;
				string filename = Encoding.UTF8.GetString(content, filenameOffset, s.ContentOffset - 2 - filenameOffset);
				contentLength = ReadSiblingFile(vscFilename, filename, g2f, 327078);
				if (!DecodeG2fFrame(g2f, contentLength, frame, height))
					return false;
			}
			return SetSize(336, height, this.Resolution) && ApplyAtari8Palette(frame);
		}

		bool DecodeDap(byte[] content, int contentLength)
		{
			if (contentLength != 77568)
				return false;
			SetSize(320, 240, RECOILResolution.Vbxe1x1);
			for (int i = 0; i < 256; i++)
				this.ContentPalette[i] = content[76800 + i] << 16 | content[77056 + i] << 8 | content[77312 + i];
			DecodeBytes(content, 0);
			return true;
		}

		bool DecodeTandyPnt(byte[] content, int contentLength)
		{
			if (contentLength < 236 || content[0] != 19 || content[1] != 'P' || content[2] != 'N' || content[3] != 'T')
				return false;
			SetSize(312, 176, RECOILResolution.Tandy1x1);
			if (contentLength == 27478) {
				Array.Copy(DecodeTandyPnt_palette, 0, this.ContentPalette, 0, 16);
				DecodeNibbles(content, 22, 156);
				return true;
			}
			int contentOffset = 22;
			int repeatCount = 1;
			int repeatValue = 0;
			for (int pixelsOffset = 0; pixelsOffset < 54912; pixelsOffset += 2) {
				if (--repeatCount == 0) {
					if (contentOffset + 1 >= contentLength)
						return false;
					repeatCount = content[contentOffset + 1];
					if (repeatCount == 0)
						return false;
					repeatValue = content[contentOffset];
					contentOffset += 2;
				}
				this.Pixels[pixelsOffset] = DecodeTandyPnt_palette[repeatValue >> 4];
				this.Pixels[pixelsOffset + 1] = DecodeTandyPnt_palette[repeatValue & 15];
			}
			return contentOffset == contentLength;
		}

		bool DecodeHs2(byte[] content, int contentLength)
		{
			if (contentLength % 105 != 0)
				return false;
			return SetSize(840, contentLength / 105, RECOILResolution.Pc1x1) && DecodeBlackAndWhite(content, 0, contentLength, false, 0);
		}

		bool DecodeImage72Fnt(byte[] content, int contentLength)
		{
			if (contentLength < 4 || content[0] != 0 || content[1] != 8)
				return false;
			int fontHeight = content[2];
			if (contentLength != 3 + (fontHeight << 8))
				return false;
			SetSize(256, fontHeight << 3, RECOILResolution.Pc1x1);
			DecodeBlackAndWhiteFont(content, 3, contentLength, fontHeight);
			return true;
