		bool DecodeMsp(byte[] content, int contentLength)
		{
			if (contentLength < 32)
				return false;
			int width = content[4] | content[5] << 8;
			int height = content[6] | content[7] << 8;
			if (IsStringAt(content, 0, "DanM"))
				return SetSize(width, height, RECOILResolution.Pc1x1) && DecodeBlackAndWhite(content, 32, contentLength, false, 0);
			if (IsStringAt(content, 0, "LinS") && SetSize(width, height, RECOILResolution.Pc1x1)) {
				MspStream rle = new MspStream { Content = content, ContentOffset = 32 + (height << 1), ContentLength = contentLength };
				return DecodeRleBlackAndWhite(rle, 0);
			}
			return false;
		}

		bool DecodeAwbmPalette(byte[] content, int contentLength, int paletteOffset, int colors)
		{
			if (contentLength < paletteOffset + 4 + colors * 3 || !IsStringAt(content, paletteOffset, "RGB "))
				return false;
			for (int i = 0; i < colors; i++) {
				int rgb = GetR8G8B8Color(content, paletteOffset + 4 + i * 3);
				this.ContentPalette[i] = (rgb & 4144959) << 2 | (rgb >> 4 & 197379);
			}
			return true;
		}

		bool DecodeAwbm(byte[] content, int contentLength)
		{
			int width = content[4] | content[5] << 8;
			int height = content[6] | content[7] << 8;
			if (!SetSize(width, height, RECOILResolution.Pc1x1))
				return false;
			if (DecodeAwbmPalette(content, contentLength, 8 + width * height, 256)) {
				DecodeBytes(content, 8);
				return true;
			}
			int planeStride = (width + 7) >> 3;
			if (!DecodeAwbmPalette(content, contentLength, 8 + (height * planeStride << 2), 16))
				return false;
			for (int y = 0; y < height; y++) {
				for (int x = 0; x < width; x++)
					this.Pixels[y * width + x] = this.ContentPalette[GetBitplanePixel(content, 8 + (y * planeStride << 2) + (x >> 3), x, 4, planeStride)];
			}
			return true;
		}

		static readonly int[] CgaPalette = { 0, 170, 43520, 43690, 11141120, 11141290, 11162880, 11184810, 5592405, 5592575, 5635925, 5636095, 16733525, 16733695, 16777045, 16777215 };

		bool DecodeEpa(byte[] content, int contentLength)
		{
			if (contentLength < 17)
				return false;
			if (IsStringAt(content, 0, "AWBM"))
				return DecodeAwbm(content, contentLength);
			int columns = content[0];
			int rows = content[1];
			if (columns > 80 || rows > 25 || contentLength != 2 + columns * rows * 15 + 70)
				return false;
			int width = columns * 8;
			int height = rows * 14;
			SetSize(width, height, RECOILResolution.Pc1x1);
			int bitmapOffset = 2 + columns * rows;
			for (int y = 0; y < height; y++) {
				for (int x = 0; x < width; x++) {
					int ch = y / 14 * columns + (x >> 3);
					int attribute = content[2 + ch];
					int b = content[bitmapOffset + ch * 14 + y % 14] >> (~x & 7) & 1;
					this.Pixels[y * width + x] = CgaPalette[b == 0 ? attribute >> 4 : attribute & 15];
				}
			}
			return true;
		}

		void DecodeBkMono(byte[] content, int height)
		{
			for (int y = 0; y < height; y++) {
				for (int x = 0; x < 512; x++) {
					int c = content[(y >> 1 << 6) + (x >> 3)] >> (x & 7) & 1;
					if (c != 0)
						c = 16777215;
					this.Pixels[(y << 9) + x] = c;
				}
			}
		}

		void DecodeBkColorFrame(byte[] content, int paletteOffset, int frame)
		{
			paletteOffset <<= 2;
			for (int i = 0; i < 65536; i++) {
				this.Pixels[(frame << 16) + i] = DecodeBkColorFrame_palette[paletteOffset + (content[(frame << 14) + (i >> 2)] >> ((i & 3) << 1) & 3)];
			}
		}

		bool DecodeBkColor(byte[] content, int palette)
		{
			SetSize(256, 256, RECOILResolution.Bk1x1);
			DecodeBkColorFrame(content, palette, 0);
			return true;
		}

		bool DecodeBks(byte[] content, int contentLength)
		{
			switch (contentLength) {
			case 16384:
				if (!SetSize(512, 512, RECOILResolution.Bk1x2))
					return false;
				DecodeBkMono(content, 512);
				return true;
			case 16385:
				int palette = content[16384];
				if (palette > 15)
					return false;
				return DecodeBkColor(content, palette);
			case 32768:
				if (!SetSize(512, 512, RECOILResolution.Bk1x2, 2))
					return false;
				DecodeBkMono(content, 1024);
				return ApplyBlend();
			case 32770:
				int palette1 = content[32768];
				int palette2 = content[32769];
				if (palette1 > 15 || palette2 > 15)
					return false;
				SetSize(256, 256, RECOILResolution.Bk1x1, 2);
				DecodeBkColorFrame(content, palette1, 0);
				DecodeBkColorFrame(content, palette2, 1);
				return ApplyBlend();
			default:
				return false;
			}
		}

		bool DecodeVectorSpr(byte[] content, int contentLength)
		{
			VectorSprStream rle = new VectorSprStream { Content = content, ContentOffset = contentLength };
			byte[] unpacked = new byte[32768];
			if (!rle.Unpack(unpacked, 0, 1, 32768))
				return false;
			for (int i = 0; i < 16; i++) {
