		static bool IsPaint256(string filename)
		{
			int i = filename.Length - 10;
			if (i < 0)
				return false;
			if (i > 0 && filename[i - 1] != '/' && filename[i - 1] != '\\')
				return false;
			return (filename[i] | 32) == 'p' && (filename[i + 1] | 32) == 'a' && (filename[i + 2] | 32) == 'i' && (filename[i + 3] | 32) == 'n' && (filename[i + 4] | 32) == 't' && filename[i + 5] != '/' && filename[i + 5] != '\\';
		}

		bool DecodePic(string filename, byte[] content, int contentLength)
		{
			if (DecodePsion3Pic(content, contentLength) || DecodeX68KPic(content, contentLength) || DecodeAtari8Koala(content, 0, contentLength))
				return true;
			switch (contentLength) {
			case 3325:
				return DecodeVisualizer(content);
			case 4325:
				return DecodeGad(content, contentLength);
			case 7680:
				return IsPaint256(filename) ? Decode256(content, contentLength) : DecodeGr8(content, contentLength);
			case 7681:
			case 7682:
			case 7683:
			case 7684:
			case 7685:
				return DecodeMic(null, content, contentLength);
			case 16384:
				return DecodeBkColor(content, 0);
			case 32000:
				return DecodeDoo(content, contentLength);
			case 32768:
				return DecodeAppleIIShr(content, contentLength);
			default:
				return DecodeStPi(content, contentLength) || DecodeSc8(null, content, contentLength);
			}
		}

		bool DecodeScr(string filename, byte[] content, int contentLength)
		{
			switch (contentLength) {
			case 960:
