			case 1002:
				return DecodeScrCol(filename, content, contentLength);
			case 6144:
				SetZx(RECOILResolution.Spectrum1x1);
				DecodeZx(content, 0, -1, -3, 0);
				return true;
			case 6160:
				return DecodeAmstradScr(filename, content, contentLength) || DecodeRad(content, contentLength);
			case 6912:
			case 6913:
				SetZx(RECOILResolution.Spectrum1x1);
				DecodeZx(content, 0, 6144, 3, 0);
				return true;
			case 6976:
				SetUlaPlus(RECOILResolution.SpectrumUlaPlus1x1, content, 6912, 64);
				DecodeZx(content, 0, 6144, 3, 0);
				return true;
			case 12288:
				return DecodeThc(content, contentLength);
			case 12289:
				return DecodeThr(content, contentLength);
			case 12352:
				return DecodeTcu(content, contentLength);
			case 13824:
				return DecodeGsc(content, contentLength);
			case 13825:
				return DecodeSkl(content, contentLength);
			case 15360:
				return DecodeHrc(content, contentLength);
			case 15456:
				return DecodeHrx(content, contentLength);
			case 16000:
				if (DecodeAmstradScr(filename, content, contentLength))
					return true;
				SetSize(640, 400, RECOILResolution.Mc05151x2);
				this.ContentPalette[0] = 0;
				this.ContentPalette[1] = 16777215;
				DecodeScaledBitplanes(content, 0, 640, 200, 1, false, null);
				return true;
			case 30720:
				return DecodeHgs(content, contentLength);
			case 30721:
				return DecodeHkl(content, contentLength);
			case 30913:
				return DecodeXkl(content, contentLength);
			case 32768:
				return DecodeAppleIIShr(content, contentLength);
			default:
				return DecodeAmstradScr(filename, content, contentLength);
			}
		}

		bool DecodeFlfFont(byte[] content, int contentOffset, int contentLength, int columns, int rows, RECOILResolution resolution, int[] palette, int colors, int xMask, int cMask)
		{
			if (contentLength != contentOffset + columns * rows * 12)
				return false;
			int width = columns << 3;
			int height = rows << 3;
			SetSize(width, height, resolution);
			for (int y = 0; y < height; y++) {
				for (int x = 0; x < width; x++) {
					int offset = contentOffset + ((y >> 3) * columns + (x >> 3)) * 12;
					int c = content[offset + (y & 7)] >> (x & xMask) & cMask;
					c = content[offset + 8 + c];
					if (c >= colors)
						return false;
					this.Pixels[y * width + x] = palette[c];
				}
			}
			return true;
		}

		bool DecodeFlfBytes(byte[] content, int contentLength)
		{
			int colorsOffset = 14 + 320 * this.Height;
			if (contentLength < colorsOffset + 6)
				return false;
			int colors = content[colorsOffset - 1];
			if (colors == 0)
				colors = 256;
			switch (contentLength - colorsOffset - colors * 3) {
			case 0:
			case 256:
				break;
			default:
				return false;
			}
			DecodeR8G8B8Colors(content, colorsOffset, colors, this.ContentPalette, 0);
			DecodeBytes(content, 13);
			return true;
		}

		bool DecodeFlf(byte[] content, int contentLength)
		{
			if (contentLength < 20 || !IsStringAt(content, 0, "FLUFF64"))
				return false;
			Array.Clear(this.ContentPalette, 0, 256);
			switch (content[11]) {
			case 1:
				return DecodeFlfFont(content, 15, contentLength, 40, 25, RECOILResolution.C642x1, this.C64Palette, 16, 6, 3);
			case 4:
			case 5:
				return DecodeFlfFont(content, 18, contentLength, 40, 25, RECOILResolution.C642x1, this.C64Palette, 16, 6, 3);
			case 6:
				return DecodeFlfFont(content, 18, contentLength, 40, 25, RECOILResolution.C641x1, this.C64Palette, 16, 7, 1);
			case 7:
				int columns = content[15];
				int rows = content[16];
				int length = columns * rows;
				return contentLength >= 45 + (length << 1) && DecodePetScreen(content, 29 + length, 29, content[13], columns, rows);
			case 9:
				if (content[12] != 6)
					return false;
				return DecodeFlfFont(content, 20, contentLength, content[18], content[19], RECOILResolution.Vic202x1, Vic20Palette, 8, 6, 3);
			case 11:
				if (contentLength != 64269)
					return false;
				int c;
				switch (content[12]) {
				case 2:
					c = 1;
					break;
				case 3:
					c = 9;
					break;
				case 4:
					c = 0;
					break;
				case 5:
					c = 8;
					break;
				default:
					return false;
				}
				this.ContentPalette[1] = CgaPalette[c + 2];
				this.ContentPalette[2] = CgaPalette[c + 4];
				this.ContentPalette[3] = CgaPalette[c + 6];
				SetSize(320, 200, RECOILResolution.Pc1x1);
				DecodeBytes(content, 13);
				return true;
			case 12:
				SetSize(320, 200, RECOILResolution.Amiga1x1);
				return DecodeFlfBytes(content, contentLength);
			case 13:
				SetSize(320, 256, RECOILResolution.Amiga1x1);
				return DecodeFlfBytes(content, contentLength);
			case 22:
				SetSize(320, 200, RECOILResolution.St1x1);
				return DecodeFlfBytes(content, contentLength);
			case 24:
				if (content[12] != 11 || contentLength != 32269)
					return false;
				SetAmstradFirmwarePalette(content, 32205, 16);
				SetSize(320, 200, RECOILResolution.Amstrad2x1);
				DecodeBytes(content, 13);
				return true;
			case 25:
				if (content[12] != 11 || contentLength < 282)
					return false;
				int width = Get32LittleEndian(content, 13);
				int height = Get32LittleEndian(content, 17);
				if (Get32LittleEndian(content, 21) != 0 || !SetSize(width << 1, height, RECOILResolution.Amstrad2x1) || contentLength != 281 + width * height)
					return false;
				SetAmstradFirmwarePalette(content, contentLength - 64, 16);
				DecodeBytes(content, 25);
				return true;
			case 26:
				if (content[12] != 12)
					return false;
				switch (content[13]) {
				case 4:
					if (contentLength != 82190)
						return false;
					this.ContentPalette[1] = 16777215;
					SetSize(320, 256, RECOILResolution.Bbc1x1);
					DecodeBytes(content, 13);
					return true;
				case 5:
					if (contentLength != 41230)
						return false;
					Array.Copy(BbcPalette2Bit, 0, this.ContentPalette, 0, 4);
					SetSize(320, 256, RECOILResolution.Bbc2x1);
					DecodeBytes(content, 13);
					return true;
				default:
					return false;
				}
			case 27:
				SetSize(320, 200, RECOILResolution.Pc1x1);
				return DecodeFlfBytes(content, contentLength);
			case 28:
				if (content[12] != 14 || contentLength < 49165)
					return false;
				SetZx(RECOILResolution.Spectrum1x1);
				DecodeBytes(content, 13);
				return true;
			default:
				return false;
			}
		}

