		/// <summary>Returns the number of alternating frames the pictures is composed of.</summary>
		/// <remarks>
		/// <list type="bullet">
		/// <item>1 means the picture doesn't flicker.</item>
		/// <item>2 means the picture is displayed by quickly alternating two sub-pictures.</item>
		/// <item>3 means the picture is displayed by alternating three sub-pictures.</item>
		/// </list></remarks>
		public int GetFrames() { return this.Frames; }

		byte[] ColorInUse = null;

		int Colors;

		const int UnknownColors = -1;

		readonly int[] Palette = new int[256];

		byte[] Indexes = null;

		int IndexesLength = 0;

		/// <summary>Calculates palette for the decoded picture.</summary>
		void CalculatePalette()
		{
			if (this.ColorInUse == null)
				this.ColorInUse = new byte[2097152];
			Array.Clear(this.ColorInUse, 0, 2097152);
			this.Colors = 0;
			Array.Clear(this.Palette, 0, 256);
			int pixelsCount = this.Width * this.Height;
			for (int pixelsOffset = 0; pixelsOffset < pixelsCount; pixelsOffset++) {
				int rgb = this.Pixels[pixelsOffset];
				int i = rgb >> 3;
				int mask = 1 << (rgb & 7);
				if ((this.ColorInUse[i] & mask) == 0) {
					this.ColorInUse[i] |= (byte) mask;
					if (this.Colors < 256)
						this.Palette[this.Colors] = rgb;
					this.Colors++;
				}
			}
		}

		/// <summary>Returns number of unique colors in the decoded picture.</summary>
		public int GetColors()
		{
			if (this.Colors == -1)
				CalculatePalette();
			return this.Colors;
		}

		/// <summary>Find the index of the <c>rgb</c> color in the sorted palette.</summary>
		int FindInSortedPalette(int rgb)
		{
			int left = 0;
			int right = this.Colors;
			while (left < right) {
				int index = (left + right) >> 1;
				int paletteRgb = this.Palette[index];
				if (rgb == paletteRgb)
					return index;
				if (rgb < paletteRgb)
					right = index;
				else
					left = index + 1;
			}
			return 0;
		}

		/// <summary>Converts the decoded picture to palette-indexed.</summary>
		/// <remarks>Returns palette of 256 0xRRGGBB entries.
		/// Call <c>GetColors()</c> for the actual number of colors.
		/// Returns <see langword="null" /> if conversion fails,
		/// because there are more than 256 colors.</remarks>
		public int[] ToPalette()
		{
			if (this.Colors == -1)
				CalculatePalette();
			if (this.Colors > 256)
				return null;
			Array.Sort(this.Palette, 0, this.Colors);
			int pixelsLength = this.Width * this.Height;
			if (this.IndexesLength < pixelsLength) {
				this.IndexesLength = pixelsLength;
				this.Indexes = new byte[pixelsLength];
			}
			for (int i = 0; i < pixelsLength; i++)
				this.Indexes[i] = (byte) FindInSortedPalette(this.Pixels[i]);
			return this.Palette;
		}

